import type { Key } from '../engine';

const KEY: Key[] = JSON.parse("[{\"id\":260,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, какая работа требует дыхательной маски и что может происходить с человеком на большой глубине.\",\"Что происходит с человеком, который дышит сжатым воздухом на глубине 60 метров и более?\"],\"short\":\"Водолаз на глубине: азотный наркоз помутил разум, и ему показалось, что маска бесполезна.\",\"answer\":\"Мужчина был водолазом. При дыхании сжатым воздухом на большой глубине (60 метров и более) проявляется так называемый «азотный наркоз». Человек возбуждается, теряет чувство реальности, и ему кажется, что маска совершенно бесполезна и её нужно выбросить.\"},{\"id\":261,\"book\":\"zagadki\",\"lv\":1,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, кем работал уволенный и что входило в его обязанности ночью.\",\"Что значит, что человек видел сон ночью, если по работе ему не полагалось спать?\"],\"short\":\"Начальник прав: ночной сторож должен был бодрствовать, а раз он видел сон, значит, спал на посту.\",\"answer\":\"Уволенный работал ночным сторожем. Он должен был бодрствовать всю ночь и выполнять свои обязанности. Однако, если он видел сон, значит, спал. Поэтому его и уволили.\"},{\"id\":262,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Обрати внимание на то, что каждый из друзей приносил с собой в баню.\",\"Какой острый предмет можно пронести в термосе и потом растопить, не оставив следов?\"],\"short\":\"Александр: он принёс в термосе осколок льда, которым убил Павла, а лёд растаял без следов.\",\"answer\":\"Павла убил Александр. Он принёс осколок льда в термосе. Лёд растаял и не оставил никаких следов.\"},{\"id\":263,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к тому, где именно стоял дом вора и где проходят границы.\",\"Что будет, если граница двух стран проходит прямо через дом вора?\"],\"short\":\"Дом стоял на границе: спальня была в Колумбии, куда венесуэльская полиция не имела права войти.\",\"answer\":\"Его дом стоял на границе Венесуэлы и Колумбии. Входная дверь и кухня были на территории Венесуэлы, спальня — на территории Колумбии.\"},{\"id\":264,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Подумай, почему люди внизу спокойно смотрели на происходящее и не вмешивались.\",\"Кто обычно отвечает за страховку того, кто падает на съёмках?\"],\"short\":\"Ответственного за страховку каскадера: падение снимали для фильма, а мужчина был каскадером.\",\"answer\":\"На крыше дома снимали фильм, а мужчина был каскадером. В его смерти был обвинён человек, который отвечал за страховку каскадера.\"},{\"id\":265,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Подумай, кого из присутствующих женщина могла назвать по имени и кто из них был мужчиной.\",\"Кого женщина умоляла, назвав по имени, и кто из присутствующих мог носить такое имя?\"],\"short\":\"Учитель: женщина назвала убийцу Лёшей, а юрист и врач были женщинами.\",\"answer\":\"Юрист и врач были женщинами — следовательно, они не могли иметь имя Леша.\"},{\"id\":266,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к куску бинта и подумай, о каком состоянии здоровья он может говорить.\",\"Что делает человек с повязкой, когда хочет проверить, видит ли он?\"],\"short\":\"Он только что лечился от слепоты, снял повязку, ничего не увидел и решил, что лечение не помогло.\",\"answer\":\"Человек только что закончил лечение от слепоты. Он решил сам снять повязку, чтобы проверить зрение. Когда он снял повязку, то ничего не увидел — и решил, что не вылечился. Он не мог представить себе будущее без зрения и поэтому выпрыгнул из поезда.\"},{\"id\":267,\"book\":\"zagadki\",\"lv\":3,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к тому, что Александр сказал раньше, чем милиционер назвал имя погибшего.\",\"Кого Александр назвал по имени, хотя милиционер ни разу не произнёс имени погибшего?\"],\"short\":\"Александр назвал погибшего по имени «Миша», хотя милиционер его имени не называл.\",\"answer\":\"Александр точно знал, какой из братьев его жены убит. Это было подозрительно, ведь милиционер не назвал ему имени убитого.\"},{\"id\":268,\"book\":\"zagadki\",\"lv\":1,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, в каких случаях у закона нет возможности наказать преступника.\",\"Что можно совершить так, что наказать уже будет некого?\"],\"short\":\"Самоубийство: попытку можно наказать, а если её не предотвратили, наказывать уже некого.\",\"answer\":\"Самоубийство\"},{\"id\":269,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, что милиция могла заподозрить, глядя на требования захватчика.\",\"Что решила бы милиция, если бы захватчик попросил всего один парашют?\"],\"short\":\"Чтобы милиция думала, что он берёт заложника, и не догадалась, что один парашют нужен ему самому.\",\"answer\":\"Захватчик попросил два парашюта, для того чтобы милиция думала, что он планирует взять заложника. И ему выдали два исправных парашюта. Если бы он попросил один, было бы ясно, что парашют нужен ему для себя, и была бы вероятность, что ему дадут неисправный.\"},{\"id\":270,\"book\":\"zagadki\",\"lv\":3,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к тому, как выглядела комната и что муж говорил, когда жена стучала в дверь.\",\"Почему на ноже не нашли отпечатков и кому было выгодно, чтобы смерть выглядела как убийство?\"],\"short\":\"Муж был смертельно болен, сам покончил с собой и инсценировал убийство, чтобы жена получила страховку.\",\"answer\":\"Муж был смертельно болен. Решил покончить с жизнью и выставил это как убийство, чтобы жена получила страховку. Запер дверь, открыл окно, а когда услышал приближение жены, начал разговор с воображаемым собеседником. Потом убил себя, держа нож через тряпку.\"},{\"id\":271,\"book\":\"zagadki\",\"lv\":3,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к тому, на какой глубине работали сотрудники и как быстро они возвращались.\",\"Что происходит с азотом в крови, если человек слишком быстро поднимается с большой глубины?\"],\"short\":\"Паникёр быстро поднялся с глубины 100 метров: азотные пузырьки в крови закупорили сосуды.\",\"answer\":\"Эти люди исследовали океанское дно в поисках полезных ископаемых. Они ныряли на глубину 100 метров, где воздух обычного состава становится опасным. При подъёме на поверхность в лёгких ныряльщика могут образоваться азотные пузырьки и вызвать закупорку.\"},{\"id\":272,\"book\":\"zagadki\",\"lv\":1,\"pic\":false,\"ok\":3,\"hints\":[\"Подумай, как вор мог узнать о полиции, если вокруг было темно и тихо.\",\"Что нужно иметь при себе, чтобы слышать переговоры милиции, не видя её?\"],\"short\":\"У первого вора была рация, настроенная на волну милиции: он слышал переговоры патрулей.\",\"answer\":\"У первого вора была рация, которую он настроил на волну милиции.\"},{\"id\":273,\"book\":\"zagadki\",\"lv\":1,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к тому, где именно находилась вторая машина и что было вокруг неё.\",\"Где рация может не работать, даже если она исправна?\"],\"short\":\"Вторая машина была в сельской глуши, где рация не работала, поэтому вызов до неё не дошёл.\",\"answer\":\"Вторая машина находилась в сельской местности, где рация не работала. Вот почему полицейские не ответили на срочный вызов.\"},{\"id\":275,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Подумай, почему обычный заключённый вдруг так откровенно разговаривал с соседом по камере.\",\"Что делает человек, который сидит в камере не ради наказания, а по заданию полиции?\"],\"short\":\"Вавилов был полицейским под прикрытием: в тюрьме он добыл у наёмного убийцы признание.\",\"answer\":\"Петр Вавилов на самом деле милиционер. Он был внедрён в тюрьму, чтобы добиться признания от сокамерника, наёмного убийцы, которого никак не могли поймать с поличным или собрать против него улики.\"},{\"id\":276,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к тому, что было под машиной Ветрова, и вспомни, какая погода была вечером.\",\"Что было бы под колёсами машины, если бы она ехала домой под дождём вечером?\"],\"short\":\"Под машиной Ветрова сухо, хотя дождь шёл вечером: он не ездил домой, значит, солгал о вечере.\",\"answer\":\"Дождь начался ещё вечером. И милиционер заметил, что под машиной Ветрова сухо, т. е. машина не ездила с вечера. Ветров в состоянии аффекта из ревности убил Маргариту, когда услышал, как она разговаривает по телефону с Александровым.\"},{\"id\":277,\"book\":\"zagadki\",\"lv\":1,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, что было у грузчиков с собой, пока их держали в машине.\",\"Что могло помочь связанному человеку подать сигнал, если угонщики не обыскали карманы?\"],\"short\":\"Один из грузчиков, несмотря на наручники, позвонил в милицию с мобильного и назвал номер машины.\",\"answer\":\"Действуя в спешке, угонщики не подумали о наличии мобильных телефонов у грузчиков. И, несмотря на наручники, общими усилиями один из грузчиков смог позвонить в милицию и сообщить номер машины.\"},{\"id\":278,\"book\":\"zagadki\",\"lv\":1,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к тому, на чём облокотился инспектор и зачем он это сделал.\",\"Что инспектор почувствовал бы, опершись на капот машины, которая только что ехала?\"],\"short\":\"Капот «шевроле» был тёплым: мотор только что заглушили, значит, Нилендер ездил на машине.\",\"answer\":\"Инспектор недаром облокотился на капот «шевроле»: он применил самый простой способ узнать, давно ли выключен мотор машины. Очевидно, капот был ещё тёплым.\"},{\"id\":279,\"book\":\"zagadki\",\"lv\":1,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к тому, что говорил каждый подозреваемый о своём дне и какой сейчас день учебного года.\",\"Какой тест никогда не проводят в первый день учебного года?\"],\"short\":\"Преподаватель математики: в первый день учебного года не бывает полугодового теста, значит, он врёт.\",\"answer\":\"В первый день учебного года не проводят итоговые полугодовые тесты. Преподаватель математики врёт.\"},{\"id\":280,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к названию города, которое указано в письме.\",\"Каким был Осло в 1906 году? Вспомни историю города.\"],\"short\":\"Письмо 1906 года: тогда Осло назывался Христиания, а не Осло\",\"answer\":\"В 1906 г. Осло назывался Христиания.\\n\\nОснованный в 1048 году, Осло после пожара в 1624 году был вновь отстроен, после чего получил название Христиания в честь короля Христиана IV.\\n\\nЛишь в 1925 году город вновь стал называться Осло.\"},{\"id\":281,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, что инспектор знает о персонале больницы и что сказала умирающая.\",\"Умирающая говорила о мужчине. Кто из врачей в списке — женщина?\"],\"short\":\"С. Марвиц: это женщина-врач, а умирающая назвала убийцу мужчиной\",\"answer\":\"Очень просто. Инспектор лично знал весь персонал этой больницы и знал, что фамилия Марвиц принадлежит врачу-женщине. Убитая же говорила о мужчине.\"},{\"id\":282,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, как и где Фабер принёс воду и что эксперт нашёл на кувшине.\",\"Стал бы человек, решивший отравиться, травить весь кувшин? Чьи отпечатки на кувшине?\"],\"short\":\"Фабер: яд был во всём кувшине, а на кувшине нет его отпечатков, значит, он их стёр\",\"answer\":\"Во-первых, если бы женщина решила себя отравить, она не стала бы отравлять всю воду в кувшине, а растворила бы яд только в стакане с водой.\\n\\nА во-вторых, если Фабер принес сам кувшин в спальню, то на нем должны были остаться его отпечатки пальцев. Если их нет, значит, по всей видимости, он их стер. И вместо того, чтобы снять с себя обвинения, он навлек на себя подозрение.\"},{\"id\":283,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к тому, с какой стороны головы ювелир прижимает компресс.\",\"Представь: грабитель держит револьвер в вытянутой руке и замахивается тростью. Какой висок он может достать?\"],\"short\":\"Компресс на правом виске: вытянутая рука с револьвером не дала бы грабителю ударить в правый висок\",\"answer\":\"Ювелир должен был прикладывать компресс к левому виску. Если бы все было так, как он рассказывал, он должен был получить удар в левый висок. Удару в правый висок с размаха нападавшему препятствовала бы его же вытянутая рука с револьвером.\"},{\"id\":284,\"book\":\"zagadki\",\"lv\":1,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, кто на самом деле мог снести яйцо и кому принадлежит птица.\",\"Павлины — самцы или самки? Могут ли самцы откладывать яйца?\"],\"short\":\"Прав Джон: павлины не несут яиц, а яйцо снесено на его земле\",\"answer\":\"Фермер Смит не может претендовать на яйцо, так как павлины не несут яйца. (Самка павлина зовётся «павой».)\"},{\"id\":285,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к тому, как Логан сел за руль в гараже.\",\"Чей рост соответствовал сиденью, когда Логан сел в машину?\"],\"short\":\"Логан: сиденье за рулём было подогнано под его двухметровый рост, значит, машину вёл он сам\",\"answer\":\"Хотя Логан утверждал, что два дня не садился за руль и утром за рулём была его жена, он, демонстрируя инспектору тихую работу мотора, удобно устроился за рулём. Если бы машину последнее время водила его жена, ему, человеку двухметрового роста, пришлось бы подгонять под свой рост сиденье. Однако сиденье уже стояло под его ростом, значит, за рулём был сам Логан.\"},{\"id\":286,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Посмотри, сколько миль до города и сколько времени было у шофёра.\",\"Туда и обратно — 60 миль. За полчаса на машине это возможно?\"],\"short\":\"Шофёр: до города 30 миль, за полчаса туда, помыть машину и вернуться не успеть, значит, он лжёт\",\"answer\":\"Потому что шофёр сказал, что ездил в город мыть машину, а до города — 30 миль. Он не смог бы успеть за полчаса съездить в город, помыть на мойке машину и вернуться назад.\"},{\"id\":287,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к тому, на чём приехал Том и что Ленни рассказал о его машине.\",\"На какой машине приехал Том и мог ли он положить коробку в её багажник?\"],\"short\":\"Ленни: Том приехал на грузовике, значит, коробку в багажник он не клал, и Ленни врёт\",\"answer\":\"Ленни сказал, что видел, как Том кладёт что-то в багажник, но у Тома был грузовик. Значит, Ленни лжёт.\"},{\"id\":288,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Вспомни, что доктор Квик увидел внизу, когда вышел из дома.\",\"Откуда миссис Джамп могла знать то, что видно только снизу, с обрыва?\"],\"short\":\"Миссис Джамп: она знала, что у мужа разбита голова, хотя утверждала, что не выходила из кухни\",\"answer\":\"Миссис Джамп знала о том, что у её мужа разбита голова, хотя и утверждала, что не выходила из кухни.\"},{\"id\":289,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к двери «комнаты самоубийств» и к тому, что было за ней.\",\"Можно ли закрыть тяжёлую дверь изнутри, если под ногами нет пола?\"],\"short\":\"Дверь была закрыта, а из комнаты без пола нельзя закрыть её изнутри и прыгнуть\",\"answer\":\"Дверь в «комнату самоубийства» была найдена закрытой. Поскольку у комнаты не было пола, для Ритчи было невозможно закрыть массивную дверь изнутри и броситься вниз.\"},{\"id\":290,\"book\":\"zagadki\",\"lv\":3,\"pic\":false,\"ok\":1,\"hints\":[\"Подумай, что на самом деле лежало в стакане, когда Скит его открыл.\",\"Из чего был сделан «лёд», который Марти положил в стакан?\"],\"short\":\"Лёд был из замороженного эля: при таянии он не издаёт звуков, поэтому Скит ничего не услышал\",\"answer\":\"Никто не может услышать, как тает лед. Марти положил в стакан не простой лед, а замороженный эль…\"},{\"id\":291,\"book\":\"zagadki\",\"lv\":1,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, в какое время суток муж обещал прийти домой.\",\"Жена ждала его вечером. А когда он на самом деле появился?\"],\"short\":\"Муж обещал вернуться к восьми вечера, но пришёл в 8:02 утра следующего дня\",\"answer\":\"Жена ожидала мужа домой к восьми вечера, а он вернулся в 8:02 утра следующего дня.\"},{\"id\":292,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, когда и в какой армии мог служить человек с таким именем.\",\"Речь не о Второй мировой: вспомни, в каком году Гитлер впервые попал на фронт.\"],\"short\":\"В Первую мировую Гитлер был раненым солдатом, и британец счёл его недостойным пули\",\"answer\":\"Это случилось во время Первой мировой войны, когда Адольф Гитлер был кадровым военным немецкой армии. Он был ранен, и английский солдат решил, что убивать его недостойно.\"},{\"id\":293,\"book\":\"zagadki\",\"lv\":1,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к тому, какие именно числа записаны на листе.\",\"Что будет, если записать на листе все числа, которые вообще могут выпасть?\"],\"short\":\"Лист содержит все возможные числа, а не только выигрышные, поэтому шансы не растут\",\"answer\":\"На листе по порядку записаны все числа, которые могут выпасть в лотерее (скажем, все числа от 1 до 36, если речь идёт о лотерее «5 из 36»). Среди них обязательно есть и те, которые окажутся выигрышными, но шансы на выигрыш это нисколько не увеличивает.\"},{\"id\":294,\"book\":\"zagadki\",\"lv\":1,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, что мог сделать мужчина с помидором до того, как тот коснулся асфальта.\",\"Касался ли помидор асфальта? Что было между рукой и землёй?\"],\"short\":\"Мужчина поймал помидор у самой земли, поэтому тот не упал с двух метров\",\"answer\":\"Мужчина поймал помидор прямо над землёй.\"},{\"id\":295,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Подумай, с кем мог быть связан этот человек.\",\"Есть ли у кого-то из твоих знакомых родственник, который выглядит точно так же?\"],\"short\":\"Незнакомец — брат-близнец моего приятеля, и я узнал его по сходству с ним\",\"answer\":\"Незнакомец был братом-близнецом одного моего приятеля. Я раньше слышал о нём, но никогда с ним не встречался.\"},{\"id\":296,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, почему вулкан, который хорошо видно, так и не покорили.\",\"Земля — не единственная планета с вулканами. Где находится самый крупный из них?\"],\"short\":\"Олимп на Марсе: самый крупный потухший вулкан находится не на Земле, поэтому на него никто не поднимался\",\"answer\":\"Самый крупный из известных потухших вулканов находится на Марсе (Олимп).\"},{\"id\":297,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, о каком событии в её жизни идёт речь.\",\"Что нельзя повторить, но что ей однажды уже пришлось пережить?\"],\"short\":\"Она имела в виду своё рождение: его нельзя повторить\",\"answer\":\"Они говорили о рождении девочки.\"},{\"id\":298,\"book\":\"zagadki\",\"lv\":1,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, что ещё входит в покупку, кроме самого холста.\",\"Картина ничего не стоила. Что в этой покупке было дорогим?\"],\"short\":\"Ему нужна была дорогая рама: сама картина ничего не стоила, а рама была ценной\",\"answer\":\"Картина сама по себе ничего не стоила, но она была заключена в дорогую красивую раму, которую он собирался использовать.\"},{\"id\":299,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Вспомни, какие условия должны выполняться, чтобы референдум вообще считался.\",\"Сколько людей должно прийти на референдум, чтобы он был законным?\"],\"short\":\"Голосов было мало для кворума, поэтому референдум признан несостоявшимся\",\"answer\":\"Число проголосовавших на референдуме было недостаточным для достижения кворума, и референдум был признан несостоявшимся.\"},{\"id\":300,\"book\":\"zagadki\",\"lv\":1,\"pic\":false,\"ok\":1,\"hints\":[\"Подумай, что выгодно владельцу, даже если ошибка остаётся на вывеске.\",\"Зачем люди заходят в магазин и что они там говорят?\"],\"short\":\"Владелец оставил ошибку: люди заходят в магазин, чтобы указать на неё, и продажи растут.\",\"answer\":\"Изначально это было просто ошибкой, но со временем владелец магазина заметил, что люди часто заходят к нему в лавку, чтобы указать на несоответствие, и это только увеличивает его продажи.\"},{\"id\":301,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, для чего, кроме езды, могла понадобиться ровная полоса длиной в километр без поворотов.\",\"Что нужно самолёту, чтобы взлететь и сесть, кроме неба?\"],\"short\":\"Прямые участки служили посадочными полосами для самолётов на случай войны.\",\"answer\":\"Абсолютно прямые участки дороги были нужны для того, чтобы использовать их в качестве посадочных полос для самолётов на случай войны.\"},{\"id\":302,\"book\":\"zagadki\",\"lv\":1,\"pic\":false,\"ok\":0,\"hints\":[\"Посмотри, что посетитель успел сделать с кофе до того, как нашёл муху.\",\"Чем он мог подсластить кофе раньше, чем нашёл муху?\"],\"short\":\"Вторая чашка оказалась сладкой: это та же чашка кофе, в которую он уже положил сахар.\",\"answer\":\"Кофе в чашке был сладким: прежде чем посетитель обнаружил муху, он успел положить в кофе сахар.\"},{\"id\":303,\"book\":\"zagadki\",\"lv\":1,\"pic\":false,\"ok\":3,\"hints\":[\"Подумай, что делают сотрудники, если в анкете нужно указать дату, а её не знают.\",\"Что пишут в обязательное поле, которое нельзя оставить пустым, если настоящей даты нет?\"],\"short\":\"Поле даты рождения обязательно, а клиенты его не знают, поэтому сотрудники вписывают «11/11/11».\",\"answer\":\"В компьютерной базе, куда сотрудники компании вносят информацию о клиентах, поле с датой рождения является обязательным для заполнения. Однако этих данных зачастую не бывает, и они просто вбивают туда дату «11/11/11».\"},{\"id\":304,\"book\":\"zagadki\",\"lv\":1,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, что кислота могла не тронуть, даже если растворила всё тело.\",\"Что в теле могло быть сделано из материала, который кислота не берёт?\"],\"short\":\"Искусственный зуб жены: кислота растворила тело, а протез остался и выдал убийцу.\",\"answer\":\"Тело женщины полностью растворилось в кислоте, но у неё был искусственный зуб, который не подвергался кислотному воздействию.\"},{\"id\":305,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, где живут омары и что будет с ними в воде другого вида.\",\"Какая вода нужна омарам, чтобы жить?\"],\"short\":\"Она выкупила омаров и выпустила их в пресную воду, решив, что это раки; омары в ней гибнут.\",\"answer\":\"Она выкупила всех омаров и, приняв их за больших раков, выпустила в пресный водоём, где они умерли, поскольку омары могут жить только в солёной воде.\"},{\"id\":306,\"book\":\"zagadki\",\"lv\":1,\"pic\":false,\"ok\":0,\"hints\":[\"Обрати внимание, где стояла машина, пока он ходил за водой.\",\"Что обычно делают с машиной ведром воды?\"],\"short\":\"Он хотел помыть машину, но пока ходил за водой, её угнали.\",\"answer\":\"Мужчина собирался помыть свою машину, но, пока он ходил за водой, машину угнали.\"},{\"id\":307,\"book\":\"zagadki\",\"lv\":3,\"pic\":false,\"ok\":3,\"hints\":[\"Подумай, кто в отделении каждую пятницу появляется, кроме врачей и медсестёр.\",\"Кто по пятницам ходит по коридорам с шумным прибором и подключается к розеткам?\"],\"short\":\"Уборщица по пятницам выдёргивала из розетки аппарат жизнеобеспечения, пока пылесосила.\",\"answer\":\"Каждую пятницу в отделение приходила уборщица с пылесосом. В самую удобную розетку как раз было воткнуто оборудование, поддерживающее жизнь больного, лежащего на злосчастной койке. Уборщица отключала питание приборов на несколько минут, пока пылесосила коридор. Шум от пылесоса заглушал предсмертные крики больного. После этого уборщица подключала питание приборов обратно и уходила в другое отделение.\"},{\"id\":308,\"book\":\"zagadki\",\"lv\":1,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, что можно делать несколько раз в жизни, но не дважды в день.\",\"Что раз в несколько лет делают все граждане и это право и обязанность одновременно?\"],\"short\":\"Голосование на выборах: раз — право и обязанность, дважды в день — преступление.\",\"answer\":\"Это голосование на выборах.\"},{\"id\":309,\"book\":\"zagadki\",\"lv\":1,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, кто в этой истории только что появился на свет и что с ним делают в первые минуты.\",\"Что врач делает с новорождённым, чтобы тот начал дышать?\"],\"short\":\"Джон — новорождённый: врач шлёпает его, чтобы он заплакал и начал дышать.\",\"answer\":\"Джон — новорождённый малыш. Доктор бьёт его, чтобы он закричал и начал дышать своими лёгкими.\"},{\"id\":310,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, какие движения тела у парализованного человека всё же могли остаться.\",\"Что он мог делать одним глазом, чтобы передать слова другому человеку?\"],\"short\":\"Жан-Доминик Боби: парализован, кроме левого глаза; моргая, он продиктовал книгу ассистенту.\",\"answer\":\"Этим мужчиной был французский журналист и писатель Жан-Доминик Боби, у которого после перенесённого инсульта оказалось парализовано всё, кроме левого глаза. Моргая, он передал очень усердному ассистенту содержание книги «Скафандр и бабочка», которая стала бестселлером сразу после выхода.\"},{\"id\":311,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Подумай, что могло остаться в банке после визита вора и что он сделал с деньгами.\",\"Что случилось с одной из банкнот в спешке?\"],\"short\":\"Вор порвал банкноту пополам: утром он сдал в банк вторую половинку, совпавшую с её.\",\"answer\":\"Вор проник в дом женщины и унёс все её сбережения. Одна из банкнот застряла в банке, и вор в спешке порвал её пополам. Женщина подала заявление о краже в полицию, а потом с половинкой банкноты отправилась в свой банк, где ей сказали, что утром к ним приходил мужчина с другой половинкой той же банкноты.\"},{\"id\":312,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, что у археолога было под рукой наверху трубы, кроме лестницы.\",\"Чем можно выбить кирпичи из кладки, если в руках есть один кирпич?\"],\"short\":\"Он вынул кирпич и этим кирпичом выбивал кладку сверху вниз, пока труба не стала низкой.\",\"answer\":\"Ему удалось вынуть один кирпич из верхнего ряда трубы. Далее, используя этот кирпич в качестве молотка, он выбивал кирпичи из кладки, ряд за рядом разрушая трубу. Таким образом ему в конце концов удалось разрушить трубу почти полностью и спуститься на землю.\"},{\"id\":313,\"book\":\"zagadki\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, в каком виде были внесены деньги и откуда такие монеты обычно берутся.\",\"Сколько монет по 25 центов нужно, чтобы набрать $400, и откуда он мог их взять?\"],\"short\":\"Залог в $400 он внёс монетами по 25 центов — те самые, что украл из автоматов.\",\"answer\":\"Мужчина был обвинён в воровстве монет из машин-автоматов. Требуемый залог в $400 он внёс целиком монетами по 25 центов.\"},{\"id\":314,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к витрине и полу рядом с ней: что там видно и что с этим сделали?\",\"Что уборщики обычно делают с осколками, и кто в этой истории мог их убрать?\"],\"short\":\"Цейзиги по привычке убрали осколки стекла витрины — так поступают только уборщики.\",\"answer\":\"Семья Цейзиг стала жертвой профессиональной привычки. Супруги, похитив бокал, убрали осколки стекла витрины.\"},{\"id\":315,\"book\":\"varnike\",\"lv\":3,\"pic\":true,\"ok\":0,\"hints\":[\"Обрати внимание на то, как устроен радиоприёмник, о котором говорил Пилле.\",\"Сколько времени нужно старому ламповому приёмнику, чтобы заиграть после включения?\"],\"short\":\"Пилле врёт: ламповый приёмник не заиграл бы сразу, ведь его лампы сначала нужно прогреть.\",\"answer\":\"Господин Пилле заявляет, что не позвал на помощь потому, что громкая музыка из радиоприёмника всё равно заглушила бы его голос. Но ламповый приёмник начинает работать лишь после того, как лампы нагреются, так что это утверждение Пилле не выглядит правдоподобным.\"},{\"id\":316,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Посмотри, где в прихожей лежала газета, которую, по словам Мюллера, просунул почтальон.\",\"Где должна была лежать газета, если её просунули в щель для писем?\"],\"short\":\"Мюллер лжёт: газету нашли на столике в прихожей, а не у двери, значит, её положил сообщник.\",\"answer\":\"Инспектор сразу же обратил внимание на то, что газета лежала не на полу около двери, а на столике в прихожей. Туда её мог положить лишь соучастник Мюллера.\"},{\"id\":317,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к двери квартиры вдовы: где там замок и есть ли звонок.\",\"С какой стороны двери скважина и каким глазом через неё можно смотреть?\"],\"short\":\"Эдди лжёт: через скважину в этой двери смотрят только правым глазом, а у него его нет.\",\"answer\":\"Несомненно, инспектор Варнике тоже заметил, что на двери квартиры вдовы Н. нет звонка. Но значительно более важным оказалось другое обстоятельство. Как убедился инспектор, расположение замка в двери таково, что через замочную скважину можно посмотреть только правым глазом. А правого глаза у Эдди нет.\"},{\"id\":318,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к тому, что мотоциклист держит в руке, и в каком оно состоянии.\",\"Горяча ли свеча в его руке, если он только что подъехал и мотор работал?\"],\"short\":\"Мотоциклист держит остывшую свечу — значит, он стоит здесь давно, а не только что подъехал.\",\"answer\":\"Мотоциклист держит в руке свечу, значит, она уже остыла. Таким образом, его заявление, что он только что подъехал к месту происшествия, ложь.\"},{\"id\":319,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Подумай, что кассир рассказал о лампе и как она могла себя вести.\",\"Нагревается ли люминесцентная лампа так, чтобы обжечь руку?\"],\"short\":\"Кассир лжёт: лампа, которую он будто схватил голой рукой, люминесцентная — она не нагревается.\",\"answer\":\"Люминесцентные лампы являются лампами холодного света и никогда не нагреваются.\"},{\"id\":320,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к тому, как именно установлена цепочка и что за пластинка на двери.\",\"Пластинка с пазом должна крепиться горизонтально. Что будет, если её поставить иначе?\"],\"short\":\"Грюневальд, сосед-столяр: он поставил пластинку цепочки неправильно, и цепочка была бесполезна\",\"answer\":\"Пластинка с пазом для закрепления цепочки должна крепиться горизонтально. В противном случае цепочка совершенно бесполезна.\\n\\nСледовательно, Грюневальд умышленно поставил ее неправильно.\"},{\"id\":321,\"book\":\"varnike\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Подумай, что будет, если поднять оба чемодана, прежде чем открывать их.\",\"Сравни вес: что тяжелее — альбомы с марками или ватные игрушки?\"],\"short\":\"Подозреваемый: альбомы с марками весят намного больше ватных игрушек — перепутать чемоданы было невозможно\",\"answer\":\"Перепутать чемоданы было невозможно: слишком велика разница в весе…\"},{\"id\":322,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Посмотри, в какую сторону открывается дверь, о которую кассирша якобы ударилась.\",\"Куда открывается дверь запасного выхода: к кассирше или от неё?\"],\"short\":\"Кассирша: дверь запасного выхода открывается наружу, так что удар по голове ей не нанесла — она сама участвовала в краже\",\"answer\":\"Дверь запасного выхода открывается наружу.\\n\\nСледовательно, кассирша не могла получить удар дверью по голове…\"},{\"id\":323,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к тому, как одет сам инспектор Варнике.\",\"Сколько времени нужно, чтобы мокрое бельё на морозе замёрзло?\"],\"short\":\"Фрау Хаберкорн лжёт: на морозе мокрое бельё за час замерзает, его не свернуть и не спрятать в сумку\",\"answer\":\"Судя по шарфу, перчаткам и завязанным ушам инспектора Варнике, на улице мороз.\\n\\nМокрое белье через час окажется настолько замерзшим, что свернуть и спрятать его в сумку будет невозможно. Отсюда можно заключить, что фрау Хаберкорн лгала.\"},{\"id\":324,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Посмотри, что написано на вывеске на кухонной двери и сколько сейчас времени.\",\"До которого часа в этом ресторане подают горячие блюда?\"],\"short\":\"Официантка лжёт: горячие блюда не подают после 15 часов, а клиент пришёл позже — отбивную он заказать не мог\",\"answer\":\"Клиент при всем желании не мог заказать свиную отбивную. Вывеска на кухонной двери гласит, что в ресторане горячие блюда можно заказывать лишь до 15 часов. Так как часы показывают 18 часов 15 минут, а клиент находился в ресторане всего два часа, то, следовательно, выдача горячих блюд была прекращена задолго до его прихода.\"},{\"id\":325,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Зачем супруги заплыли так далеко от берега и что они с собой брали?\",\"Что муж, по его словам, держал в руках, когда плыл к жене, и что он мог выпустить?\"],\"short\":\"Муж: чтобы держать жену обеими руками, пришлось бы бросить гарпуны, которые он ценил дороже — помогать он не хотел\",\"answer\":\"Супруг даже при всем своем желании не смог бы оказать помощь жене, тем более держать ее двумя руками. В противном случае вместо жены ко дну пошли бы гарпуны, которые для него, видимо, были дороже.\"},{\"id\":326,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Подумай, мог ли пловец выбраться на берег точно напротив того места, где нырнул.\",\"Сравни слова юношей с тем, как течение сносит пловца.\"],\"short\":\"Юноши врали: пловца снесло бы течением, и он не мог выйти на том берегу точно напротив — они выгораживали беглеца\",\"answer\":\"Человеку, переплывающему реку, трудно выйти на противоположный берег строго напротив того места, где он вошел в воду: его обязательно снесет течением реки.\"},{\"id\":327,\"book\":\"varnike\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Подумай, где находился инспектор в тот момент, когда прозвучал выстрел, и что было вокруг.\",\"Где Варнике сидел перед выстрелом и был ли в той комнате свет?\"],\"short\":\"Варнике сидел в неосвещённой комнате, и глаза уже привыкли к темноте, в отличие от соперников\",\"answer\":\"Инспектор ответил следующее: «Приступая к операции, мне не нужно было привыкать к темноте, как моим коллегам, так как непосредственно перед выстрелом я находился в неосвещенной комнате».\"},{\"id\":328,\"book\":\"varnike\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Посмотри внимательно, чем занят человек в поле и как он это делает.\",\"Как в деревне убирают лён: жнут его серпом или выдёргивают?\"],\"short\":\"Тот жнёт лён, хотя его теребят — незнание сельского хозяйства выдало сбежавшего преступника\",\"answer\":\"Преступника выдало его невежество в сельском хозяйстве: лен никогда не жнут, чтобы не разрушать его волокна, его выдергивают с корнями — теребят.\"},{\"id\":329,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Подумай, каков был рост участников этой истории и что стояло на шкафу.\",\"Мог ли маленький Томми дотянуться до яйца на шкафу?\"],\"short\":\"Дядя Джеймс: только высокий человек мог увидеть яйцо на шкафу, а Томми до него ростом не достаёт\",\"answer\":\"Рассерженные родители упустили из виду то, что Томми слишком мал ростом, чтобы увидеть лежащее на шкафу яйцо. Его мог увидеть только человек высокого роста, то есть не кто иной, как сам мистер Джеймс.\"},{\"id\":330,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к самим перчаткам: на какую руку каждая из них?\",\"Могут ли две перчатки одной пары подходить на одну и ту же руку?\"],\"short\":\"Перчатки были на одну руку — такую пару он не мог купить и носить, значит, лжёт\",\"answer\":\"Покупатель говорит неправду. Если бы даже, размечтавшись, он и купил у очаровательной продавщицы две перчатки на одну и ту же руку, то уж носить их он наверняка бы не смог.\"},{\"id\":331,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Посмотри внимательно, как каждый из пассажиров одет и что у него с собой.\",\"Какая одежда нужна на Аляске, и во что был одет последний пассажир из автобуса?\"],\"short\":\"Последний пассажир: он летит на Аляску из жаркой Калифорнии без багажа и тёплой одежды\",\"answer\":\"Подозрение Варнике пало на пассажира, идущего последним: он единственный из жаркой Калифорнии отправляется на Аляску без багажа и теплой одежды.\"},{\"id\":332,\"book\":\"varnike\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Подумай, что происходит с оконным стеклом снаружи в сильный мороз.\",\"Замерзают ли оконные стекла снаружи так же, как изнутри?\"],\"short\":\"З. лжёт: снаружи окна не покрываются льдом, так что «глазок» он продышать не мог — значит, был в доме\",\"answer\":\"Как известно, оконные стекла снаружи не замерзают.\\n\\nЕстественно, что заявление З. о том, что он продышал в окне «глазок», вызвало у инспектора Варнике подозрение.\"},{\"id\":333,\"book\":\"varnike\",\"lv\":3,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, что происходит с телефонной линией, если трубку не положили.\",\"Мог ли друг вызвать полицию со своего телефона, если линия осталась занята?\"],\"short\":\"Друг лжёт: если Пауль не успел положить трубку, линия была бы занята и звонок не прошёл бы; да и адрес он знал\",\"answer\":\"Если бы убитый действительно не успел повесить трубку, как заявил его друг, то этот последний вследствие блокировки телефонной линии не смог бы по своему телефону вызвать полицию.\\n\\nИ еще. Подозреваемый не мог точно знать, где находится Пауль, когда тот звал на помощь, тем не менее тут же вызвал полицию к нему домой.\"},{\"id\":334,\"book\":\"varnike\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Обрати внимание на то, в каком состоянии бывают очки после выхода из дома.\",\"Запотевают ли очки, если выйти из тёплого помещения на холод?\"],\"short\":\"Муж лжёт: очки не запотевают, когда выходишь из тёплой комнаты на холод — историю с грабителем он выдумал\",\"answer\":\"Общеизвестно, что очки никогда не запотевают, если выйти из теплого помещения на улицу, где воздух обычно более холодный.\"},{\"id\":335,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к гирлянде на ёлке: все ли лампочки на месте?\",\"Что будет с последовательной гирляндой, если в ней не хватает одной лампочки?\"],\"short\":\"Майер лжёт: в гирлянде не хватало лампочки, а последовательная цепь без неё не горит — ёлку не зажигали\",\"answer\":\"Электрические лампочки, которые используются для украшения елки, включаются последовательно. В гирлянде одна лампочка отсутствует, следовательно, елка вообще не зажигалась.\"},{\"id\":336,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к бутылке, из которой приятели пьют уже два часа, и к тому, где она стоит.\",\"Что произошло с вином в бутылке, которая два часа стояла на солнце?\"],\"short\":\"Вино приятелей нагрелось на солнце, а из погреба принесли холодное — незнакомец различил их по температуре\",\"answer\":\"Бутылка, из которой пили приятели, в течение двух часов находилась на солнце, и вино в ней нагрелось.\\n\\nВино, принесённое из погреба, конечно же, было холодным. Это и помогло незнакомцу различить их.\"},{\"id\":337,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Подумай, что могло светиться в кромешной тьме туннеля.\",\"Что на руке у сидевшего напротив инспектора могло светиться в темноте?\"],\"short\":\"Вор — сидевший напротив мужчина: в темноте Варнике разглядел светящиеся часы на его руке\",\"answer\":\"Инспектор Варнике смог бы увидеть в темноте руку вора лишь в том случае, если на ней был какой-либо светящийся предмет. Таким предметом могут быть часы, которые надеты на руке сидящего напротив инспектора мужчины. Как стало известно, он в краже сознался.\"},{\"id\":338,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Подумай, что такой человек мог сделать, зная местность как свои пять пальцев.\",\"Что рядом с тропой, по которой кассир шёл до деревни?\"],\"short\":\"Кассир лжёт: зная местность, он дошёл до деревни почти вслепую, значит, мог дойти до ручья и промыть глаза\",\"answer\":\"Конечно, кассир лгал. Если он знал местность как свои пять пальцев и сумел с закрытыми глазами дойти до деревни Визенгрунд, то с таким же успехом он мог добраться до протекающего рядом ручья и промыть в нем глаза.\"},{\"id\":339,\"book\":\"varnike\",\"lv\":3,\"pic\":true,\"ok\":2,\"hints\":[\"Посмотри на рисунок: в какую сторону открывается дверь номера?\",\"Что стало бы с предметами перед дверью, если бы через неё кто-то пробежал?\"],\"short\":\"Кинозвезда инсценировала покушение: дверь открывается внутрь, и предметы перед ней не сдвинуты — никто за ней не прятался\",\"answer\":\"Если бы преступник действительно скрылся за дверью, то все находившиеся перед дверью предметы были бы отброшены в сторону (на рисунке видно, что дверь открывается внутрь). Эту маленькую деталь не учла кинозвезда, пытавшаяся ради рекламы инсценировать покушение на собственную особу.\"},{\"id\":340,\"book\":\"varnike\",\"lv\":1,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись, что видно под машиной на стоянке.\",\"Под машиной земля совсем сухая: сколько времени она там простояла?\"],\"short\":\"Машина стояла здесь давно: под ней сухое поле, значит, она не могла задавить кошку.\",\"answer\":\"— Взгляните сами, — произнес инспектор, обращаясь к даме. — Под машиной видно сухое поле, поэтому водитель действительно остановился здесь давно и не мог задавить вашу кошку.\"},{\"id\":341,\"book\":\"varnike\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к тому, какой свет горел в кабинете, когда Риттер увидел тень.\",\"Мог ли Риттер при одной настольной лампе увидеть тень справа от себя?\"],\"short\":\"Риттер лжёт: в тот момент горела только настольная лампа, и он не мог видеть тень справа от себя.\",\"answer\":\"Как явствует из рассказа Риттера, в момент происшествия горела лишь настольная лампа, и он, таким образом, никак не мог увидеть с правой стороны от себя тень злоумышленника. Эта тонкость не ускользнула от внимания инспектора.\\n\\nПоэтому он и обвинил Риттера в преднамеренной лжи.\"},{\"id\":342,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к рисунку: как нарисован рояль.\",\"На какой стороне рояля обычно делают фигурный вырез и где он оказался на листе?\"],\"short\":\"Посетитель солгал: на его рисунке рояль нарисован с вырезом не с той стороны, значит, рояля не было.\",\"answer\":\"На рисунке, который увидел инспектор Варнике, рояль изображен неправильно. Фигурный вырез у рояля всегда находится с правой стороны.\"},{\"id\":343,\"book\":\"varnike\",\"lv\":1,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись, что висит на стенах в доме Альфредо.\",\"Водятся ли львы в бассейне реки Амазонки?\"],\"short\":\"Альфредо солгал о коллекции: на стене шкура льва, а львов в бассейне Амазонки никогда не водилось.\",\"answer\":\"При осмотре коллекции инспектор Варнике сразу же обратил внимание на висящую на стене шкуру льва. Известно, что львы в бассейне реки Амазонки никогда не водились.\"},{\"id\":344,\"book\":\"varnike\",\"lv\":1,\"pic\":true,\"ok\":2,\"hints\":[\"Посмотри, что стоит на плите у супругов.\",\"Сколько времени нужно, чтобы вода в кастрюле закипела?\"],\"short\":\"Супруги лгут: на кухне кипит кастрюля, а за минуту вода не закипит, значит, они дома давно.\",\"answer\":\"Инспектор Варнике заметил на кухне кипящую кастрюлю. За одну минуту вода в кастрюле не могла бы вскипеть.\"},{\"id\":345,\"book\":\"varnike\",\"lv\":3,\"pic\":true,\"ok\":3,\"hints\":[\"Обрати внимание, как жилец третьей квартиры объясняет, где был вчера вечером.\",\"Что в комнате Ферстера говорит о том, что он собирается уезжать, а не только что вернулся?\"],\"short\":\"Ферстера: он не вернулся из поездки, а сам собирается уезжать, ведь вещи собраны, картина свёрнута в трубку.\",\"answer\":\"Инспектор Варнике понял, что Ферстер не приехал из поездки, а, наоборот, собирается срочно уезжать. Об этом говорят и собранные вещи и беспорядок в комнате, а главное, вынутая из рамки и свернутая в трубочку картина, которая, очевидно, тоже представляет собой ценность. Кроме того, Варнике припомнил еще одну деталь: листья цветка, если бы к нему не притрагивались в течение семи дней, были бы обращены к свету.\"},{\"id\":346,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к костюмам гостей: какой из них не похож на остальные.\",\"Сколько полных комплектов выдал хозяин и сколько гостей оказалось в зале?\"],\"short\":\"Гостя с костюмом из тюрбана, болеро и голландских ботинок: полного комплекта из проката на нём нет, значит, он лишний.\",\"answer\":\"Хозяин ресторана выдал гостям полные комплекты костюмов, а у третьего в очереди костюм сборный, из одежды разных народов — индийского тюрбана, мексиканского болеро и голландских ботинок. На него и пало подозрение.\"},{\"id\":347,\"book\":\"varnike\",\"lv\":1,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к тем, кто занимается кормлением животных.\",\"Что едят носороги и чем их пытался покормить «служащий»?\"],\"short\":\"Мнимого служащего зоопарка: он пытался накормить носорога мясом, хотя носороги травоядные.\",\"answer\":\"Инспектор Варнике обратил внимание на «служащего» зоопарка, который тщетно пытался накормить носорога мясом. Как известно, носороги — животные травоядные.\"},{\"id\":348,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Посмотри, как проходят трещины от камня и где они пересекаются с другими.\",\"Трещины от камня обрываются на других трещинах: что было раньше?\"],\"short\":\"Камень попал в уже разбитое стекло: его трещины обрываются на других трещинах, значит, разбил его сам Фидлер.\",\"answer\":\"Варнике сразу заметил, что камень брошен в стекло уже после того, как оно было разбито.\\n\\nТрещины от камня заканчиваются на трещинах, нанесенных на стекле каким-то другим предметом.\"},{\"id\":349,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к вёслам и к тому, как молодой человек объясняет свою лодку.\",\"Была ли лодка молодого человека зарегистрирована и что он сам об этом сказал?\"],\"short\":\"Молодого человека: вёсла двухлопастные, как у байдарки, а его лодка не зарегистрирована и куплена вчера.\",\"answer\":\"Молодого человека выдали весла. Как известно, байдарка управляется двухлопастным веслом.\"},{\"id\":350,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к тому, как выглядят ноги у купающихся.\",\"Что видно по ногам того, кто недавно приехал на стройку и работает в брюках?\"],\"short\":\"Купальщика с белыми, не загоревшими ногами: он из приехавших строителей, которые работают в брюках, а не загорают.\",\"answer\":\"Белые, совершенно не загоревшие ноги одного из купающихся привели Варнике к убеждению, что именно он один из только что приехавших строителей, которые работают обычно без майки, но в брюках.\"},{\"id\":351,\"book\":\"varnike\",\"lv\":3,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к часам на стене мастерской.\",\"Насколько отстают электрические часы от механических, если свет якобы был выключен почти два с половиной часа?\"],\"short\":\"Часовщик лжёт: электрические часы отстают от механических лишь на 10 минут, а света не было почти два с половиной часа.\",\"answer\":\"Если присмотреться к электрическим часам на стене, видно, что они отстают от механических часов всего на 10 минут. По утверждению же пострадавшего, электричества не было почти два с половиной часа, следовательно, часовщик пытается обмануть Варнике.\"},{\"id\":352,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись, во что одет Вакель и как на нём лежит повязка.\",\"Снял ли Вакель пиджак, когда накладывал повязку на руку?\"],\"short\":\"Вакеля: «сломанная» рука с повязкой поверх рукава пиджака, значит, рука цела и он вполне может воровать.\",\"answer\":\"Второпях Вакельфингер забыл снять пиджак и сделал себе повязку поверх рукава.\"},{\"id\":353,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись, откуда залетел камень и где стоит балкон.\",\"Через какое окно влетел камень: нижнее за балконной стенкой или верхнее?\"],\"short\":\"Молле сам: камень влетел через нижнее окно за балконной стенкой, значит, его бросили с балкона, а не с улицы.\",\"answer\":\"Если бы камень был брошен с улицы, то он влетел бы в комнату не через нижнее, закрытое стенкой балкона, а через верхнее стекло. Очевидно, Молле сам швырнул камень с балкона.\"},{\"id\":354,\"book\":\"varnike\",\"lv\":3,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к тому, что свидетель говорит о погоде и освещении в ту ночь.\",\"Могла ли луна быть полной две недели назад, если сейчас полнолуние?\"],\"short\":\"Мозес: он уверял, что при полной луне всё видел, но две недели назад ночь не могла быть светлой, значит, он лжёт.\",\"answer\":\"Именно темнотой воспользовался «свидетель» Мозес, убивший своего случайного знакомого. Если сейчас полнолуние, то две недели назад ночь не могла быть светлой.\"},{\"id\":355,\"book\":\"varnike\",\"lv\":3,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись к теням на снимке и к тому, какое время суток на нём видно.\",\"Насколько длинными бывают тени, когда солнце стоит в зените, то есть в полдень?\"],\"short\":\"Тени на снимке слишком длинные для полудня: фото сделано утром или вечером, а часы на нём мог подделать фотограф.\",\"answer\":\"В полдень солнце стоит слишком высоко. Предметы не могут, следовательно, отбрасывать такие длинные тени. Таким образом, снимок сделан утром или вечером. Часы же фотолюбитель, мастер своего дела, мог вмонтировать в свой снимок.\"},{\"id\":356,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись, где стоит сумка и какая рука у каждой из женщин.\",\"Которая из женщин поставила бы сумку справа от себя, если бы украла её?\"],\"short\":\"Женщину со здоровой рукой: сумка стоит рядом с больной рукой другой, а вор поставил бы её справа от себя.\",\"answer\":\"Если бы воровкой была женщина с больной рукой, то она поставила бы сумку справа от себя. Но сумка стоит рядом с её больной рукой. По всей вероятности, её украла другая женщина.\"},{\"id\":357,\"book\":\"varnike\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к тому, каким способом, по словам племянника, змея убила человека.\",\"Как удав расправляется с жертвой и как обычно умирает человек от укуса ядовитой змеи?\"],\"short\":\"Племянник врёт: удав душит, а не кусает, а от укуса змеи человек умирает в конвульсиях, а не спокойно за столом.\",\"answer\":\"Племянник погибшего зоолога не учёл, что Boa constrictor — удав, который, как известно каждому зоологу, не кусает свою жертву, а удушает.\\n\\nПричём удавы на человека, как правило, не нападают. Вдобавок жертва змеиного укуса погибает обычно в конвульсиях, а не в спокойном состоянии.\"},{\"id\":358,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к тому, на чём именно плыл Адельберт и как это соотносится с ветром.\",\"Может ли обычная лодка без выдвижного киля идти против ветра?\"],\"short\":\"Адельберт врёт: у «Бине» нет выдвижного киля (шверта), без которого против ветра не поплывёшь.\",\"answer\":\"У швербота «Бине» нет выдвижного киля (шверта), без которого лодка не может плыть против ветра.\"},{\"id\":359,\"book\":\"varnike\",\"lv\":1,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к бутылкам на полу: что с ними случилось после ограбления?\",\"Что стало бы с бутылками, если бы их со всей силой сбросили с полки на плиточный пол?\"],\"short\":\"Да: бутылки на плиточном полу целы, а упав с полки со всей силой, часть из них непременно разбилась бы.\",\"answer\":\"Инспектор Варнике сразу обратил внимание на то, что все бутылки на плиточном полу были целыми. Если бы они со всей силой упали с полки, то часть их, как минимум, была бы разбита!\"},{\"id\":360,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к подписям на картинах и к датам из справки.\",\"Когда жили Ван-Эйки и когда табак появился в Европе?\"],\"short\":\"Картина с подписью Ван-Эйка подделка: на ней табак, которого в Европе ещё не знали во времена Ван-Эйков.\",\"answer\":\"Картина, подписанная фамилией Ван-Эйк, не может быть подлинной.\\n\\nЗнаменитые голландские живописцы братья Губерт и Ян Ван-Эйки жили в XV веке, а табак в Европе стал известен столетием позже.\"},{\"id\":361,\"book\":\"varnike\",\"lv\":1,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к тем, кто был рядом с ковриком, и к тому, чем занимаются люди у реки.\",\"Что можно сделать с берега, не подходя к коврику и не оставляя следов на песке?\"],\"short\":\"Человек с удочкой: из-за кустов он незаметно «выудил» браслет с книги, не оставив следов на песке.\",\"answer\":\"Скорее всего вором был человек с удочкой. Спрятавшись за кустами, он незаметно «выудил» браслет.\"},{\"id\":362,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Подумай, где стояла суфлёрша и откуда пуля прошла бы через шею.\",\"Если бы выстрел был сделан из будки снизу, какое отверстие оказалось бы ниже?\"],\"short\":\"Суфлёрша не стреляла: из её будки входное отверстие пули было бы ниже выходного, а здесь они на одной линии.\",\"answer\":\"Суфлёрша не могла совершить этого убийства. Если бы она стреляла из своей суфлёрской будки, то входное отверстие от пули было бы ниже выходного.\"},{\"id\":363,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к письменным принадлежностям и подумай, что нужно ручке для долгой работы.\",\"Что нужно авторучке, чтобы писать две недели подряд, и этого на острове не видно?\"],\"short\":\"Чернильницы: без пополнения чернил две недели не напишешь, значит, Спикер всё-таки ездил на материк.\",\"answer\":\"Инспектору Варнике, естественно, не хватало чернильницы. Ведь мистер Спикер не мог беспрерывно писать две недели, не наполнив ни разу свою авторучку!\"},{\"id\":364,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись к тому, как открывается дверь комнаты № 13 и где стоял официант в момент удара.\",\"В какую сторону открывается дверь номера 13, и могла ли она ударить того, кто стоял в коридоре?\"],\"short\":\"Официант: дверь открывается только внутрь, значит, она не могла ударить стоявшего в коридоре Томми; он солгал.\",\"answer\":\"Дверь комнаты № 13 не могла ударить официанта Томми по голове, т. к. она открывается только внутрь. А Томми сделал заявление о том, что он стоял перед комнатой в коридоре. Таким образом, инспектор Варнике разобрался в преступлении и арестовал официанта.\"},{\"id\":365,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Посмотри на подозреваемых: кто из них мог дотянуться до головы потерпевшего сзади?\",\"Кто из подозреваемых самый высокий, если удар пришёлся сзади прямо в лоб?\"],\"short\":\"Подозреваемый №2: только высокий мужчина мог ударить сзади дубиной прямо в лоб потерпевшего.\",\"answer\":\"Преступник — высокий мужчина под номером 2. Только он, с его ростом, мог нанести удар сзади и попасть дубиной в лобную часть головы.\"},{\"id\":366,\"book\":\"varnike\",\"lv\":3,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к словам графа о кальмаре и к цвету жидкости в аквариуме.\",\"Где живут гигантские кальмары и какого цвета чернила выпускает кальмар в опасности?\"],\"short\":\"Граф ошибся дважды: кальмара в аквариуме не бывает, а чернила у кальмара чёрно-коричневые, а не синие.\",\"answer\":\"Конечно, инспектор Варнике сразу понял, что в аквариуме не может быть никаких кальмаров, и уж тем более гигантских кальмаров. Известно, что гигантский кальмар является глубоководным животным и достигает до двадцати метров в длину. Кроме того, в минуту опасности он выделяет не синий, а чёрно-коричневый краситель.\"},{\"id\":367,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к шахматной доске и к тому, как она стоит перед игроками.\",\"Какого цвета должно быть угловое поле справа у каждого игрока?\"],\"short\":\"Доска лежит неверно: чёрное угловое поле справа, а настоящие шахматисты так не играют, значит, они лгут.\",\"answer\":\"Инспектор Варнике обратил внимание на то, что шахматная доска лежит неверно. Настоящие шахматисты никогда не станут играть, если чёрное угловое поле расположено справа от игрока.\"},{\"id\":368,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Подумай, кому из троих проще всего достать до подоконника.\",\"Кто из сыщиков самый высокий и у кого длиннее руки, ведь не хватало пяти сантиметров?\"],\"short\":\"Самый высокий, стоящий на полу, взбирается наверх: у него длиннее руки, и он дотянется до окна.\",\"answer\":\"На самый верх должен взобраться тот, кто стоит на полу. Он самый высокий, следовательно, и руки у него длиннее.\"},{\"id\":369,\"book\":\"varnike\",\"lv\":3,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к столу, за которым сидел директор, и к тому, что в нём необычного.\",\"Что может сделать вращающаяся столешница со стаканом, который стоит на ней?\"],\"short\":\"Директор: он заказал стол-«вертушку» и крутил столешницу во время танца, чтобы незаметно подмешать яд.\",\"answer\":\"Инспектор Варнике обратил внимание на то, что директор цирка забронировал для своих гостей стол-«вертушку». Он мог незаметно крутить столешницу взад-вперёд во время танцевального номера и незаметно подмешать яд в бокал искусствоведа.\"},{\"id\":370,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к тому, где стояла сумка покупательницы и что было на полу.\",\"Что могло лежать под сумкой покупательницы, которая стояла на коленях?\"],\"short\":\"Покупательница с сумкой: она накрыла сумкой упавшую стофунтовку и собиралась незаметно положить её в кошелёк.\",\"answer\":\"Она поставила свою хозяйственную сумку на упавшую на пол стофунтовую купюру, чтобы в какой-нибудь момент незаметно отправить её в кошелёк. Всё это время она стояла у его ног на коленях.\"},{\"id\":371,\"book\":\"varnike\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, что происходит в трубе, когда из неё вытекает вода на нижнем этаже.\",\"Что создаёт лопнувшая труба, и куда тогда могла уйти вода из шланга?\"],\"short\":\"Воду не крали: из-за лопнувшей трубы возник всасывающий эффект, и вода из ванны через шланг ушла обратно в трубу.\",\"answer\":\"Инспектор Варнике сразу понял: из-за того, что вода из лопнувшей трубы вытекала в подвале, возник всасывающий эффект, и вода для замачивания из ванны через шланг утекла обратно в водопроводную трубу.\"},{\"id\":372,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Посмотри на растение на подоконнике: как оно стоит относительно света?\",\"Куда тянутся листья растения к свету и сколько времени нужно, чтобы они повернулись?\"],\"short\":\"Мюллер лжёт: монстера на подоконнике не повёрнута к свету, значит, к окну он подходил совсем недавно.\",\"answer\":\"Инспектор Варнике сразу заметил, что монстера — растение с большими листьями, стоящее на подоконнике, не повернуто своими листьями к свету. Это говорит о том, что оно стоит в таком положении совсем недолго. В любом случае г-н Мюллер солгал, сказав, что он не подходил к окну пару недель.\"},{\"id\":373,\"book\":\"varnike\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к часам мужчины и подумай, сколько дней он провёл без света.\",\"Сколько дней светящаяся в темноте краска может сиять, если её долго не освещать?\"],\"short\":\"Мужчина врёт: светящийся циферблат после трёх дней в темноте уже не светился бы, и время он не мог узнать.\",\"answer\":\"Инспектор заподозрил мужчину во лжи, так как тот не мог определить время «ночного крика». После трёхдневного пребывания в тёмном подвале циферблат с люминесцентным покрытием перестал бы светиться.\"},{\"id\":374,\"book\":\"varnike\",\"lv\":1,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к картинке у прилавка с колбасой: кто там мог спрятаться?\",\"Чей нос и хвост видны на картинке рядом с колбасой и окороком?\"],\"short\":\"Собака: её нос и хвост выглядывают из-за колбасы и окорока чуть левее центра рисунка.\",\"answer\":\"За колбасой с окороком пристроилась собака, нос и хвост которой выглядывают чуть левее центра рисунка.\"},{\"id\":375,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Подумай, куда по инерции полетел бы молоток, соскользнув по скату крыши.\",\"Может ли молоток, скользя по наклонной кровле, упасть на того, кто сидит прямо у стены дома?\"],\"short\":\"Молоток, соскользнув с крыши, упал бы правее брата, сидевшего в «слепой» зоне: значит, его бросили нарочно.\",\"answer\":\"Скользивший по крыше молоток не мог попасть в голову брату, который сидя сажал цветы, так как он находился в «слепой» зоне. Молоток, скользя по наклонной кровле, должен был по инерции пролететь дальше и упасть правее его. Следовательно, молоток был брошен с крыши умышленно.\"},{\"id\":376,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Обрати внимание, с какой стороны мотоцикла находится коляска и в какую сторону он поворачивает.\",\"При повороте направо центробежная сила уводит мотоцикл влево: что случится с коляской, если она стоит справа?\"],\"short\":\"При повороте направо коляска справа не может взлететь, как он утверждает: значит, он сбил человека.\",\"answer\":\"Законы физики не позволяют мотоциклисту поднять колесо коляски, расположенной с правой стороны, в воздух при вхождении в правый поворот.\"},{\"id\":377,\"book\":\"varnike\",\"lv\":1,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись, кто из посетителей держит трубку и как именно она у него во рту.\",\"Варнике никогда не курит свою трубку. Кто в баре держит во рту точно такую же незажженную?\"],\"short\":\"Мужчина в очках: он единственный в баре держит во рту незажженную трубку, похожую на трубку Варнике.\",\"answer\":\"Инспектор всегда держит во рту свою любимую трубку, но никогда ее не курит. Именно это обстоятельство и позволило обнаружить похитителя. Им оказался мужчина в очках, который единственный в баре держит во рту незажженную трубку, похожую на трубку Варнике.\"},{\"id\":378,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к следам у саней: какая на них обувь?\",\"Струнц пришел по снегу в валенках. Чьи следы в ботинках на каблуках остались рядом с санями?\"],\"short\":\"Рядом с санями следы ботинок на каблуках, а Струнц ходит в валенках: сани тащил кто-то другой, и он лжет.\",\"answer\":\"Струнц утверждает, что он вместе с санями только что поднялся по склону из городка внизу. Но рядом с санями следы ног, одетых в ботинки на каблуках, а Струнц одет в валенки. Значит, санки поднимал кто-то другой. Следовательно, он лжет.\"},{\"id\":379,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись, как сшит костюм: где на нем пришиты пуговицы.\",\"С какой стороны на мужском костюме обычно пришиваются пуговицы — и как сделал бы это настоящий портной?\"],\"short\":\"Пуговицы на мужском костюме пришиты с левой стороны, чего настоящий портной не допустил бы: значит, он не портной.\",\"answer\":\"Если бы этот человек был профессиональным портным, он не пришил бы на мужском костюме пуговицы с левой стороны.\"},{\"id\":380,\"book\":\"varnike\",\"lv\":1,\"pic\":false,\"ok\":1,\"hints\":[\"Подумай, через что светило солнце в студию художника.\",\"Что задерживает ультрафиолет, из-за которого загорают, и может ли он пройти через оконное стекло?\"],\"short\":\"Через оконные стекла не загорают: стекло задерживает ультрафиолет, который даёт загар, значит, художник лжет.\",\"answer\":\"Нельзя через стекла загореть на солнце. Стекла практически полностью задерживают ультрафиолетовые лучи, которые отвечают за загар.\"},{\"id\":381,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись, как подмастерье режет колбасу.\",\"Как режут колбасу настоящие мясники, прямо или под углом? Как режет ее подмастерье?\"],\"short\":\"Подмастерье режет колбасу прямо, а настоящие мясники режут ее под углом: значит, документы поддельные.\",\"answer\":\"У настоящих мясников есть старый и добрый обычай — колбасу нарезать всегда под углом.\"},{\"id\":382,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Посмотри на схему вокзала: где находится вход, из которого выбежал Лемман?\",\"С какой стороны вокзала вход, в котором, по словам Леммана, его ослепило солнце, и откуда оно в тот день светит?\"],\"short\":\"Солнце не могло его ослепить: вход на вокзал смотрит на север, и солнце туда не попадает, значит, он лжет.\",\"answer\":\"Солнце не могло ослепить Леммана, так как вход на вокзал находится на северной стороне.\"},{\"id\":383,\"book\":\"varnike\",\"lv\":3,\"pic\":false,\"ok\":1,\"hints\":[\"Подумай, что в этом доме могло появиться со двора и исчезнуть без следа.\",\"Что лежало во дворе и что могло растаять в комнате, оставив большую лужу?\"],\"short\":\"Планк втащил в комнату снег, сделал из него горку, встал на нее и повесился; потом снег растаял и оставил лужу.\",\"answer\":\"Планк принес со двора снег и сделал из него горку, забравшись на которую он смог залезть в петлю. За прошедшие дни снег в комнате растаял, оставив на полу большую лужу.\"},{\"id\":384,\"book\":\"varnike\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Посмотри, что на письме и что лежало рядом с кровью.\",\"Есть ли на прощальном письме следы крови, а если есть, когда письмо могло оказаться рядом с ней?\"],\"short\":\"На прощальном письме есть кровь: его вложили в конверт уже после смерти Бэнкли, значит, это убийство.\",\"answer\":\"На прощальном письме мистера Бэнкли были следы крови. Значит, письмо было вложено в конверт уже после смерти Бэнкли, то есть его вложил убийца.\"},{\"id\":385,\"book\":\"varnike\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, сможет ли один человек унести такую статую и кто в это время дежурил в храме.\",\"Сколько весит золотая статуя высотой 60 сантиметров? Смог бы Нирва унести ее в мешке на спине?\"],\"short\":\"Нирва не унес бы в мешке золотого Будду весом больше ста килограммов, а у Талеба была возможность спрятать его на дежурстве.\",\"answer\":\"Нирва никак не смог бы в одиночку унести 60-сантиметрового Будду из чистого золота, да еще и в мешке на спине. Даже по самым приблизительным расчетам статуэтка должна была весить не менее ста килограммов.\\n\\nА у Талеба было достаточно возможностей украсть и спрятать Будду во время своего дежурства.\"},{\"id\":386,\"book\":\"varnike\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Посмотри, как вел себя молодой человек в комнате и во что он был обут.\",\"В чем был одет молодой человек, когда разгуливал по чужой комнате? Что это говорит о его отношениях с хозяйкой?\"],\"short\":\"Незваный гость был в домашних тапочках и чувствовал себя дома: это любовник жены, а не грабитель.\",\"answer\":\"Ясно, что женщина лгала и изменяла своему Отто. Похоже, что «грабитель» чувствовал себя здесь как дома, иначе стал бы он разгуливать по комнате в домашних тапочках.\"},{\"id\":387,\"book\":\"varnike\",\"lv\":3,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись к цифрам на промокашке: как они выглядят?\",\"Как выглядели бы две девятки на промокашке, если бы отпечаток был настоящим: зеркально или нет?\"],\"short\":\"На промокашке девятки написаны не так, как выглядели бы в зеркальном отражении: отпечаток подделан.\",\"answer\":\"Инспектор Варнике сразу же обратил внимание на то, что на промокательной бумаге две девятки написаны не так, как это выглядело бы в зеркальном отражении. Следовательно, документ был подделан.\"},{\"id\":388,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись, какой рукой Виктор пользуется, когда выходит из подъезда.\",\"Какой рукой Виктор придерживает дверь или садится в машину, если правая, по его словам, сломана?\"],\"short\":\"Виктор ходил с подвязанной правой рукой, но при выходе из дома пользовался левой: рука не сломана.\",\"answer\":\"У Виктора в квартире была подвязана «сломанная» правая рука, а при выходе из дома — левая…\"},{\"id\":389,\"book\":\"varnike\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Посмотри, что в комнате осталось на своих местах и что ветер мог бы сдвинуть.\",\"Могла ли купюра, лежавшая на столе, вылететь в окно от порыва ветра, если все остальное в комнате не сдвинулось?\"],\"short\":\"Купюра не могла вылететь в окно от порыва ветра, когда вся обстановка осталась прежней: Берг лжет.\",\"answer\":\"При порыве ветра из окна купюра не могла вылететь в открытое окно. Значит, каменщик Берг лжет.\"},{\"id\":390,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Обрати внимание на одежду задержанного и на то, откуда он, по его словам, прилетел.\",\"Какая погода в Бразилии под Рождество? Во что одет человек, который якобы прилетел из Швеции?\"],\"short\":\"Задержан бородач, назвавшийся шведом: он одет слишком легко для Швеции, хотя прилетел из Бразилии, где под Рождество лето.\",\"answer\":\"Людовик задержал того, кто сказал, что он из Швеции. Он был слишком легко одет, ведь в Бразилии под Рождество — лето…\"},{\"id\":391,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Посмотри, что Людовик заметил в чемодане третьего путешественника.\",\"Сравни глубину крышки чемодана с тем, что в ней лежит: что может прятаться между дном и крышкой?\"],\"short\":\"В крышке чемодана третьего путешественника двойное дно: его глубина не совпадает, а вещи набиты для отвода глаз.\",\"answer\":\"Людовик отметил, что чемодан третьего путешественника напичкан чем угодно: слишком маленькой для него шляпой, несовпадающей парой обуви, рваной тканью. Это заставило Людовика более пристально взглянуть на чемодан, и он заметил, что дно верхней крышки не соответствует ее глубине. В верхней крышке было двойное дно. Без сомнения, именно там и был спрятан пакет.\"},{\"id\":392,\"book\":\"varnike\",\"lv\":3,\"pic\":true,\"ok\":2,\"hints\":[\"Подумай, где стояли осколки относительно кустов и в какое время дня ими играло солнце.\",\"Где на схеме находятся осколки, с какой стороны от кустов, и куда клонится солнце после полудня?\"],\"short\":\"Осколки лежали на востоке за кустами, а после полудня солнце клонится на запад: поджечь лес они не могли.\",\"answer\":\"Поскольку солнце после обеда начинает клониться к горизонту, то осколки стекла, находящиеся, как видно на схеме, за кустами на востоке, не могут быть освещены солнечными лучами, не говоря уже о том, чтобы быть причиной пожара.\"},{\"id\":393,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Сравни, где стояли вещи в комнате утром и вечером.\",\"Почему вечером лампа стоит на столике у розетки, а не на тумбочке у кровати?\"],\"short\":\"Вечером лампа стояла на столике и была включена в розетку, хотя утром была на тумбочке: Гастон вставал.\",\"answer\":\"Он переставил настольную лампу с тумбочки на столик и включил ее в розетку.\"},{\"id\":394,\"book\":\"ludovik\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Подумай, что происходит с электрическим звонком, когда в доме нет света.\",\"Мог ли незнакомец позвонить в дверь, если вечером в доме был выключен свет?\"],\"short\":\"Если в доме погас свет, звонок не работал, и незнакомец не мог позвонить в дверь: история выдумана.\",\"answer\":\"Если в доме Компара, когда он работал с чертежами, внезапно отключилось электричество, как мог ограбивший инженера незнакомец позвонить в дверь?\"},{\"id\":395,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к тому, как получилась фотография: что на ней справа, а что слева.\",\"Посмотри, какие пуговицы на самом деле у постояльца в жёлтом плаще, и что бывает с негативом, если его напечатать неправильно.\"],\"short\":\"Не ошибся: фотограф перевернул негатив, поэтому на снимке всё зеркально, а пуговицы у постояльца в жёлтом плаще справа.\",\"answer\":\"Нет, не ошибся. Фотограф перевернул негатив, когда печатал снимок. Людовик обратил на это внимание, когда заметил, что у постояльца в жёлтом плаще пуговицы расположены справа, а не слева, как на снимке.\"},{\"id\":396,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись к часам в комнатах: все ли они показывают одно и то же?\",\"Что делают электрические часы, когда в доме пропадает ток?\"],\"short\":\"Жилец с четвёртого этажа: его электрочасы идут правильно, хотя при отключении света они должны были отстать, значит, он был дома и лжёт.\",\"answer\":\"Почти у всех жильцов в комнатах есть часы. У жильца с четвёртого этажа часы электрические, питающиеся от сети. Если вчера он не был дома и вернулся только сейчас, его часы должны отставать от часов соседей примерно на четверть часа — на время отключения тока. Однако они идут правильно. Это делает его заявление о том, будто он не был дома, крайне подозрительным.\"},{\"id\":397,\"book\":\"ludovik\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Обрати внимание, какую цену за статуэтку называет каждый из двоих.\",\"Один назвал статуэтку почти ничего не стоящей, другой в десять раз дороже. Что это говорит о каждом?\"],\"short\":\"Оба: Дюран слишком хорошо помнит статуэтку и называет её ничего не стоящей, а Лямбен завышает её цену в десять раз.\",\"answer\":\"Дюран выдал себя, сказав, что пропавшая статуэтка не стоит и десяти франков, значит, он как минимум хорошо помнит эту вещицу. Но и Лямбен выдал себя, назвав сумму в десять раз большую: он хочет получить крупный куш за дешёвый сувенир.\"},{\"id\":398,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Что на последнем рисунке делает Альфред и какой рукой?\",\"Обрати внимание, в какую сторону повёрнуты ручки чашки и кофейника у Венези.\"],\"short\":\"Альфред — левша: в квартире Венези ручки чашки и кофейника повёрнуты влево, а рюмка и бутылка стоят слева.\",\"answer\":\"Альфред на последнем рисунке пишет левой рукой. Следовательно, он — левша. Когда он пил кофе в доме у г-на Венези, он оставил доказательства своего пребывания в квартире. Действительно, ручка чашки и ручка кофейника повёрнуты влево. Рюмка и бутылка коньяка также расположены с левой стороны. Эти детали не ускользнули от проницательного Людовика.\"},{\"id\":399,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к номерам машин на стоянке: какой из них могли записать неправильно?\",\"Что будет, если прочитать номер не с машины, а в зеркале?\"],\"short\":\"Третья в ряду машина: свидетель записал её номер зеркально, как видел его в зеркале.\",\"answer\":\"Украденная машина — третья в ряду с номером 10AU81. Свидетель видел её номер в зеркале и машинально записал зеркальное отражение номера…\"},{\"id\":400,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись, кто из троих постояльцев говорит о своей прошлой ночи.\",\"Какой снег был у пансионата, когда Людовик туда подходил?\"],\"short\":\"Пьер: он якобы всю ночь отсутствовал, но нетронутый снег у пансионата показывает, что он никуда не уходил.\",\"answer\":\"Украл деньги Пьер. Иначе зачем ему понадобилось бы соврать, будто он отсутствовал всю ночь и только что вернулся? Его изобличает во лжи нетронутый снежный покров, который Людовик видел, подходя к пансионату.\"},{\"id\":401,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Посмотри, в каких единицах измерения указаны размеры на плане.\",\"Сравни год штурма Бастилии с годом введения метрической системы.\"],\"short\":\"Документ — подделка: на плане размеры в метрах, а метрическую систему ввели в 1795 году, позже штурма Бастилии.\",\"answer\":\"План Бастилии, составленный до 1789 г. (года штурма Бастилии), не мог включать измерения в метрах. Метрическая система была введена 7 апреля 1795 г. Поэтому этот план — фальшивка.\"},{\"id\":402,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись, что лежит на столе у последнего из клиентов.\",\"Что принадлежит Турди, но оказалось у последнего клиента?\"],\"short\":\"Дюбуа: на его столе лежит авторучка Турди, значит, агент был у него, и часы, скорее всего, там же.\",\"answer\":\"Людовик обратил внимание, что на столе у последнего из посещённых им клиентов лежит авторучка страхового агента. Если Дюбуа не признался, что агент забыл у него авторучку, то, очевидно, и часы находятся у него.\"},{\"id\":403,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к букету: откуда он мог взяться?\",\"Откуда у Поля мог появиться такой букет, если в секции он его не получал?\"],\"short\":\"Поль не получил букет в секции: он нарвал цветы во дворе дома и выдал их за награду.\",\"answer\":\"Поль нарвал букет во дворе дома…\"},{\"id\":404,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Вспомни, что Людовик делал с портфелем, пока был на берегу.\",\"Посмотри, на какое отверстие ремешка застёгнут портфель.\"],\"short\":\"Портфель открывали: ремешок, застёгнутый на верхнее отверстие, оказался застёгнут на среднее.\",\"answer\":\"Портфель Людовика был застёгнут на верхнее отверстие ремешка, а когда сыщик вылез из воды, то заметил, что теперь портфель застёгнут на среднее отверстие.\"},{\"id\":405,\"book\":\"ludovik\",\"lv\":3,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись к одежде и вещам посетителей: что у кого было, а чего нет.\",\"Что грабитель выбросил или снял, чтобы его не узнали?\"],\"short\":\"Посетитель, который прикуривает сигарету: остальные шестеро не подходят по одежде и облику, а усы у него могли быть фальшивыми.\",\"answer\":\"Людовик исключает шестерых посетителей от подозрений по деталям их одежды и облика:\\n\\n1) Человека в шляпе: грабитель выбросил свою шляпу.\\n\\n2) Человека в плаще: грабитель избавился от плаща.\\n\\n3) Человека с зонтиком: он не стал бы носить плащ и зонт одновременно.\\n\\n4) Человека в очках: грабитель свои выбросил.\\n\\n5) Посетителя за столом: у него есть шляпа.\\n\\n6) Человека с чемоданом: потерпевший отметил бы эту деталь.\\n\\nСледовательно, остаётся посетитель, который прикуривает сигарету. Хотя у него нет усов, это ничего не значит. Он мог носить фальшивые усы, от которых также избавился.\"},{\"id\":406,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к тому, что водитель делал сразу после аварии и где лежат его вещи.\",\"Где должны были оказаться ключи, если бы водителя выбросило из машины при ударе?\"],\"short\":\"Владелец: ключи у него в кармане, а не в замке зажигания, хотя при аварии с выбросом они остались бы в замке.\",\"answer\":\"Если владельца машины выбросило из неё при ударе, то каким образом ключи от машины оказались не в замке зажигания, а у него в кармане?\"},{\"id\":407,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к плащу Адемара на рисунке: как висит пояс и как он заправлен.\",\"Как был повёрнут пояс накануне и как он был повёрнут утром?\"],\"short\":\"Адемар: пояс на плаще заправлен в другую сторону, чем накануне, значит, ночью он выходил в плаще на вечеринку.\",\"answer\":\"Прибыв к Адемару на следующее утро, Людовик заметил, что пояс на плаще молодого человека оказался в противоположном направлении от того, какое он занимал накануне. (См. положение пряжки на рис. 1.) Следовательно, накануне Адемар не послушался Людовика, надел плащ и отправился на вечеринку. Когда его пояс выскочил из плаща, он его заправил в другом направлении.\"},{\"id\":408,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Посмотри, когда Поль утверждает, что получил письмо, и какой тогда был день недели.\",\"Что в воскресенье не делает почтальон, и какой день показывает календарь Людовика?\"],\"short\":\"Поль: он уверяет, что письмо получил в воскресенье, а почта по воскресеньям не доставляется, значит, он просто не хотел ехать.\",\"answer\":\"Поль утверждает, что получил письмо от Людовика только накануне. Очень хорошо! Но почтальон не приносит писем по воскресеньям. (Календарь на рабочем столе Людовика показывает понедельник, четвёртое ноября.) Поль просто не хотел приехать по вызову Людовика.\"},{\"id\":409,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к ящику с вином: как стоят бутылки относительно его краёв?\",\"Сравни высоту бутылок с высотой самого ящика.\"],\"short\":\"Ящик с двойным дном: горлышки бутылок стоят вровень с краем, хотя сами бутылки ниже ящика, значит, снизу что-то спрятано.\",\"answer\":\"Горлышки бутылок находятся на уровне края ящика, но ведь высота бутылок меньше высоты ящика. Следовательно, ящик имеет двойное дно. Там и надо искать контрабанду.\"},{\"id\":410,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись, кто из троих курит и какие предметы у него для этого есть.\",\"Что осталось в пепельнице директорского кабинета после уборки?\"],\"short\":\"Секретарь: в пепельнице директора остался окурок сигареты, а архивариус и чертёжник курят только трубку.\",\"answer\":\"Архивариус и чертёжник курят трубку, как и директор. А в кабинете директора в пепельнице остался окурок от сигареты, который мог оставить только секретарь, т.к. утром уборщица убрала все в кабинете.\"},{\"id\":411,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к вензелям на белье: какие буквы на них вышиты?\",\"Сравни инициалы на украденных вещах с инициалами путешественников.\"],\"short\":\"Симон Боули: украденное бельё вышито вензелями «С.Б.», а это его собственные инициалы.\",\"answer\":\"Бельё, вышитое вензелями отеля, имеет инициалы «С.Б.». Людовик считает, что это г-н Симон Боули мог похитить бельё, которое имеет такие же вензеля, как и его собственные инициалы.\"},{\"id\":412,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к отдушине: что через неё можно достать из подвала?\",\"Чем можно достать предмет через узкую отдушину, не заходя в подвал?\"],\"short\":\"Секретарь полковника: через отдушину он достал документы удочкой при свете фонарика.\",\"answer\":\"Вором является секретарь полковника. Для кражи он использовал удочку и фонарик для освещения.\"},{\"id\":413,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Подумай: кто из встреченных людей мог видеть мотоцикл, а кто нет?\",\"Ни один из встреченных людей мотоцикл не видел. Что в этом значит?\"],\"short\":\"Мотоцикл спрятан в голубом грузовике: на дорогах его никто не встретил, значит, его где-то укрыли.\",\"answer\":\"Если никто не встретил мотоцикл — это значит, что его спрятали! Но где? И почему бы не в голубом грузовике? Это Людовик и собирается срочно проверить.\"},{\"id\":414,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к продуктам на кухне: что в них свежее, а что в избытке?\",\"Свежий хлеб и полный холодильник: что из этого говорит о давности покупок?\"],\"short\":\"Джо лжёт: свежий хлеб говорит о недавней покупке, а полный холодильник показывает, что запасы он не расходовал.\",\"answer\":\"Два факта доказывают, что Джо лжёт. Во-первых, Людовик заметил свежий хлеб. Следовательно, он был куплен недавно. Во-вторых, холодильник был полностью забит продуктами! Если бы Джо питался в течение двух дней этими запасами, то продуктов в холодильнике осталось бы намного меньше.\"},{\"id\":415,\"book\":\"ludovik\",\"lv\":1,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к тому, сколько мест в машине и как устроено заднее сиденье.\",\"Сколько человек уместится на заднем диване, если посередине подлокотник?\"],\"short\":\"Пятеро в одной машине не поместились: в этой модели на заднем сиденье умещаются только двое, посередине подлокотник.\",\"answer\":\"В данной модели машины на заднем сидении могут сидеть только двое пассажиров, т.к. посередине там находится подлокотник.\"},{\"id\":416,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись, как лежит шнур телефонной трубки, и вспомни, как он лежал раньше.\",\"Как изменилось положение шнура трубки относительно кабеля, пока Людовика не было?\"],\"short\":\"Леон: он звонил сам в отсутствие Людовика — шнур трубки теперь лежит над кабелем, а раньше был под ним.\",\"answer\":\"Леон лгал, говоря, что не звонил. Шнур от телефонной трубки находится над телефонным кабелем, хотя ранее он был под ним. Следовательно, Леон пользовался аппаратом во время отсутствия Людовика.\"},{\"id\":417,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к комнате охранника: всё ли там стоит на своих местах?\",\"Чего не хватает в вазе на столе у охранника?\"],\"short\":\"Охранник: в вазе не хватает одного цветка, а такая же роза была в петлице служащего, выходившего через проходную.\",\"answer\":\"Охранник лжёт: в вазе не хватает одного цветка, а у одного из служащих, выходившего через проходную, в петлице была эта самая роза.\"},{\"id\":418,\"book\":\"ludovik\",\"lv\":1,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к рыбам в корзине: что это за рыба?\",\"Какую рыбу не ловят в море?\"],\"short\":\"Дюколе: в корзине форель, а её не ловят в море — рыба речная, значит, алиби не подтверждается.\",\"answer\":\"Форель не ловят в море! Алиби Дюколе не подтверждается.\"},{\"id\":419,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к обуви Фуше и вспомни, какая была погода утром.\",\"Какая погода была утром, когда Фуше, по его словам, отправился на рыбалку?\"],\"short\":\"Фуше: он говорит, что ушёл на рыбалку в 10 утра, но в то утро лил дождь — в такую погоду он не надел бы лёгкие кроссовки.\",\"answer\":\"Потому что Фуше сказал, что отправился на рыбалку в 10 часов. Но, как известно, всё утро шёл проливной дождь. Не думаете же вы, что, уходя в это время, он надел бы такие лёгкие кроссовки?\"},{\"id\":420,\"book\":\"ludovik\",\"lv\":3,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к волосам человека, который называет себя Жаном.\",\"С какой стороны у Жана Гарена пробор и с какой — у человека, назвавшегося им?\"],\"short\":\"Альберт: он выдаёт себя за брата-близнеца Жана, которого убил, а пробор у него справа, тогда как у Жана слева.\",\"answer\":\"Людовик сразу же увидел, что он имеет дело не с Жаном Гареном, а с его братом-близнецом Альбертом. Он завлёк брата в ловушку и хладнокровно выстрелил в него, чтобы занять его место и наслаждаться его состоянием благодаря их удивительному сходству. К несчастью для него, Людовик заметил, что пробор в волосах у него был с правой стороны, в то время как у Жана Гарена пробор был с левой стороны.\"},{\"id\":421,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к машине Шторба, когда он вернулся к ней.\",\"Что изменилось в машине Шторба, пока детективы за ним следили?\"],\"short\":\"Сообщник взял наркотики из машины Шторба, пока его выслеживали: дворники на ней стояли в другом положении.\",\"answer\":\"Людовик заметил, что дворники на машине Шторба изменили положение. Это свидетельствует о том, что в то время, как он позволил детективам устроить за собой слежку, его сообщник воспользовался его машиной и забрал оттуда наркотики. Он допустил неосторожность, включив дворники во время дождя…\"},{\"id\":422,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к пепельнице и к тому, кто что курит.\",\"Чьи окурки лежат в пепельнице — курильщика трубки или сигарет?\"],\"short\":\"Второй посетитель: окурки в пепельнице от сигарет, а первый курит трубку — значит, второй уже был в бюро.\",\"answer\":\"Окурки в пепельнице доказывают, что «второй посетитель» уже был в бюро! Действительно, ведь другой посетитель курит трубку.\"},{\"id\":423,\"book\":\"ludovik\",\"lv\":1,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к постели в спальне.\",\"Что нехарактерного в том, как застелена постель, если в доме был грабитель?\"],\"short\":\"Даржан сам инсценировал ограбление: постель «ограбленного» аккуратно застелена, а грабитель не стал бы её заправлять.\",\"answer\":\"Обратите внимание, что постель «ограбленного» аккуратно застелена. Вряд ли преступник, связав Даржана и присвоив драгоценности, привёл в порядок его ложе. Это и позволило Людовику обвинить Даржана в инсценировке ограбления.\"},{\"id\":424,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись к размерам чемоданов.\",\"Могли ли маленькие чемоданы поместиться в большой, если у всех разные размеры?\"],\"short\":\"Мошенник вложил три маленьких чемодана в большой, унёс их с собой и потом потребовал компенсацию от отеля.\",\"answer\":\"Людовик заметил, что четыре чемодана мошенника были различного размера и могли быть вложены один в другой. Мошенник, уходя из отеля, сложил три маленьких чемодана в большой и унёс их, чтобы потом получить от отеля компенсацию за их пропажу.\"},{\"id\":425,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к щели водосточного люка.\",\"Как стоит щель люка сейчас и как она стояла, когда Людовик проходил здесь раньше?\"],\"short\":\"Грабитель в водостоке: щель люка теперь стоит под углом к тротуару, хотя раньше была параллельна — значит, люк подняли.\",\"answer\":\"Людовик очень наблюдателен, и он заметил, что щель водосточного люка располагается под углом по отношению к тротуару. Но когда он проходил через этот тупик ранее, щель была параллельна тротуару. Следовательно, её поднимали. Но кто? Тот, кто скрылся в водостоке.\"},{\"id\":426,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к фамилиям пассажиров — особенно ко второму.\",\"Что общего у фамилии второго пассажира с именем разыскиваемого?\"],\"short\":\"Второй пассажир: его фамилия ТОИРАНС — это фамилия Ратисона с перемешанными буквами.\",\"answer\":\"Людовик обратил внимание на фамилию второго пассажира — ТОИРАНС. И понял, что это фамилия разыскиваемого — РАТИСОН, в которой просто перемешаны буквы.\"},{\"id\":427,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к ковру в кабинете.\",\"Какие следы должен был оставить тяжёлый сейф на ковре с высоким ворсом?\"],\"short\":\"Сейфа не было: на ковре с высоким ворсом нет следов от тяжёлого сейфа — Компле инсценировал кражу ради мошенничества.\",\"answer\":\"Дверь, что вполне очевидно, была взломана любителем. Во-вторых, тяжёлый сейф, стоявший на ковре с высоким ворсом, должен был оставить на нём след. Поэтому Людовик уверен, что сейфа здесь никакого не было, а речь идёт об обычном мошенничестве со стороны М. Компле.\"},{\"id\":428,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к книге в руках одного из попутчиков.\",\"Что стало с закладкой книги после выхода из туннеля?\"],\"short\":\"Мужчина с книгой: после туннеля закладка стала длинной — значит, книга перевёрнута, он её откладывал, пока крал брошь.\",\"answer\":\"Это мужчина с книгой в руке. Его книга имеет ленточную закладку, которая крепится к верхнему корешку книги и выходит на небольшое расстояние из нижнего края книжного блока. Но при выходе поезда из туннеля она оказалась очень длинной, что указывает на то, что мужчина держит свою книгу вверх тормашками. Следовательно, он откладывал книгу, чтобы похитить брошь, а затем случайно её перевернул, изображая безотрывное чтение.\"},{\"id\":429,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к зонтику, рюмкам и пепельнице.\",\"Сколько рюмок на столике и кто их мог поставить, если хозяин живёт один и не курит?\"],\"short\":\"Жюстен был в доме: мокрый зонтик, две рюмки и дымящаяся сигарета в пепельнице, хотя хозяин жил один и не курил.\",\"answer\":\"На улице идёт дождь. Хозяин из дома не выходил. Тогда кому принадлежит мокрый зонтик на втором рисунке? На четвёртом рисунке на столике стоят две рюмки, а хозяин утверждает, что он живёт один и отказывается от сигареты, так как он не курит. А на третьем рисунке в пепельнице дымится сигарета. Всё это и позволило Людовику понять, что хозяин его обманывает, а Жюстен только что был у него.\"},{\"id\":430,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Сравни, что было у гостей в начале вечера и что стало в конце.\",\"Что оказалось на руке хозяина дома и в вазе с цветами к концу вечера?\"],\"short\":\"Хозяин дома: к концу вечера на его руке часы гостя, а ожерелье ушедшей дамы спрятано в вазе — он клептоман.\",\"answer\":\"В начале вечера (рисунок № 1): у одного из гостей на запястье наручные часы, у другого в кармашке пиджака авторучка, и у обоих дам ожерелья.\\n\\nВ конце вечера (рисунок № 2): Людовик замечает, что у хозяина на руке появились часы гостя, а авторучку другого он положил в карман своей жилетки. У дамы, которая уходит, больше нет ожерелья, оно теперь находится в вазе с цветами, где было спрятано. Хозяин дома — клептоман, который пригласил Людовика для отвода глаз.\"},{\"id\":431,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Не окурки, а кое-что другое на столе: присмотрись к перчаткам.\",\"Для какой руки перчатка на столе и какую перчатку надел Бромский?\"],\"short\":\"Бромский: перчатка на столе для левой руки, как и та, что он надел, — значит, сообщник унёс свою пару и оставил эту.\",\"answer\":\"Очевидно, что речь не идёт о двух окурках в пепельнице, которые ничего не доказывают. Дело в паре перчаток — у сообщников были одинаковые перчатки, и тот, который ушёл, случайно унёс две перчатки с одной руки. Людовик заметил, что элегантный г-н Бромский надел перчатку на левую руку, а перчатка, лежащая на столе, тоже для левой руки.\"},{\"id\":432,\"book\":\"ludovik\",\"lv\":3,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к шляпам посетителей у барной стойки.\",\"Какая деталь на шляпе торговца отличалась от шляпы сообщника?\"],\"short\":\"Сообщники обменялись шляпами, в одной из которых был пакетик: лента шляпы торговца намного шире, чем у сообщника.\",\"answer\":\"Подозреваемый скрыл пакетик наркотика во внутренней части своей шляпы. Сообщникам для передачи товара было достаточно обменяться своими шляпами, которые были похожи друг на друга. Но Людовик это заметил, так как лента шляпы торговца намного шире, чем лента шляпы его сообщника.\"},{\"id\":433,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к обуви Аниты, когда она выходила из домика.\",\"Что скрывали съёмные части обуви Аниты?\"],\"short\":\"Микроплёнки были в съёмных каблуках сапог Аниты: Людовик заметил это, когда она выходила из домика.\",\"answer\":\"Микроплёнки находились в съёмных каблуках сапог Аниты. Людовик заметил это, когда она вышла из домика (арендатора которого скоро тоже ждёт арест).\"},{\"id\":434,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к часам у проходной.\",\"Сколько было времени, когда подозреваемый вышел из проходной, и что бывает в это время?\"],\"short\":\"В ресторан на обед: когда он вышел из проходной, часы показывали 13:15, а магазины и службы в это время закрыты.\",\"answer\":\"Когда подозреваемый вышел из проходной, часы показывали 13:15. Это обеденное время. Значит, он зашёл пообедать в ресторан. Тем более что все магазины и предприятия бытового обслуживания тоже закрыты на обед.\"},{\"id\":435,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Подумай, что нужно, чтобы починить колесо, и что было под рукой у Горация.\",\"Что нужно, чтобы накачать колесо после прокола, и было ли это у Горация?\"],\"short\":\"Гораций лжёт: без велосипедного насоса он не мог сам починить колесо грузовика.\",\"answer\":\"Как Гораций мог самостоятельно починить колесо, если у него не было даже велосипедного насоса!\"},{\"id\":436,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Посмотри внимательно, что происходило в толпе, пока все глазели на разбитую витрину.\",\"Сравни первый и последний рисунки: у кого оказались часы и кто был рядом?\"],\"short\":\"Вор из толпы в комбинезоне и клетчатой кепке: пока все смотрели на витрину, он вытащил часы у мужчины с портфелем.\",\"answer\":\"В толпе находился опытный преступник. Одетый, для отвода глаз, в комбинезон и клетчатую кепку, он, пользуясь тем, что общее внимание было обращено на витрину магазина, украл часы у мужчины с портфелем в руках. Глядя на первый и последний рисунок, можно увидеть, как часы «поменяли» своего хозяина и оказались на руке у воришки.\"},{\"id\":437,\"book\":\"ludovik\",\"lv\":3,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к записке из бумажника и к её последней строке, которую Людовик принял за подпись.\",\"Попробуй сопоставить цифры в записке с номерами букв в алфавите.\"],\"short\":\"Лоу Стик: в записке киллера, зашифрованной цифрами, он назван заказчиком, «Убей Людовика».\",\"answer\":\"Людовик установил взаимосвязь между этим покушением на него и расследованием, которое он вёл. Изучая странную записку, он решил, что последняя строка могла быть подписью, а эти цифры могли обозначать имя Лоу Стика. Проверка позволила ему констатировать, что определённые цифры совпадают с соответствующими буквами алфавита: 1=А, 3=Б, 5=В и т.д. Это позволило ему расшифровать записку, в которой было написано: «УБЕЙ ЛЮДОВИКА. ЛОУ СТИК».\\n\\nПоэтому он и приказал его арестовать, так как теперь есть неопровержимые доказательства причастности Стика к преступлению.\"},{\"id\":438,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Обрати внимание на того, кто вышел из магазина в шляпе и очках, и на то, что он мог оставить.\",\"Кто оставил берет на полке, и тот ли это человек, который вышел в шляпе и очках?\"],\"short\":\"Продавец: в шляпе и тёмных очках он вынес товар в портфеле, вернулся переодетым, а забытый на полке берет его выдал.\",\"answer\":\"Все просто. Продавец, замаскировавшись тёмными очками, шляпой и высоко поднятым воротником пальто, вышел из магазина с портфелем, в котором он вынес похищенный им товар, и через некоторое время вернулся назад, переодевшись в другую одежду. Людовик это понял, заметив на полке берет, который неосторожный расхититель оставил на полке.\"},{\"id\":439,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Сравни, как лежали вещи на пляже до купания г-на Флюе и после него.\",\"Лопата лежала справа от молодого человека. Где она оказалась потом?\"],\"short\":\"Молодой сосед: он зарыл транзистор в кучу песка, лопата переехала на другую сторону, а куча изменила форму.\",\"answer\":\"Сосед утверждал, что он спал, но Людовик обратил внимание на то, что лопата, которая раньше лежала с правой стороны от молодого человека, переместилась на левую сторону. Да и куча песка изменила свою форму. Абсолютно точно, что это молодой человек похитил транзистор и зарыл его в кучу песка, чтобы потом оттуда его забрать попозже.\"},{\"id\":440,\"book\":\"ludovik\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Подумай, кого из троих мог бы поймать каждый бегун, если бы просто обернулся.\",\"Представь, что вор второй: кто из бегущих мог бы его поймать, обернувшись?\"],\"short\":\"Первый из «бегунов»: если бы вор был вторым или третьим, соседний бегун поймал бы его, просто обернувшись.\",\"answer\":\"Если бы вор был третьим, то второму достаточно было обернуться, чтобы его задержать. А если бы вор был вторым, то его легко мог задержать, обернувшись, первый бегущий. Следовательно, вором является первый из «бегунов».\"},{\"id\":441,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Подумай, где на катере таможенники не искали, и что на рисунке видно про катер.\",\"Катер стоит на якоре. Что можно было привязать к якорному канату и куда это опустить?\"],\"short\":\"На дне моря: водонепроницаемый мешок с сигарами Дуфило прицепил к якорному канату и опустил вместе с якорем.\",\"answer\":\"Единственное место, где Людовик с капитаном не искали контрабанду, — это под водой. На рисунке видно, что катер Дуфило поставлен на якорь. Увидев таможенный корабль, ему не составляло большого труда прицепить к якорному канату водонепроницаемый мешок с сигарами и отправить его на дно вместе с якорем.\"},{\"id\":442,\"book\":\"ludovik\",\"lv\":1,\"pic\":false,\"ok\":3,\"hints\":[\"Подумай, как обычно ведёт себя собака, когда хозяин возвращается после долгой отлучки.\",\"Собака Джо спокойна при встрече. Что это говорит о том, разлучались ли они?\"],\"short\":\"Джо не уезжал: его собака спокойно встретила хозяина, а после недельной разлуки она бы бурно радовалась.\",\"answer\":\"Любой, у кого есть собака, сразу понял, в чём дело. Если бы Джо возвратился после недельного отсутствия, то собака стала бы активно выражать свою радость по поводу его появления. А собака Джо была абсолютно спокойна, что свидетельствует о том, что она рассталась с хозяином совсем недавно.\"},{\"id\":443,\"book\":\"ludovik\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Послушай, что говорит каждый из троих, и на кого кто указывает.\",\"Один из троих говорит, что ничего не видел, но обвиняет другого. Сходятся ли его слова?\"],\"short\":\"Посетитель в шляпе: на него указали двое, а сам он обвинял другого, хотя говорит, что ничего не видел.\",\"answer\":\"Двое посетителей указывают на мужчину в шляпе, хотя тот, в свою очередь, обвиняет в содеянном другого. Людовик догадался, что преступником является именно посетитель в шляпе. Как он может обвинять кого-то, если по его словам он смотрел в окно и ничего не видел?\"},{\"id\":444,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Обрати внимание на колодец и на то, где стояла верёвка для ведра, когда Людовик пришёл и когда уходил.\",\"Пока Людовик был в доме, кто ненадолго выходил под каким-то предлогом?\"],\"short\":\"Жена Лесажа: под предлогом чашек для чая она спрятала драгоценности в ведре и опустила его в колодец.\",\"answer\":\"Обратите внимание на колодец. Когда Людовик заходил в дом, верёвка для ведра находилась вне колодца. Однако когда он уходил, верёвка была уже внутри колодца! Следовательно, жена Лесажа под предлогом принести чашки для чая вышла из дома, спрятала драгоценности в ведре и опустила его в колодец.\"},{\"id\":445,\"book\":\"ludovik\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Сравни, что говорят жильцы о своей переписке и как давно у них пропадают письма.\",\"Жилец со второго этажа ждёт вестей от больного дяди. Когда тот заболел?\"],\"short\":\"Жилец со второго этажа: он ждёт вестей от больного дяди, но тот заболел неделю назад, а письма пропадают месяц.\",\"answer\":\"Это жилец со второго этажа, который сказал, что ожидает известий от своего больного дяди. Если письма пропадают уже месяц, то как он узнал, что его дядя заболел во вторник, то есть не более недели назад? Следовательно, он лжёт.\"},{\"id\":446,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к манжету на руке, которая залезла в карман, и к тому, кто в зале был в белой рубашке.\",\"У вора должна быть белая рубашка. Кто из посетителей вытирал руки, и какого цвета была рука вора?\"],\"short\":\"Мужчина, вытирающий руки полотенцем: у вора белый манжет, а рука, вытащившая бумажник, светлая.\",\"answer\":\"Судя по белому манжету на руке, которая лезла в карман, у вора должна быть белая рубашка. Белые рубашки только у двоих. Один из них темнокожий, но рука, вытягивающая бумажник, была светлой. Следовательно, преступником является мужчина, вытирающий руки полотенцем.\"},{\"id\":447,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Посмотри, какой отвёрткой мастер пользовался и какие винты у крышки телевизора.\",\"Крышка держится на крестовых винтах. Подходит ли лежащая рядом плоская отвёртка?\"],\"short\":\"Мастер не открывал телевизор: он говорил, что закрутил крышку, но плоская отвёртка не подходит к крестовым винтам.\",\"answer\":\"Мастер сказал, что завинтил крышку телевизора перед самым приходом Людовика. Рядом с телевизором лежит обычная плоская отвёртка с широкой головкой, которой невозможно отвернуть и завернуть крестообразные винты крышки телевизора. Следовательно, мастер сделал обычную настройку телевизора, не открывая его.\"},{\"id\":448,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Вспомни, что детективы видели на чердаке и в каком состоянии там было окно.\",\"Окно чердака при обыске было закрыто, а потом открыто. Что это значит?\"],\"short\":\"На чердаке: окно, закрытое при обыске, оказалось открытым, значит, Цезарь ушёл через крышу.\",\"answer\":\"Когда детективы осматривали чердак, то единственное окошко на чердаке было закрыто, а когда Людовик возвращался из магазина, оно было открыто. Это позволяет сделать вывод о том, что Цезарь скрывался на чердаке и смог убежать от детективов через крышу.\"},{\"id\":449,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Сравни положение глобуса до ухода Людовика и после возвращения: что изменилось?\",\"Кого Людовик предупреждал Лукаса остерегаться и мог ли тот зайти в кабинет, пока Лукас спал?\"],\"short\":\"Джой «Шрам»: глобус на столе стоял не так, как раньше, а Лукас в это время спал на диване.\",\"answer\":\"Когда детектив зашёл к себе в кабинет, он сразу заметил, что глобус на столе стоит не так, как он стоял до этого. Следовательно, Джой «Шрам» всё-таки проник в его кабинет, а его беспечный помощник не заметил этого, так как спал в это время.\"},{\"id\":450,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Посмотри, что мешало водителю видеть дорогу сзади и в каком состоянии было его боковое зеркало.\",\"Что закрывало заднее стекло и что случилось с боковым зеркалом?\"],\"short\":\"Водитель лжёт: сумки закрывали заднее стекло, а боковое зеркало разбито, скорее всего, в аварии.\",\"answer\":\"Людовик обратил внимание на то, что у водителя не было возможности что-либо наблюдать в зеркало заднего вида внутри автомобиля, так как обзор через заднее стекло был закрыт большими сумками. А боковое зеркало было разбито, скорее всего, при аварии.\"},{\"id\":451,\"book\":\"ludovik\",\"lv\":3,\"pic\":true,\"ok\":1,\"hints\":[\"Посмотри, как стоит настольная лампа на стойке и что там с проводом.\",\"Хватило бы длины провода лампы, чтобы включить её в розетку?\"],\"short\":\"Ночной сторож: он спал вместо того, чтобы следить за входом; лампа на стойке не работала, провод не доставал до розетки.\",\"answer\":\"Людовик обвинил ночного сторожа в том, что он спал вместо того, чтобы следить за входом. Он не пользовался настольной лампой на стойке: провод висит с боку стойки, да и, как видно на втором рисунке, его длины не хватает, чтобы достать до розетки. Кроме этого, Людовик обнаружил, что вор не мог покинуть номер через оконную дверь: оказавшись снаружи на улице, он не смог бы закрыть окно изнутри.\"},{\"id\":452,\"book\":\"ludovik\",\"lv\":3,\"pic\":true,\"ok\":3,\"hints\":[\"Обрати внимание на верёвку и на то, как рабочие поднимали ведра наверх.\",\"Хватило бы длины верёвки, чтобы поднимать и опускать ведра между людьми внизу и наверху?\"],\"short\":\"Двое «строителей»: их напарник говорит, что поднимал ведра наверх, но верёвка слишком коротка, значит, они лгали.\",\"answer\":\"Человек, находившийся внизу около водопровода, заявляет, что он подавал наверх ведра своему коллеге с помощью подъёмника, но это невозможно было сделать, так как верёвка была недостаточной длины, чтобы поднимать и опускать ведра. Следовательно, эти люди лгали, что они строители. Они воспользовались для совершения кражи тем обстоятельством, что наступило обеденное время и настоящие строители ушли на обед, оставив строительную люльку без присмотра.\"},{\"id\":453,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Посмотри, какие следы на дороге лежат поверх других, и что было раньше.\",\"Чьи следы сверху: грузовика или легковушки? Что это говорит о том, кто проехал позже?\"],\"short\":\"Дюпне, владелец разбитой легковушки: следы грузовика лежат поверх его следов, значит, он лжёт.\",\"answer\":\"Людовик обратил внимание, что следы от грузовика проходят поверх следов от легковушки. Следовательно, грузовик проехал уже после легковой машины, а её водитель лжёт.\"},{\"id\":454,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к капоту машины Жужу и к тому, какая была погода в то утро.\",\"Если Жужу приехал полчаса назад, что должно было случиться со снегом на капоте при ясной погоде?\"],\"short\":\"Жужу лжёт: на капоте его машины толстый слой снега, а при ясной погоде за полчаса он растаял бы и слетел.\",\"answer\":\"Людовик заметил, что на капоте автомобиля лежит достаточно толстый слой снега. Жужу же утверждает, что приехал на машине всего полчаса назад. В этом случае на капоте автомобиля не было бы снега. Он бы растаял и слетел по дороге. А так как погода установилась ясная, то нового снега на капоте быть не могло. Следовательно, Жужу лжёт.\"},{\"id\":455,\"book\":\"ludovik\",\"lv\":1,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к деталям пейзажа на картине.\",\"Сравни даты жизни Коро с тем, что изображено на заднем плане картины.\"],\"short\":\"На картине нарисована линия электропередачи, а Коро жил с 1796 по 1875 год: картина — подделка.\",\"answer\":\"Линия электропередачи не могла быть нарисована на картине у Коро, который жил с 1796 по 1875 год. Разумеется, такая картина является подделкой.\"},{\"id\":456,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Внимательно рассмотри каждого посетителя на картинке.\",\"Сравни обувь грабителя с обувью посетителей.\"],\"short\":\"Посетитель, стоявший посередине: на нём такие же туфли, какие были у грабителя.\",\"answer\":\"По туфлям. Только у одного посетителя (стоящего посередине) на ногах такие же туфли, какие были у грабителя.\"},{\"id\":457,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Подумай, что Людовик увидел, вернувшись домой, и что это говорит о времени.\",\"Что стало с вязаньем, которое мадам Роза оставила на кресле?\"],\"short\":\"Роза давно вернулась домой: вязанье на кресле продвинулось, значит, она пропустила Гастона.\",\"answer\":\"Уходя из дома вместе с Людовиком, мадам Роза положила вязанье на кресло. Вернувшись, Людовик заметил, что вязанье, лежавшее на кресле, сильно продвинулось. Следовательно, мадам Роза давно возвратилась домой и поэтому пропустила появление Гастона.\"},{\"id\":458,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к одежде джентльмена и к тому, куда она делась во время досмотра.\",\"Что случилось с клетчатым плащом, пока на чемоданчик ставили отметку?\"],\"short\":\"Джентльмен: алмазы спрятаны в клетчатом плаще, который он убрал в чемоданчик, пока ставили отметку.\",\"answer\":\"Людовик заметил, что путешественник скромно положил свой клетчатый плащ в чемоданчик, в то время как на чемоданчик ставили отметку «ПРОВЕРЕНО». Детектив сделал вывод, что алмазы спрятаны в плаще.\"},{\"id\":459,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к письму на столе и к тому, в каких условиях его писали.\",\"Мог ли кто-то писать так аккуратно, когда корабль качает сильный шторм?\"],\"short\":\"Писатель Пьер де Нои: письмо, написанное ровным почерком в шторм, — заранее подготовленное алиби.\",\"answer\":\"Людовик обратил внимание на то, что письмо было написано ровным, аккуратным почерком. Но писать так аккуратно во время сильного шторма на корабле невозможно. Пьер де Нои подготовил себе заранее весьма плохое алиби.\"},{\"id\":460,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Осмотри комнату, особенно то, что висит на стене над камином.\",\"Что стоит выше камина и как его наклон помогает игроку видеть чужие карты?\"],\"short\":\"Наклонённое зеркало над камином: в нём Детурн видит карты соперника во время игры.\",\"answer\":\"Осмотрев квартиру, Людовик установил, что мошенник во время игры может видеть карты своего противника благодаря наклонённому зеркалу, прикреплённому выше камина. Жан Детурн был арестован за мошенничество.\"},{\"id\":461,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись, что Людовик делал у прилавков, хотя ничего не покупал.\",\"Вспомни, как Людовик шёл к выходу и что он мог унести, оставшись незамеченным.\"],\"short\":\"Сам Людовик: незаметно унёс трубку со стенда и доказал, что продавцы невнимательны.\",\"answer\":\"Кража была совершена. Людовик, который ничего не покупал, вышел всё же из магазина с трубкой, которую он незаметно взял со стенда возле отдела галантереи. Он сделал это, чтобы убедиться, что в магазине легко совершить кражу. Из этого он заключил, что в увеличении количества краж виноваты в первую очередь продавцы, которые довольно невнимательны.\"},{\"id\":462,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Обрати внимание, как подозреваемый держит свой чемодан в руках.\",\"Сколько рук понадобилось бы, чтобы поднять чемодан, в котором только бельё?\"],\"short\":\"Чемодан с одним бельём слишком тяжёлый: его поднимают двумя руками — в нём второе дно с золотом.\",\"answer\":\"Когда человек держит чемодан в руках, заметно, что он довольно тяжёлый. Ему даже приходится поднимать его двумя руками, хотя чемодан должен быть лёгким, ведь в нём нет ничего, кроме белья. Из этого Людовик делает вывод, что в чемодане есть второе дно, где оборудован тайник с контрабандным золотом. Это и является причиной необычного веса чемодана.\"},{\"id\":463,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к позе погибшего и к тому, как лежал пистолет.\",\"В какой руке держал пистолет Дюплан и в какой висок, по всей видимости, он выстрелил?\"],\"short\":\"Мартэн: пистолет был в правой руке Дюплана, а рана в левом виске — инсценировка.\",\"answer\":\"Во-первых, письмо напечатано на машинке (не важно, кто это сделал).\\n\\nВо-вторых, ящики стола открыты и их содержимое в беспорядке (кто-то проявил любопытство).\\n\\nГлавное же: Дюплан лежал на полу, держа пистолет в правой руке. Следовательно, он не мог выпустить пулю себе в левый висок.\\n\\nВсё это вместе с рассказом Мартэна о том, как он обнаружил труп, и его попыткой привлечь внимание к «посланию погибшего» позволило Людовику обвинить его в убийстве.\"},{\"id\":464,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к руке Эрнеста в вагоне и при выходе.\",\"Что случилось с часами на руке пассажира в клетчатом пиджаке во время выхода?\"],\"short\":\"Эрнест: в дороге часов на руке не было, а при выходе появились — украл у пассажира в клетчатом пиджаке.\",\"answer\":\"Людовик заметил, что у Эрнеста, когда тот садился в поезд и во время поездки, не было часов на руке. Однако при выходе из вагона часы появились. В то же время часы исчезли с руки пассажира в клетчатом пиджаке: карманник украл их.\"},{\"id\":465,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к свитеру под курткой у человека, который вышел из дверей.\",\"Посчитай полоски на свитере вора и на свитере того, кто вышел из дверей.\"],\"short\":\"Человек из дверей не вор: под курткой у него свитер с восемью полосками, а у вора было семь.\",\"answer\":\"Шерлок Холмс, Эркюль Пуаро и комиссар Мегре восхитились бы наблюдательностью Людовика: ему хватило беглого взгляда, чтобы заметить, что куртка этого человека надета на свитер с восемью полосками, а на свитере вора их было семь. За столь короткий срок вор не успел бы поменять свитер.\"},{\"id\":466,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись, на какой высоте лежали рулоны, когда ящик только открыли.\",\"Сравни высоту, на которой лежали рулоны, с высотой самого ящика.\"],\"short\":\"Рулоны обоев не доставали до верхнего края ящика — значит, там двойное дно, где прячут фальшивые деньги.\",\"answer\":\"Когда ящик открыли, было видно, что рулоны обоев находятся на уровне верхнего края ящика. Когда же их вытащили, Людовик обратил внимание, что рулоны не доходят до верхнего уровня. Это позволило ему сделать вывод, что в ящике оборудовано двойное дно, которое он и решил проверить.\"},{\"id\":467,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Сколько стаканов стояло на столе, когда в квартиру вошёл Людовик?\",\"Что сосед мог сделать со стаканом, пока Людовик звонил вниз?\"],\"short\":\"Сосед: второй стакан с его отпечатками он спрятал, как только Людовик намекнул на отпечатки пальцев.\",\"answer\":\"Когда Людовик вошёл в комнату, на столе стояли бутылка и два стакана. Сосед утверждал, что ни к чему не прикасался, но один из стаканов исчез.\\n\\nПо всей видимости, драка произошла в результате ссоры, и сосед, взволнованный случившимся, бросился за детективом, пытаясь таким образом отвести подозрения от себя. Но после того, как Людовик намекнул, что на месте могут обнаружить отпечатки пальцев преступника, сосед решил спрятать стакан с его отпечатками.\"},{\"id\":468,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Посмотри, как повязан платок на лице у каждого из троих на фото.\",\"Что могло быть видно у одного из троих, если платок завязан не там, где положено?\"],\"short\":\"Джино-Цыган: платок повязан над ушами, чтобы скрыть серьгу, по которой его могли опознать.\",\"answer\":\"Платок, которым закрывают нижнюю часть лица, всегда завязывают под ушами, иначе он будет всё время наползать на глаза. Но в данном случае преступник завязал платок над ушами. Людовик пришёл к выводу, что так он хотел скрыть какую-то деталь своего облика, которая могла его изобличить. Так действовать мог только Джино-Цыган, которого можно было опознать по серьге в ухе.\"},{\"id\":469,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к письму, которое Артур показал Людовику, и к тому, чем его якобы писали.\",\"Могло ли письмо быть дописано ручкой, колпачок которой оставался закрытым?\"],\"short\":\"Письмо незаконченное, но авторучка была закрыта: писать ею нельзя, письмо подготовлено заранее.\",\"answer\":\"Письмо незаконченное, но авторучка была закрыта. Писать ею было нельзя, значит, письмо не писалось в момент нападения: Артур подготовил его заранее, чтобы выглядеть жертвой.\"},{\"id\":470,\"book\":\"ludovik\",\"lv\":1,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к тому, что было в квартире, когда Людовик вернулся домой.\",\"Что сделали с антенной, чтобы поймать программу лучше?\"],\"short\":\"Легаль: антенна телевизора была повёрнута — значит, он смотрел телевизор, пока рылся в бумагах.\",\"answer\":\"Телевизионная антенна была повёрнута. Следовательно, Легаль заходил в квартиру и смотрел телевизор, пока рылся в бумагах Людовика.\"},{\"id\":471,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к знакам у бистро, где стояла машина Малыша Луи.\",\"Могла ли машина две недели простоять там, где запрещена стоянка?\"],\"short\":\"Малыш Луи: по знаку «стоянка запрещена» его машина не могла две недели стоять у бистро — он лгал.\",\"answer\":\"Рядом с бистро, где Малыш Луи припарковал свой автомобиль, стоит знак, запрещающий стоянку автотранспорта. Значит, машина не могла стоять на этом месте две недели, как утверждал подозреваемый. Поэтому Людовик не поверил его объяснениям.\"},{\"id\":472,\"book\":\"ludovik\",\"lv\":1,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись к картам, которые остались на столе после игры.\",\"Сколько туза пик должно быть в одной колоде и сколько их нашёл Людовик на столе?\"],\"short\":\"Игрок: в колоде оказалось два туза пик — значит, карты подтасованы.\",\"answer\":\"Мужчина утверждает, что не жульничал, но Людовик обнаружил, что в игре было использовано два туза пик.\"},{\"id\":473,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к волосам Тапиона и сравни с тем, как он выглядел раньше.\",\"Что на голове может выглядеть как настоящие волосы и быстро «отрасти»?\"],\"short\":\"Под париком: волосы Тапиона за короткое время «выросли» — на нём был парик, а под ним плёнка.\",\"answer\":\"Людовик обратил внимание, что волосы у Тапиона странным образом выросли с того момента, как они виделись в прошлый раз (это заметно по бакенбардам, чёлке и волосам на затылке). Единственное объяснение этому: Тапион надел парик, под которым и спрятал микропленку.\"},{\"id\":474,\"book\":\"ludovik\",\"lv\":3,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись к номеру на снимке и к тому, как напечатана фотография.\",\"Что бывает с номером и рулём, если фотографию напечатали наоборот?\"],\"short\":\"Видаль невиновен: снимок перевёрнут, настоящий номер машины 81 WA 08, а у Видаля 80 AW 18.\",\"answer\":\"На фотографии руль у машины справа, а номер — 80 AW 18. У машины г-на Видаля руль слева и такой же номер. Но фотограф второпях напечатал снимок перевёрнутым: на самом деле номер машины — 81 WA 08, а руль, как и у Видаля, слева. Значит, это не его машина, и г-н Видаль не виновен.\"},{\"id\":475,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к мусорным бакам в городке — они стоят не одинаково.\",\"Сравни бак Гастона с баками соседей: что в них лежит и когда их в последний раз опустошали?\"],\"short\":\"Гастон: его мусорный бак пуст, а у соседей полон — значит, он был в отъезде и только что вернулся.\",\"answer\":\"Заехав в городок, Людовик обратил внимание на мусорные баки — они были полны. Значит, мусорщики ещё не приезжали. И только мусорный бак Гастона был пуст. Следовательно, его освободили накануне утром, Гастона не было дома целый день, и он приехал только что.\"},{\"id\":476,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись, какие детали были у капюшона грабителя.\",\"Посчитай, у кого из троих глаза стоят так широко, как прорези в капюшоне.\"],\"short\":\"Третий на фотографии, с широко посаженными глазами: только его глаза совпадают с прорезями капюшона.\",\"answer\":\"Судя по отверстиям для глаз на капюшоне, единственный, кто мог его носить из троих, был человек с широко посаженными глазами с третьей фотографии.\"},{\"id\":477,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к тому, как каждый из троих говорит о статуэтке.\",\"Кто из троих назвал статуэтку китайской, хотя детектив этого не говорил?\"],\"short\":\"Жюль-«Клешня»: он назвал статуэтку китайской, хотя Людовик при нём говорил только о статуэтке.\",\"answer\":\"Взломщик — Жюль-«Клешня». Он выдал себя, говоря о китайской статуэтке, в то время как Людовик при нём говорил только о статуэтке.\"},{\"id\":478,\"book\":\"ludovik\",\"lv\":1,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к шлему мотоциклиста на руле у Джо.\",\"Что стало бы со шлемом, если бы Джо целый день не выходил под проливной дождь?\"],\"short\":\"Шлем на руле сухой: в проливной дождь он был бы полон воды, значит, Джо ездил на мотоцикле и лжёт.\",\"answer\":\"Джо говорит, что не выходил на улицу со вчерашнего дня. Но если бы это было так, то в проливной дождь шлем, висящий на руле, был бы полон воды. Но это не так. Значит, Джо солгал.\"},{\"id\":479,\"book\":\"ludovik\",\"lv\":3,\"pic\":true,\"ok\":3,\"hints\":[\"Посмотри, как стоит крюк прицепа на земле.\",\"Как повернулся бы крюк, если бы прицеп просто отцепился и упал сам?\"],\"short\":\"Пишу: крюк прицепа смотрит не в ту сторону — прицеп развернули до того, как его столкнули.\",\"answer\":\"Если бы всё было так, как говорит водитель, то крюк после падения прицепа должен был бы смотреть в обратную сторону. Прицеп был развёрнут перед тем, как его столкнули.\"},{\"id\":480,\"book\":\"ludovik\",\"lv\":3,\"pic\":true,\"ok\":0,\"hints\":[\"Вспомни, что делал прохожий, пока Людовик бегал в деревню за скорой.\",\"Сколько пуговиц было застёгнуто на пиджаке банкира до ухода Людовика и сколько — после его возвращения?\"],\"short\":\"Прохожий: пиджак банкира застегнули на вторую пуговицу, пока Людовик ходил за скорой, — значит, он рылся в вещах.\",\"answer\":\"Банкир вряд ли стал бы путешествовать без денег. Прохожий заявляет, что ничего не трогал. Однако Людовик обратил внимание на то, что перед тем, как он бросился в деревню, пиджак жертвы был застёгнут на одну пуговицу, а по возвращении пиджак уже был застёгнут на две пуговицы. Раненый находится без сознания, и только прохожий мог застегнуть вторую пуговицу. Зачем? Не потому ли, что он расстегнул пиджак для того, чтобы избавить банкира от его денег.\"},{\"id\":481,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Вспомни, что изменилось на ферме, пока Людовик ездил за подмогой.\",\"Что произойдёт с уровнем воды, если в бассейн опустить тяжёлый металл?\"],\"short\":\"В бассейне: уровень воды поднялся, пока Людовик ездил за комиссаром, — слитки утоплены в воде.\",\"answer\":\"Людовик обратил внимание, что уровень воды в бассейне заметно поднялся с того времени, когда он отправился за комиссаром. Следовательно, Дурубис спрятал похищенные слитки в бассейне.\"},{\"id\":482,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Сравни, как выглядел дом утром и как он нарисован на картине.\",\"Какие ставни нарисованы на картине художника — и какими они были утром?\"],\"short\":\"Художник: на его картине ставни открыты, а утром были закрыты — значит, в дом кто-то заходил, и он это скрывает.\",\"answer\":\"Во время первого визита детектива ставни на окнах дома были закрыты. Но, зайдя вечером к художнику, Людовик заметил на картине с изображением дома, что ставни на окнах нарисованы открытыми. Значит, в дом кто-то заходил, и художник не мог этого не заметить. Однако художник данный факт отрицает и, следовательно, он в сговоре с преступником.\"},{\"id\":483,\"book\":\"ludovik\",\"lv\":1,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к снегу перед домом.\",\"Что осталось бы на снегу, если бы Лерадин только что вышел из дома?\"],\"short\":\"Перед домом нетронутый снег: если бы Лерадин только что ушёл, остались бы его следы, а есть только следы Людовика.\",\"answer\":\"Перед домом Лерадина нетронутый снежный покров. Если бы Лерадин только что вышел, он оставил бы следы. А единственные следы — это следы Людовика. Значит, Лерадин всё ещё дома.\"},{\"id\":484,\"book\":\"ludovik\",\"lv\":3,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к зеркалу в магазине ювелира и к тому, что на нём написано.\",\"Смог бы человек спокойно прочесть длинный текст в зеркале, если бы ему приставили револьвер к затылку?\"],\"short\":\"Сторож не мог спокойно прочесть в зеркале длинный зеркальный текст, когда ствол револьвера у затылка — рассказ выдуман.\",\"answer\":\"Охранник, конечно, не мог прочесть в зеркале такой длинный текст, потому что видел его зеркально. Для этого ему потребовалось бы определённое время, а главное — спокойствие, которого не могло быть тогда, когда ствол револьвера приставлен тебе к затылку.\"},{\"id\":485,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись, что было у посетителей в руках в солнечный день.\",\"Зачем зонтик в ясную погоду, если им так удобно указывать на объекты?\"],\"short\":\"Зонт в солнечную погоду: им посетитель указывал на объекты базы — в наконечнике может прятаться микрокамера.\",\"answer\":\"У одного из посетителей есть зонтик, которым он постоянно указывает на различные объекты базы. Но зачем нужен зонтик при солнечной погоде? Значит, именно этот зонт Людовик и собирается осмотреть, чтобы убедиться, что его наконечник не скрывает микрокамеру.\"},{\"id\":486,\"book\":\"ludovik\",\"lv\":3,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к тому, как записаны даты на манускрипте.\",\"В каком порядке до нашей эры принято записывать годы — от большего к меньшему или наоборот?\"],\"short\":\"Подделка: даты «с 1317 по 1289 год до нашей эры» записаны не в том порядке — для до н.э. годы идут в обратную сторону.\",\"answer\":\"Гектор де ла Карублэ совершил большую ошибку, сфабриковав данный манускрипт. Даты до нашей эры должны записываться в обратном порядке, а не наоборот — «с 1317 по 1289 год до нашей эры».\"},{\"id\":487,\"book\":\"ludovik\",\"lv\":3,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись к гипсу Додо и к фотографии, которую показывает Дедье.\",\"Проверь, на какой стороне пиджака пуговица на фото и есть ли у велосипеда ночная фара.\"],\"short\":\"Дедье и Додо: Додо симулирует перелом, фото перевёрнуто, а у велосипеда Дедье нет ночной фары.\",\"answer\":\"Людовик арестовал Дедье «Акробата» и Додо «Каната».\\n\\nКогда он вошёл в кафе, то увидел, что у Додо теперь в гипсе правая рука, а не левая, как утром. Значит, это симуляция.\\n\\nНа фотографии, которую показывает Дедье, пуговица на пиджаке расположена на левой стороне, а не на правой, как должно быть. Значит, фотография перевёрнута и была сделана не в восемь часов, а в четыре. У Дедье было достаточно времени, чтобы вернуться в город и принять участие в краже.\\n\\nКроме того, у его велосипеда нет ночной фары, и на нём было невозможно ездить ночью по сельским дорогам.\\n\\nВсё это привело Людовика к выводу, что кражу совершили эти двое, которые утром специально остановились у его дома, чтобы отвести от себя подозрение.\"},{\"id\":488,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к велосипеду, который вернули на место.\",\"Кому пришлось бы поднять седло, и не забыл ли вор опустить его обратно?\"],\"short\":\"Фредо: он высокого роста, поэтому поднимал седло; вернув велосипед, забыл его опустить — это и выдало вора.\",\"answer\":\"Фредо допустил промашку, которая его выдала. Из-за своего большого роста он был вынужден поднять седло велосипеда, чтобы доехать на нём до усадьбы в двух километрах от городка… Но, возвращая велосипед на место, он забыл опустить седло, и эту его оплошность Людовик и заметил.\"},{\"id\":489,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к машине: что на ней есть, а чего нет?\",\"Что водитель может увидеть в зеркале салона, если позади него груз?\"],\"short\":\"Водитель: у машины нет боковых зеркал, а в салонном зеркале из-за груза ничего не видно — он лжёт.\",\"answer\":\"Людовик обратил внимание, что у автомобиля отсутствуют боковые зеркала. А в зеркале внутри салона водитель не мог ничего увидеть, так как сзади расположен груз. Следовательно, водитель автомобиля солгал.\"},{\"id\":490,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к камину в доме.\",\"Сколько золы должно быть в камине, который разожгли только что?\"],\"short\":\"Камин полон золы: огонь в нём горел несколько дней, значит, Артур здесь давно, а не приехал только что.\",\"answer\":\"Артур говорит, что только что приехал, успел только убраться и разжечь камин. Но если бы это было правдой, то в камине не было бы столько пепла. Это обстоятельство указывает на то, что огонь в камине горел уже несколько дней.\"},{\"id\":491,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Сравни фотографию дома с тем домом, где они оказались.\",\"Сверь, сколько окон видно на фотографии и сколько в комнате, где они стоят.\"],\"short\":\"На фото у дома два окна на фасаде, а в комнате, где они стоят, три окна — это другой дом.\",\"answer\":\"На фотографии Людовик заметил, что дом имеет на фасаде два окна, в то время как комната, в которой они находятся, имеет три. Поэтому Людовик понял, что Боно привёл его в другой дом — не тот, который был на фотографии. Боно очень не хочет, чтобы его обыскивали.\"},{\"id\":492,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Вспомни, в каком состоянии было ведро с водой, когда Людовик пришёл впервые.\",\"Что стало с ведром и его ручкой между первым и вторым визитом?\"],\"short\":\"Летриер поил коня: при повторном визите ведро опустело и ручка сместилась — конюх, ухаживающий за конём, это прикрыл.\",\"answer\":\"Когда Людовик приехал, ведро было полным, а ручка была с правой стороны. Когда он вернулся с конюхом, ведро оказалось пустым, а ручка была слева. Таким образом, господин Летриер дал коню выпить, а конюх, который ухаживает за конём, должен был заметить, что ведро пустое.\"},{\"id\":493,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к крыше машины, где видны следы выстрелов.\",\"Откуда могли лететь пули, оставившие две дыры в крыше?\"],\"short\":\"Две дыры в крыше машины могли появиться только от выстрелов изнутри: Ганс убил Глюка и выдумал нападение.\",\"answer\":\"Если бы нападавший стрелял в Ганса в упор, в крыше автомобиля не было бы двух пулевых отверстий — их можно было сделать только выстрелами, выпущенными из пистолета внутри машины. Таким образом, произошла драка между Глюком и Гансом, который, убив своего напарника, украл алмазы и выдумал нападение.\"},{\"id\":494,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Посмотри на фигуру и руки троих мужчин в костюмах Пьеро.\",\"Кто из троих худее остальных и носит кольцо на мизинце?\"],\"short\":\"Мужчина в бабочке со стаканом: он худее остальных и, как у вора-Пьеро, кольцо на мизинце.\",\"answer\":\"Это не тот, кто курит сигару, так как преступник был похудее. И только один из троих носит кольцо на мизинце, как и Пьеро, совершивший кражу. Вор — мужчина в бабочке со стаканом в руке.\"},{\"id\":495,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к ведру с краской на картинке.\",\"Сравни, сколько краски было в ведре утром и сколько осталось, когда вернулся Лагут.\"],\"short\":\"Лагут весь день провел в бистро за картами: уровень краски в ведре не изменился с утра, работы не было.\",\"answer\":\"По возвращению Лагута, Людовик сразу заметил, что уровень краски в ведре не изменился по сравнению с утром. Это позволило ему предположить, что тот провел все время в бистро, играя в карты.\"},{\"id\":497,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к тому, в чем был погибший, и к тому, что Элла рассказывает о его уходе.\",\"Можно ли выбежать на улицу в тапочках и без куртки, если Элла уверяет, что муж одевался перед уходом?\"],\"short\":\"Элла врет: муж был в тапочках и без верхней одежды, а она говорила, что он выбежал одетым. Значит, она замешана.\",\"answer\":\"На убитом нет верхней одежды, а на ноги надеты тапочки. Супруга четко сказала: «Одевшись, он выскочил на улицу». Элла врет, когда говорит, что, едва услышав звук открывающейся двери, закричала мужу: «Беги». Вряд ли бы в этом случае он снял куртку и переоделся в тапочки. А раз женщина лукавит в мелочах, наверняка она замешана и в самом преступлении.\"},{\"id\":498,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Обрати внимание на погоду в городе и на то, что рассказывает каждый подозреваемый о своем дне.\",\"Можно ли при минус пятнадцати лепить снеговика, как рассказал один из подозреваемых?\"],\"short\":\"Сергей со второго этажа: в мороз под минус пятнадцать он врал, что лепил снеговика, а в такой холод это невозможно.\",\"answer\":\"Анискин заподозрил в преступлении Сергея со второго этажа. На улице, как было сказано в самом начале рассказа, уже несколько дней стоит мороз. Если в снежки в такую погоду (хоть и с большой натяжкой) играть еще можно, то лепить снеговика — точно нет. Соврав в деталях, Сергей автоматически стал главным подозреваемым.\"},{\"id\":499,\"book\":\"aniskin\",\"lv\":3,\"pic\":false,\"ok\":2,\"hints\":[\"Перечитай письмо внимательно: в нем есть что-то лишнее, кроме смысла.\",\"Что получится, если сложить все опечатки из письма подряд? Вспомни, что Кропотов говорил об увлечениях Бухарова.\"],\"short\":\"Адрес «гагарина дом 7» сложен из намеренных ошибок в письме: Бухаров любит ребусы и головоломки, это и подсказало шифр.\",\"answer\":\"Александр Бухаров — филолог, бывший преподаватель университета. Так почему в его письме так много ошибок? Если поочередно складывать все «опечатки» из послания, получится: «гагарина дом 7». Именно по этому адресу Анискин отправил группу захвата, которая и освободила заложника. Кропотов не зря упомянул, что Александр увлекается ребусами и головоломками. Это хобби и спасло ему жизнь.\"},{\"id\":500,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к украшениям на фотографиях и к тому, что надето на людях в деревне.\",\"Что у одной из женщин на одежде совпадает с украшениями госпожи Гроссоу на её фотографиях?\"],\"short\":\"Супружескую пару из последнего дома: на женщине брошь и браслет госпожи Гроссоу, видные на фотографиях.\",\"answer\":\"Людовик подозревает в похищении мужа и жену, которые заявили, что они уже застрахованы. Он заметил, что женщина носит на своем платье брошь госпожи Гроссоу, которая видна на одной из ее фотографий, и браслет, запечатленный на двух других. Похитители совершили ошибку, забрав их у своей жертвы.\"},{\"id\":501,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Перечитай, что говорил каждый подозреваемый о гибели Лаврова и откуда им это известно.\",\"Кто назвал орудие убийства, хотя сыщики о нём не говорили?\"],\"short\":\"Прораба Стрючина: он сам назвал орудие убийства, арматуру, хотя полиция о способе убийства не говорила.\",\"answer\":\"Анискин заподозрил в убийстве прораба Стрючина. Сыщики не говорили о том, как именно погиб Лавров, но Стрючин в разговоре заявил: «Башку арматуриной проломить — нет, у меня рука не поднялась бы». Прораб оговорился, назвав не только способ убийства, но и орудие убийства, и тем самым выдал себя.\"},{\"id\":502,\"book\":\"aniskin\",\"lv\":3,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись к фотографиям в паспортах: что изображено за спиной у каждого?\",\"Почему у одного паспорт с фотографией не на белом фоне, и что видно на заднем плане?\"],\"short\":\"Антон Нагиев из Нальчика: на его паспортном фото вместо белого фона видна горная вершина, фото подменено беглецом.\",\"answer\":\"Анискин велел остаться Антону Нагиеву из Нальчика. Только в его паспорте — фотография, на заднем плане которой видна вершина горы. Украв в поезде паспорт у пассажира, беглый зэк вклеил в документ свою физиономию, поскольку был совершенно не похож на истинного владельца. Правда, у него не оказалось фотографии с белым фоном, как обязательно требуется для паспорта, и он заменил ее на единственную, которая казалась ему подходящей.\"},{\"id\":503,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к скорости, с которой ехала машина, и к тому, как близко был стрелок.\",\"Сколько мгновений машина на скорости 60 км/ч находилась бы рядом со стрелком?\"],\"short\":\"Трегубов врёт: на ходу машина проскочила бы стрелка, а тот не успел бы семь раз попасть в одно место.\",\"answer\":\"По словам депутата, он ехал на машине по шоссе, когда киллер выскочил прямо перед ним. При этом все семь пуль, судя по отверстиям в лобовом стекле, легли очень кучно. Даже при скорости 60 км/ч это невозможно: машина миновала бы киллера, «появившегося в упор», за несколько мгновений, и он не успел бы выстрелить семь раз фактически в одно и то же место лобового стекла.\"},{\"id\":504,\"book\":\"aniskin\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись к печной трубе дачи: снег на ней ведёт себя странно.\",\"Что означает проталина на колпачке трубы, если в доме давно никто не живёт?\"],\"short\":\"Проталина на колпачке печной трубы: в доме топят печь, а ключи были только у беглеца Душегубова.\",\"answer\":\"Все подходы к даче и сам дом засыпаны снегом. Однако на колпачке печной трубы образовалась небольшая проталина. Так бывает, когда в доме топят печь. А кто мог делать это в заброшенном доме, ключи от которого были только у Душегубова? Именно печная труба выдала местонахождение убийцы.\"},{\"id\":505,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к тому, что «ученый» рассказывает о математиках и премиях.\",\"Существует ли вообще Нобелевская премия по математике?\"],\"short\":\"Он назвал несуществующую «Нобелевскую премию по математике» и перепутал, от какой награды отказался Перельман.\",\"answer\":\"По мотивам личного характера Альфред Нобель на дух не переносил математиков. Поэтому согласно его завещанию Нобелевская премия не присуждается математикам за заслуги в этой науке. И тот же Григорий Перельман, вопреки распространенному мнению, отказался не от Нобелевской премии, а от Премии тысячелетия.\"},{\"id\":506,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Что эксперт сказал о ноже и что обычно остаётся на оружии после того, как им кого-то ранили?\",\"Остались ли на ноже отпечатки пальцев Василия, если он сам им себя ранил?\"],\"short\":\"Невеста: на ноже нет отпечатков Василия, значит, его протёрли, а сам он себя не ранил.\",\"answer\":\"Если бы Василий действительно нанёс себе удар ножом и отбросил его, на оружии обязательно остались бы его отпечатки пальцев. Но эксперт утверждает, что на ноже никаких «пальчиков» нет. Видимо, Юлия ударила Василия ножом, а затем убедила жениха не выдавать её и придумала версию с суицидом, которую он и повторил сыщику. Юлю подвело то, что после трагедии она протерла нож.\"},{\"id\":507,\"book\":\"aniskin\",\"lv\":3,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к фамилиям пострадавших и к тому, в каком порядке на них нападали.\",\"Выпиши первые буквы фамилий пострадавших по порядку нападений — что получится?\"],\"short\":\"Козлов, лишённый премии: мстил бухгалтерии и оставлял «автограф» — первые буквы фамилий жертв дают КОЗЛО.\",\"answer\":\"Анискин задержал мужчину по фамилии Козлов.\\n\\nВ воспаленном от алкоголизма мозгу работяги родился коварный план. Он не только мстил сотрудницам бухгалтерии, но и оставлял своеобразный «автограф»: если сложить в порядке очередности первые буквы фамилий пострадавших, получится КОЗЛО. Логично предположить, что последней жертвой должна была стать главбух Васильева, и тогда «автограф» читался бы как КОЗЛОВ.\"},{\"id\":508,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Вспомни, как учитель объяснял, по каким ориентирам шёл в пургу.\",\"Какая звезда видна только в Северном полушарии?\"],\"short\":\"Учитель географии: хвастаясь спасением в Антарктиде, он ориентировался по Полярной звезде, которой там не видно.\",\"answer\":\"Анискин заподозрил в кражах учителя географии.\\n\\n«Герой-полярник», рассказывая детям о своем «подвиге», очень серьезно прокололся, сообщив, что, будучи в Антарктиде и спасая товарища, он ориентировался по Полярной звезде. Полярная звезда в Южном полушарии не видна, ориентироваться по ней можно только в Северном. Уголовник специально устроился в элитную гимназию, чтобы воровать у детей деньги и вещи.\"},{\"id\":509,\"book\":\"ludovik\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к картинкам у ворот: что там лежит и где?\",\"Что случилось бы с яблоком у створки, если бы обе створки ворот открывали?\"],\"short\":\"Дюбуа: яблоко у створки ворот не сдвинулось, значит, он никуда не выезжал и кражу подстроил сам.\",\"answer\":\"Когда Людовик уходил из дома Дюбуа после первой встречи, он заметил, что одно из яблок лежит прямо у створки ворот. Невозможно открыть обе створки ворот, не сдвинув это яблоко. Однако яблоко лежит на своем прежнем месте. Следовательно, Дюбуа лжет, будто выезжал на машине: для этого надо было открыть обе створки ворот. Все содеянное является инсценировкой, чтобы получить страховку.\"},{\"id\":510,\"book\":\"aniskin\",\"lv\":3,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к подписи под рукописным письмом: кто и когда мог так назвать себя?\",\"Подумай, из каких слов могло получиться имя, которое стоит в подписи, и когда такие имена появились.\"],\"short\":\"Имя «Владилен» — сокращение от «Владимир Ильич Ленин»: в начале века такого имени ещё не было, письмо подделка\",\"answer\":\"Владилен — имя, которое встречалось в СССР в послевоенные годы, означающее сокращение от «Владимир Ильич Ленин». В начале века такого имени не было.\"},{\"id\":511,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Обрати внимание на то, как парень вёл себя перед быком, а не на то, что было на нём надето.\",\"Бык не различает красного цвета: подумай, что именно раздражало Федора перед нападением.\"],\"short\":\"Бык не различает красного: парень сам дразнил его тряпкой, и тот ответил на движения, а не на цвет футболки\",\"answer\":\"Быки совершенно не различают красного цвета, а раздражают быка на арене не красные цвета платья матадора и мулеты, а угрожающие движения как ткани, так и самого матадора.\"},{\"id\":512,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Посмотри внимательно, что изображено на одной из фотографий, и сравни это с датой смерти мастера.\",\"Сравни 1870 год с годом постройки башни, которую, по программке, снял мэтр.\"],\"short\":\"На одном из «снимков» Эйфелева башня — её построили почти через 20 лет после смерти мастера в 1870 году\",\"answer\":\"Согласно программке, месье Рошель скончался в 1870 году. Однако на одном из его фотоснимков запечатлена Эйфелева башня, которая была построена лишь почти через 20 лет после его смерти. Поэтому выдуманный мошенниками мэтр и не фотографировал людей — жулики опасались, что кто-то может заметить их современную одежду. Аферистов подвело незнание истории.\"},{\"id\":513,\"book\":\"ludovik\",\"lv\":3,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись к напитку, который пили игроки, и подумай, что с ним происходит, когда в него добавляют воду.\",\"Пастис мутнеет от воды: спроси себя, чей рассказ о напитке не сходится с этим и кто знает аперитив лучше всех.\"],\"short\":\"Лжёт тот, чей рассказ о пастисе не сходится с тем, что он мутнеет от воды: горничная такой аперитив знает\",\"answer\":\"Особенностью пастиса является то, что достаточно лишь немного добавить в него воды и напиток сразу мутнеет. Горничная, которая постоянно подаёт своему мужу точно такой же аперитив, сразу бы обратила на это внимание.\"},{\"id\":514,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Обрати внимание на надпись на Мавзолее и подумай, менялась ли она за годы.\",\"В 1953–1961 годах на Мавзолее была не одна фамилия: какая надпись должна была стоять на нём в 1958 году?\"],\"short\":\"Марка 1958 года с надписью «Ленин» на Мавзолее: тогда там значилось «Ленин. Сталин», значит, марка подделка\",\"answer\":\"В 1953 году, после смерти Иосифа Виссарионовича, его тело поместили в Мавзолей. И целых 8 лет его украшала надпись: «Ленин. Сталин». Лишь в 1961 году Сталина перезахоронили, а Мавзолею вернули первозданный вид. Поэтому на марке, выпущенной в 1958 году, на Мавзолее должны быть написаны две фамилии. А раз виднеется лишь «Ленин», значит, она фальшивая. Мошенники от филателии не всегда знают историю так же хорошо, как Анискин.\"},{\"id\":515,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к документам покойного: что там было помимо паспорта?\",\"Подумай, зачем человеку, решившему умереть здесь, покупать билет обратно в Лондон.\"],\"short\":\"Скряга не стал бы покупать обратный билет в Лондон, если бы задумал самоубийство в России\",\"answer\":\"Валентин сказал, что его дядя считал каждую копейку и был жутким скрягой. Но такой человек, спланировав самоубийство в России, не стал бы покупать обратный билет в Лондон.\"},{\"id\":516,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к телескопу астронома: на что он настроен и что может показать?\",\"Телескоп настроен на далёкие звёзды: может ли он показать то, что происходит на земле в двух шагах?\"],\"short\":\"Телескоп для звёзд не показывает двор, а перенастроить его за секунды нельзя: астроном лжёт, чтобы насолить соседу\",\"answer\":\"Астроном говорит: «Я направил телескоп туда и увидел…». Однако телескоп, настроенный для наблюдения за небом, даёт слишком большое увеличение, и он просто не смог бы рассмотреть в нём то, что происходит во дворе. А времени перенастроить телескоп у астронома не было — он сам говорит, что всё произошло в считанные секунды. Лжесвидетельствуя, астроном просто хотел насолить беспокойному соседу.\"},{\"id\":517,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к тому, откуда у Рукосуйко взялись две настоящие купюры и что выдал банкомат.\",\"Бывают ли в обороте 500-долларовые купюры и мог ли банкомат их выдавать?\"],\"short\":\"Банкомат не мог выдать 500-долларовые купюры: их давно изъяли из оборота, так что история Рукосуйко выдумана.\",\"answer\":\"500-долларовые купюры действительно существуют. Однако в последние годы их активно изымают из оборота. По сути, сейчас крупная купюра, которая имеет массовое хождение в США - стодолларовая. Банкнотой в 500 долларов можно без проблем расплачиваться, но получить ее где-либо проблематично. Поэтому банкомат отеля, который мог выдать такие купюры, это нонсенс!\"},{\"id\":518,\"book\":\"aniskin\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к тому, что Хитрецов рассказал о ранах и откуда он мог это знать.\",\"Что стоит у Хитрецова под раковиной на кухне, если он говорит, что опорожнил ведро?\"],\"short\":\"Сам Хитрецов убил Бородкина: он знал про два ножевых удара, а ведро с бутылками стоит у него под раковиной.\",\"answer\":\"Во-первых, Хитрецов сказал про то, что «узнал Кольку». В то же время участковому пришлось подсвечивать сыщикам карманным фонариком. Кроме того, откуда мог знать «случайно нашедший труп» гражданин про именно два ножевых удара? И в-третьих, он говорит, что пошел выносить мусор и «опорожнил ведро», но полное ведро, из которого торчат те самые две водочные бутылки, стоит у него под раковиной.\"},{\"id\":519,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к тому, как Гаврила одет и что он делает, когда его переспрашивают.\",\"Может ли человек, у которого ухо шапки задрано, услышать треск сучка за спиной?\"],\"short\":\"Гаврила сам застрелил Ваську: он плохо слышит, поэтому не мог услышать треск сучка за спиной, о котором рассказывает.\",\"answer\":\"Гаврила одет в огромную меховую шапку-ушанку и плохо слышит даже сидящего рядом Анискина. Охотник вынужден задрать ухо у шапки, чтобы понять, что говорит ему собеседник. Как же он в таком случае мог услышать звук «тихонечко треснувшего сучка за спиной»? Именно поэтому Анискин и заподозрил Гаврилу.\"},{\"id\":520,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к огороду и к тому, что там делал Сидоров.\",\"Что бывает с огурцами в жару, если их долго не поливать?\"],\"short\":\"Огурцы в парнике вкусные, значит, их поливали: на даче кто-то есть, и дед жив, просто обиделся на внука.\",\"answer\":\"В жару если огурцы вовремя не поливать они становятся горькими и невкусными. Так что если они вкусные, то их поливают и с хозяином дачи всё в порядке.\"},{\"id\":521,\"book\":\"aniskin\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к тому, что висит на стене у Булкина.\",\"Чем рога лося отличаются от оленьих и какие рога висят у Булкина?\"],\"short\":\"Булкин врёт про оленя: на стене висят рога лося, а перепутать их может только тот, кто в охоте ничего не понимает.\",\"answer\":\"Булкин понимает в охоте еще меньше Анискина. Младший лейтенант в красках рассказывает майору про то, как охотился на оленя, в то время как на стене висят… рога лося. Как бы далек от охоты ни был Анискин, он не мог обойти вниманием этот факт. Перепутать рога лося и оленя может только полный дилетант, коим и является Булкин.\"},{\"id\":522,\"book\":\"aniskin\",\"lv\":3,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к тому, что царь перечисляет, жалуясь на пустые столы опричнины.\",\"Вспомни, когда на Руси впервые появился картофель.\"],\"short\":\"В письме Ивана Грозного упомянут картофель, а на Руси его не знали до Петра I: письмо подделано.\",\"answer\":\"Во времена Ивана Грозного на столах опричников никак не мог быть картофель. Впервые картофель появился на Руси только во времена Петра I. Находясь в Нидерландах в конце 17 века, Петр заинтересовался картофелем и \\\"для расплода\\\" прислал мешок клубней графу Шереметьеву. Знание этих обстоятельств и позволили Анискину разоблачить подделку.\"},{\"id\":523,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к дате, которую Анискин увидел на календаре в самом начале.\",\"Какие ночи бывают в Петербурге в конце июня?\"],\"short\":\"20 июня в Петербурге белые ночи, так что «темнота, хоть глаз выколи» — выдумка Вознесенского.\",\"answer\":\"На календаре указана дата — 20 июня. В это время в Санкт-Петербурге наблюдаются белые ночи, во время которых вся ночь состоит лишь из сумерек. Это противоречит показаниям «потерпевшего» о том, что темнота была такой — «хоть глаз выколи».\"},{\"id\":524,\"book\":\"aniskin\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись к бейджикам на груди у докторов возле кофейного автомата.\",\"Что нужно окулисту, а что — невропатологу?\"],\"short\":\"Окулист Корконосов: стетоскоп и молоточек невропатолога ему ни к чему — он переодетый грабитель.\",\"answer\":\"Переодетым преступником является окулист Корконосов. Окулист — это специалист по глазам, и стетоскоп, который висит у него на шее, данному типу врачей не нужен в принципе. Как и торчащий у него из кармана молоточек — им пользуются невропатологи. Преступник, схватив халат, пробежал через сестринскую, где для большего правдоподобия схватил первые попавшиеся инструменты. Это и выдало его.\"},{\"id\":525,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, что Петя мог и чего не мог видеть, когда ему надели мешок на голову.\",\"Мог ли человек с мешком на голове разглядеть бородатых горцев в машине?\"],\"short\":\"Петя не мог разглядеть троих горцев в машине: ему весь путь держали мешок на голове.\",\"answer\":\"Если бы, как рассказывал подросток, ему при похищении одели на голову мешок, то как он мог определить, что в автомобиле находились трое бородатых горцев?\"},{\"id\":526,\"book\":\"aniskin\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись к фотографиям на стене в кабинете Артфула.\",\"Сравни рост Артфула на снимках с Бараком Обамой и с Владимиром Владимировичем.\"],\"short\":\"Фото с президентами — монтаж: Джон стоит с ними вровень, хотя у лидеров разница в росте 30 см.\",\"answer\":\"На обоих фотографиях главный герой стоит вровень и с Бараком Обамой, и с Владимиром Владимировичем. Однако у лидеров США и России разница в росте порядка 30 сантиметров. Учитывая одинаковую одежду на обоих фотографиях, логично предположить, что это монтаж.\"},{\"id\":527,\"book\":\"aniskin\",\"lv\":3,\"pic\":true,\"ok\":0,\"hints\":[\"Внимательно рассмотри обе фотографии, которые принёс хранитель музея.\",\"Сравни фигуру девушки в красном на двух снимках.\"],\"short\":\"Девушка в красном платье: на снимке после экскурсии у неё заметно округлился животик — подушечка под платьем.\",\"answer\":\"Подушечку украла девушка в красном платье. Если сравнить обе фотографии, то видно, что на фото, сделанном после посещения музея, у неё заметно «округлился» животик.\"},{\"id\":528,\"book\":\"aniskin\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к картине, которую так хвалил Иваньков.\",\"Что изображено на картине: цветы и яблоки на столе или вид за окном?\"],\"short\":\"Картина в кабинете — натюрморт (цветы и яблоки), а не пейзаж, как уверял «знаток».\",\"answer\":\"Даже дети, наверное, знают, что картина в кабинете относится к жанру натюрморта, а не пейзажа. А уж «профессионал» это знать обязан.\"},{\"id\":529,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к тому, какие деньги и монеты просил у майора валютчик и какие из них вообще бывают.\",\"Есть ли в долларовой системе купюра номиналом 25 долларов?\"],\"short\":\"Валютчик просил 25-долларовые купюры, которых не бывает: значит, он сам их подделал, а шутка вышла в попытке подкупа.\",\"answer\":\"По аналогии с 25-центовыми монетами новоиспеченный кооператор, никогда не бывавший за границей, требует у валютчика и 25-долларовые банкноты. Таковых, в отличие от 25-центовой монеты, не существует (есть 20 и 50 долларов). Шутки ради валютчик все же изготовил заказанные купюры, пусть и фальшивые: мол, желание клиента — закон. Ну а потом спекулянт не смог отказать себе в удовольствии и попытался подкупить Анискина всеми теми же фальшивыми купюрами. На чем и попался.\"},{\"id\":530,\"book\":\"aniskin\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Обрати внимание на головки инструмента мастера и на то, какие болты он ввинчивал.\",\"Может ли крестовая отвертка войти в простой поперечный шлиц болта?\"],\"short\":\"Шуруповерт с крестовой головкой не подходит к болтам с простым шлицем: он не работал, а поломка — выдумка мошенника.\",\"answer\":\"Когда мерзавец показывал Анискину «сломанный» шуруповерт, майор обратил внимание на крестовую головку инструмента. А потом заметил, что болты, которые ввинчены в стены, обладают простым поперечным разрезом. Крестовая отвертка или насадка к таким болтам просто не подходит, значит, шуруповерт не использовался в работе, а был использован просто для имитации поломки.\"},{\"id\":531,\"book\":\"aniskin\",\"lv\":3,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к тому, чем занят каждый из подозреваемых и что у него с собой.\",\"Что нужно художнику, чтобы рисовать акварелью, и не замерзнет ли вода на таком морозе?\"],\"short\":\"Художник у собора: акварелью на морозе не рисуют, зато в тубусе легко спрятать снайперскую винтовку.\",\"answer\":\"Анискин понял, что киллер избрал для себя маску художника. На столике у него лежат акварельные краски и стоит банка с водой, которой необходимо разводить акварель. Но на морозе рисовать акварелью невозможно — вода мгновенно замерзнет! А в тубусе легко спрятать снайперскую винтовку. Именно поэтому Анискин принял решение задержать живописца — и попал в точку.\"},{\"id\":532,\"book\":\"aniskin\",\"lv\":3,\"pic\":true,\"ok\":1,\"hints\":[\"Посмотри, какие коньки были в пакетике Бармалеева, и подумай, для какого спорта они нужны.\",\"Есть ли у коньков зубцы на передней части лезвия, и бывают ли такие у хоккейных?\"],\"short\":\"Коньки для фигурного катания: у них зубцы на лезвии, которых нет у хоккейных, а вратарь сборной играл только в хоккейных.\",\"answer\":\"В руках у Бармалеева — коньки для фигурного катания. В отличие от хоккейных, они снабжены зубчиками на передней части лезвия — это необходимо фигуристам для исполнения прыжков и других элементов. Хоккейные коньки зубчиков на лезвии не имеют. Маловероятно, чтобы Вячеслав Третьяк играл за сборную СССР в коньках, предназначенных для фигурного катания.\"},{\"id\":533,\"book\":\"aniskin\",\"lv\":3,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись к кабинету кадровика и подумай, что еще в этом деле могло перелететь через высокий забор.\",\"Чем обычно надувают шарики, чтобы они взлетали вверх?\"],\"short\":\"Кадровик: гелиевые шары с микросхемами перелетали через забор по ветру, а сообщник сбивал их пневматической винтовкой.\",\"answer\":\"Анискин заподозрил кадровика, увидев у него в кабинете баллон с гелием (летучим газом) и несколько спущенных воздушных шаров. Кадровик надувал шар газом, привязывал к нему микросхему и отпускал его по ветру так, чтобы он перелетал забор. А на той стороне забора его сообщник сбивал шар выстрелом из пневматической винтовки и подбирал груз.\"},{\"id\":534,\"book\":\"aniskin\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к букетам поклонниц, которые тянутся к сцене.\",\"Какое число цветов не дарят живым, а несут на траурные мероприятия?\"],\"short\":\"Женщина с четырьмя розами: четное число цветов несут на похороны, а в письме как раз обещали, что Гикоров уже труп.\",\"answer\":\"Анискин запомнил фразу из письма сумасшедшей поклонницы: «А ты уже труп». Все зрительницы, которые толкаются у сцены, несут букеты, и лишь одна держит в руках четыре розы. Четное число цветов, как известно, носят не в подарок, а на траурные мероприятия, в том числе на похороны. Именно этим сумасшедшая поклонница выдала себя.\"},{\"id\":535,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к тому, как игроки стоят в стенке при штрафном и что прикрывают руками.\",\"В стенке при штрафном женщины прикрывают грудь и живот. А что прикрывают мужчины?\"],\"short\":\"«Акулы» — переодетые мужчины: в стенке при штрафном закрыли пах, как принято у мужчин, а не грудь, как у женщин.\",\"answer\":\"Ларчик открывается просто: только в мужском футболе игроки, стоя в стенке при штрафном ударе соперника, закрывают пах. Женщины, напротив, прикрывают грудь и живот, иногда лицо. «Акулы» прекрасно загримировались, но чисто автоматически выдали себя типично «мужским» жестом.\"},{\"id\":536,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, мог ли рассказчик точно назвать марки машин, которые останавливались у дороги.\",\"Есть ли у рассказчика зрение? Он ведь описал барсетку так, будто видел её.\"],\"short\":\"Слепого: он не мог точно назвать марки машин, которые останавливались, но описал барсетку так, будто видел её.\",\"answer\":\"Слепого. Во-первых, слепой вряд ли мог точно определить марки автомобилей, которые останавливались. Во-вторых, он сказал, что барсетка была точно такой, как у него. Следовательно, он её видел.\"},{\"id\":537,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к инвентарю: что в руках у людей, которые пришли на соревнования?\",\"Какая клюшка нужна для хоккея с шайбой на льду, а какая — для хоккея с мячом на траве?\"],\"short\":\"Мужчину с сумкой из группы хоккеистов: в руках у него клюшка для хоккея с шайбой, а турнир шёл с мячом на траве.\",\"answer\":\"Сидоров обратил внимание на группу хоккеистов. Среди них был мужчина с сумкой на правом плече, в руках у него была клюшка для игры в хоккей с шайбой на льду. А ведь соревнования проходили по хоккею с мячом на траве. Мужчина, видимо, не знал, что в этом виде спорта у игроков совсем другие клюшки. Это и позволило Сидорову обнаружить подозреваемого.\"},{\"id\":538,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к датам: когда жили авторы картин и когда были созданы изображённые на них сюжеты.\",\"Когда умер Айвазовский и когда был спущен на воду броненосец «Слава»?\"],\"short\":\"Три картины — подделки: Айвазовский умер в 1900-м, «Слава» спущена в 1902-м, Ван Эйк умер до табака в Европе.\",\"answer\":\"Единственная картина, которая ещё могла быть подлинной, — «Пейзаж с ветряными мельницами» Айвазовского. Картину «Торжественный спуск на воду броненосца „Слава“» Айвазовский написать не мог: он умер в 1900 году, а броненосец «Слава» был спущен на воду в 1902 году и был пароходом, а не парусником. Ну и уж тем более Врубель не мог написать портрет красноармейца. Так же как и Ван Эйк не мог написать портрет курильщика: он умер задолго до того, как Колумб привёз табак в Европу из своих плаваний в Америку.\"},{\"id\":539,\"book\":\"aniskin\",\"lv\":3,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к бутылке с водой, которую Анискин взял в салоне машины.\",\"Что случилось бы с водой в бутылке, если бы машина простояла всю ночь на тридцатиградусном морозе?\"],\"short\":\"Загорулько: вода в бутылке из салона не замёрзла, значит, машина не стояла всю ночь на морозе — он вернулся утром с дачи.\",\"answer\":\"Если бы машина всю ночь простояла на тридцатиградусном морозе, вода в бутылке, которая находилась в салоне, замёрзла бы.\"},{\"id\":540,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись, как меняется высота машины в зависимости от того, гружёная она или порожняя.\",\"Что станет с высотой грузовика, если спустить часть воздуха из колёс?\"],\"short\":\"Спустить часть воздуха из колёс фуры: машина опустилась, как под грузом утром, и прошла под мостом.\",\"answer\":\"Анискин понял, что утром, под тяжестью груза, автомобиль был «ниже ростом», поэтому и прошёл под мостом. Он предложил водителю спустить часть воздуха из колёс, и на приспущенных колёсах фура смогла проехать мост.\"},{\"id\":541,\"book\":\"aniskin\",\"lv\":3,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись, где стоит руль в машине, которую продают, и какой руль ставят в японские машины для своих дорог.\",\"Японцы ездят по левой стороне. Как ставят руль в машину, рассчитанную на их дороги, и где он стоит в этой?\"],\"short\":\"Руль слева, а японцы для своего рынка делают праворульные машины: это подделка, и продавец работает в группе.\",\"answer\":\"В Японии левостороннее движение, а потому продукция их автопрома, рассчитанная на внутренний рынок, — с правым рулём. Машина же, на которой якобы катался по местным дорогам старичок-японец, леворульная, как российские машины. А если документы на явно поддельную машину выглядят подлинными, то, скорее всего, действует группа, в составе которой есть и специалист по их подделке.\"},{\"id\":542,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к тому, что старик рассказывает о горючем и о том, как банка с ним загорелась.\",\"Какое топливо заливают в трактор и загорится ли оно от зажигалки на морозе в открытой банке?\"],\"short\":\"Калинин врёт: солярку на морозе зажигалкой из открытой банки не поджечь, значит, история про Прокудина выдумана.\",\"answer\":\"Трактор работает на дизельном топливе (солярке), а в зимних условиях поджечь его зажигалкой в открытой ёмкости невозможно.\"},{\"id\":543,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Посмотри, что Анискин видит на столе, когда Валуев велит выложить содержимое карманов подозреваемого.\",\"Для чего, кроме проверки золота, применяют йод, магнит и уксус вместе с ляписом?\"],\"short\":\"Копытько — скупщик-новичок: в карманах йод, магнит, уксус и ляпис, то есть набор для проверки золота.\",\"answer\":\"Йод, магнит, уксус, ляписный карандаш — все это используется для проверки подлинности золота. В принципе, достаточно любого из этих средств, но начинающий скупщик решил подстраховаться.\"},{\"id\":544,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к маске, которую нашла Арсения, и к тому, что она рассказывает о слюне маньяка.\",\"Какую маску описывает Арсения и есть ли в ней отверстие для рта?\"],\"short\":\"Арсения врёт: маска закрывала лицо с прорезями только для глаз, и слюна «в лицо» через ткань не долетела бы.\",\"answer\":\"Арсения рассказывает: «Его глаза горели, как угли, он шипел от ярости, а изо рта мне в лицо летели брызги слюны». Однако на фотографии светская львица демонстрирует маску-шапку с прорезями для глаз — отверстия для рта у нее нет. Мог ли насильник брызгать слюной сквозь ткань? Анискин предположил, что нет, а потому, вероятно, и весь остальной рассказ — ложь.\"},{\"id\":545,\"book\":\"aniskin\",\"lv\":3,\"pic\":false,\"ok\":3,\"hints\":[\"Подумай, что любой врач, даже не травматолог, должен знать о первой помощи пострадавшему в ДТП.\",\"Что медик велел сделать с пострадавшим после того, как проверил пульс, и почему это опасно без сознания?\"],\"short\":\"Ложный врач велел уложить пострадавшего на спину, хотя без сознания его кладут на бок, чтобы язык не перекрыл дыхание.\",\"answer\":\"Любой врач, независимо от своей специализации, знает правила оказания первой помощи пострадавшим в ДТП. Если пострадавший находится в бессознательном состоянии, его следует перевернуть на бок, чтобы освободить дыхательные пути, и ни в коем случае не оставлять лежать на спине, т.к. язык может полностью перекрыть глотку.\"},{\"id\":546,\"book\":\"aniskin\",\"lv\":3,\"pic\":false,\"ok\":1,\"hints\":[\"Посмотри, какой улов у Бабаева и какими снастями он ловил, в сравнении с тем, что было у других.\",\"Какая из рыб в его улове не хищная и не может клюнуть на блесну или воблер?\"],\"short\":\"Бабаев купил рыбу на рынке: подлещика на блесну и воблер не поймать, а на его спиннинге такой улов невозможен.\",\"answer\":\"Бабаев, как и остальные рыболовы, вооружен исключительно спиннингом, а из насадок у него — блесны и воблеры. Щуку, судака и окуней он действительно вполне мог выловить. Но подполковник просто не знал, что подлещик — не хищник и не ловится на приманку, имитирующую рыбку. Будь у него с собой еще и обычная поплавковая удочка или донка, Анискин не смог бы уличить его в обмане.\"},{\"id\":547,\"book\":\"aniskin\",\"lv\":3,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к тому, что лежит на земле у колёс машины доставщика.\",\"Что бывает с водой, если на садовом шланге стоит тяжёлая машина, и пошёл бы поливальщик проверять, почему её нет?\"],\"short\":\"Шланг придавлен колесами машины: Сергей и Марина не поливали цветы, иначе сразу пошли бы проверить, почему нет воды.\",\"answer\":\"Доставщик пиццы сказал, что наехал колесами автомобиля (и какое-то время стоял в таком положении) на садовый шланг, который, как хорошо видно на рисунке, лежит на твердой поверхности. Сергей и Марина, если бы они действительно, как уверяют, поливали цветы, сразу пошли бы проверять, почему вода перестала поступать. Они этого не сделали, а значит, никакого полива не осуществляли.\"},{\"id\":548,\"book\":\"aniskin\",\"lv\":3,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к справке в руках Анискина и сравни её с остальными бумагами на столе.\",\"Посмотри, есть ли на справке дырки для скоросшивателя, как на остальных листах.\"],\"short\":\"Справка подделана: на ней нет дырок для скоросшивателя, как на всех остальных бумагах, — бухгалтер её перепечатала.\",\"answer\":\"На справке, которую держит в руках Анискин отсутствуют пробоины для скоросшивателя, которые имеются на всех остальных бумагах. Это указывает на то, что она поддельная. Бухгалтер успела перепечатать справку, но не догадалась (или не успела) пробить дырки на ней под скоросшиватель.\"},{\"id\":549,\"book\":\"aniskin\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись к кубкам в шкафу: что на них изображено и откуда они могли взяться?\",\"Что изображено на кубках в шкафу — видны ли там боксёрские атрибуты?\"],\"short\":\"Манаенков — мошенник: купленные в спортмагазине кубки в основном футбольные и хоккейные, а не боксёрские.\",\"answer\":\"Манаенков не слишком задумывался об антураже. Прибыв в новый город, он просто скупал в спортивном магазине различные кубки и медали, которыми украшал свой кабинет. Анискин обратил внимание, что «кубки, завоеванные воспитанниками», почему-то в большинстве своем содержат футбольные и хоккейные атрибуты, а отнюдь не боксерские.\"},{\"id\":550,\"book\":\"aniskin\",\"lv\":3,\"pic\":true,\"ok\":1,\"hints\":[\"Посмотри, где в этом районе могли оказаться вещи, которые не нашли при обыске, и что стоит на балконах.\",\"Что торчит на балконе второго этажа и какую снасть подельник не успел убрать?\"],\"short\":\"Подельник — в квартире на втором этаже, где на балконе вялится рыба: он поднял пакет с добычей удочкой.\",\"answer\":\"Подельник Явушкина прятался в квартире на втором этаже – той, где на балконе вялится рыба и стоит удочка. Выбежав из помещения банка и уверенный, что его не преследуют, рецидивист положил маску и пистолет в пакет с деньгами, а его подельник при помощи удочки поднял все наверх и унес в квартиру. Он не успел сложить удочку и просто оставил ее на балконе, не ожидая, что именно эта снасть подскажет Анискину способ и место сокрытия добычи.\"},{\"id\":551,\"book\":\"aniskin\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к двери в прихожей: что на ней установлено и что оно делает?\",\"Посмотри на дверь: есть ли на ней устройство, которое не даёт ей оставаться открытой?\"],\"short\":\"Никонов — убийца: он уверяет, что увидел распахнутую дверь, но на ней доводчик, который не даёт двери оставаться открытой.\",\"answer\":\"Никонов сказал, что решился зайти к соседу, когда увидел, что в дом Антона распахнута дверь. Но он и Анискин разговаривают в прихожей, и на пресловутой двери, которая «подсказала» Никонову, что дело нечисто, укреплена пружина-доводчик, которая не позволяет двери оставаться открытой. Именно эта деталь позволила Анискину вывести истинного убийцу на чистую воду.\"},{\"id\":552,\"book\":\"aniskin\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к табличке на стене за спиной секретарши: что написано рядом с номерами?\",\"Сколько цифр в каждом внутреннем номере на табличке и сколько раз нажала Тонечка?\"],\"short\":\"Тонечка набирала внутренний номер тремя нажатиями, а на всех телефонах номера из четырёх цифр — она врала, что директора нет.\",\"answer\":\"Рядом с Тонечкой висит список внутренних телефонов — Виктора Анатольевича, главбуха, охраны. На всех них — четыре цифры. Между тем, как следует из текста Тонечка все время нажимала кнопки лишь три раза. То есть явно тыкала их наугад и делала вид, что у директора никто не берет трубку.\"},{\"id\":553,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к щенкам на фотографии в объявлении: в каком они виде?\",\"Далматинцы рождаются без пятен. Через сколько времени они появляются?\"],\"short\":\"Далматинцы рождаются белыми, а слепых щенков никто не отдаёт: мошенник «попятнал» дворнягу и её детей.\",\"answer\":\"Далматинцы рождаются абсолютно белыми. А пятна у них появляются в течение следующих пары недель. К тому же какой собаковод будет отдавать новорожденных, еще слепых щенков-сосунков? Мошенник просто «попятнал» дворняжку и ее детишек и пытался избавиться от них как можно быстрее, исчезнув с деньгами.\"},{\"id\":554,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Обрати внимание, что именно сказал каждый из родственников, услышав новость о смерти.\",\"Откуда Валерий знает имя погибшего, если Анискин его ещё не называл?\"],\"short\":\"Валерий: он назвал погибшего «Мишей», хотя Анискин имени не называл, — значит, знал о случившемся, потому что сам был причастен.\",\"answer\":\"Услышав про смерть шурина, Валерий воскликнул: «Бедный Миша!» При этом Анискин не называл имени убитого. А ведь у Елены есть еще один брат, поэтому Валерий мог понять, что речь идет именно о Михаиле, только в том случае, если непосредственно был причастен к его гибели. Так что именно он — убийца, хотя Анискин понял это не сразу.\"},{\"id\":555,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Подумай, что могло исчезнуть из закрытого чемодана без единого следа, даже если пломбы остались целыми.\",\"Что происходит с сухим льдом, если оставить его в чемодане на долгий перелёт?\"],\"short\":\"Пассажир сам опустошил чемодан: положил сухой лёд, который за долгий перелёт испарился, а молнию оставил приоткрытой.\",\"answer\":\"У скандального пассажира, разумеется, не было никаких ценностей. Он положил в чемодан несколько брикетов сухого льда и специально оставил слегка прикрытой молнию. За время долгого перелета из Владивостока содержимое просто испарилось, не оставив никаких следов. Жулику оставалось только изобразить возмущение, устроить скандал и потребовать компенсации с компании «Эх, прокачу!».\"},{\"id\":556,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к рассказу каждого продавца о том, как к нему попала медаль.\",\"Что советские спортсмены делали на Олимпиаде 1984 года в Лос-Анджелесе?\"],\"short\":\"«Крыса»: он говорил, что медаль отца с Олимпиады 1984 года в Лос-Анджелесе, а СССР тогда бойкотировал эти игры.\",\"answer\":\"Кражу совершил мужчина, «похожий на крысу». Дело в том, что Советский Союз бойкотировал Олимпийские игры 1984 года в Лос-Анджелесе. Поэтому отец продавца никак не мог завоевать медаль на этих состязаниях. У всех остальных подозреваемых — истории, которые имеют право на существование.\"},{\"id\":557,\"book\":\"aniskin\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись, во что одет мужчина у дверей банка и как выглядит его куртка.\",\"Какого рисунка подкладка у распахнутой куртки мужчины у дверей и совпадает ли она с курткой налётчика?\"],\"short\":\"Мужчина у дверей банка: подкладка его распахнутой куртки той же расцветки, что у куртки налётчика, — он успел вывернуть её наизнанку.\",\"answer\":\"Преступника выдала распахнутая куртка. Анискин обратил внимание на то, что у нее подкладка такой же расцветки, как и у куртки грабителя, и понял, что грабитель во время налета просто вывернул куртку наизнанку, а после ограбления проделал все наоборот.\"},{\"id\":558,\"book\":\"aniskin\",\"lv\":3,\"pic\":false,\"ok\":3,\"hints\":[\"Обрати внимание, где в момент падения находилась Екатерина и что она могла слышать.\",\"Могла ли Екатерина услышать глухой удар о газон, если лежала в комнате с закрытой балконной дверью?\"],\"short\":\"Гусева врёт: из комнаты при закрытой балконной двери удар тела о газон не слышен, значит, она была на балконе.\",\"answer\":\"Женщина не могла слышать звука от удара тела об землю, так как дверь на балкон была закрыта, а тело упало с шестого этажа на траву.\"},{\"id\":559,\"book\":\"aniskin\",\"lv\":3,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к тому, как вскрыты витрины с золотом и с серебром — и кто из сотрудников был рядом с ними ночью.\",\"Почему у сторожа перевязана рука, а стекло в «серебряной» витрине разбито, а не вырезано?\"],\"short\":\"Сторож Игнатьев: разбил витрину с серебром рукой, а не стеклорезом, и свалил кражу на тех, кто унес золото.\",\"answer\":\"Серебро похитил охранник. Обнаружив, что преступники похитили золото, он решил, что можно воспользоваться данной ситуацией, свалив на них и похищение серебра. Он разбил витрину рукой, повредив ее при этом. Если бы кражу совершили преступники, то они воспользовались бы тем же самым способом — разрезали бы стекло стеклорезом, чтобы не привлечь к себе внимание звуком разбиваемого стекла. Никто другой из сотрудников музея совершить кражу не мог, так как со слов охранника он каждые два часа совершал обход и, следовательно, в два часа ночи все было на месте.\"},{\"id\":560,\"book\":\"aniskin\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к нагрудному кресту «старца» и к тому, что нашли у него на столе.\",\"Сверь крест старца с тем, какие кресты носят староверы. Что нашли у него в рясе, кроме денег?\"],\"short\":\"Жулик в рясе: у староверов кресты восьмиконечные, а у него обычный; в отделе нашли сигареты, грех для староверов.\",\"answer\":\"Нагрудные кресты у старообрядческих священников только восьмиконечные. Это и привлекло внимание Анискина. Ну а во время обыска у «старца» были обнаружены еще и сигареты, а ведь у староверов один из самых главных грехов — курение.\"},{\"id\":561,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Вспомни, что Носкин сказал о времени своего алиби и что полиция ему сообщила.\",\"Сравни: назвал ли Носкин время алиби сам, и знал ли он, когда именно убили дядю?\"],\"short\":\"Носкин: назвал алиби с трех до пяти, хотя сыщики не говорили, когда убили дядю, значит, знал время точно.\",\"answer\":\"Носкин, заявляя о своем алиби, сообщил, что с 3 до 5 был дома. Но сотрудники милиции не сообщали ему, в какое время был убит его дядя. А он точно знал это время. Следовательно, он имеет непосредственное отношение к этому преступлению.\"},{\"id\":562,\"book\":\"aniskin\",\"lv\":3,\"pic\":false,\"ok\":1,\"hints\":[\"Посмотри, что каждый из троих достал из карманов, и кто из них выглядел самым уверенным.\",\"Чем режут сумки, если резать монетой? Кто из троих носил с собой то, что можно отточить?\"],\"short\":\"Второй, «плюгавый»: в кармане монетки, которыми режут сумки; судя по речи, он опытный рецидивист.\",\"answer\":\"Карманник, специализирующийся на разрезании сумок или одежды для совершения кражи, использует в качестве орудия труда кусок лезвия бритвы или отточенную монету. Такой аксессуар помогает легко разрезать сумки, карманы и пакеты, а при опасности от монетки можно быстро избавиться. Таким образом подозреваемым оказался второй мужчина, у которого и были обнаружены монетки. Да и манера его разговора указывает, что у него большой опыт общения с милицией.\"},{\"id\":563,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, какая погода была утром, и что ветер делает с купюрами, лежащими на земле.\",\"С утра дул сильный ветер. Могли ли купюры лежать у дороги, если бы их рассыпали ночью?\"],\"short\":\"Антон: деньги, выпавшие у дороги утром, унесло бы ветром, который дул с утра; история выдумана.\",\"answer\":\"С утра дул сильный ветер, и если бы все было так, как описал сотрудник обменника, то деньги «оброненные» преступниками просто-напросто улетели бы…\"},{\"id\":564,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, в каком порядке по законам природы происходят вспышка молнии и раскат грома.\",\"Что раньше — вспышка молнии или раскат грома? Сравни с тем, что рассказал Моисеев.\"],\"short\":\"Василий Моисеев: гром раздался раньше молнии, так не бывает; историю про медведя он выдумал.\",\"answer\":\"Зимние грозы — это, конечно, редкость, но ничего необычного в них нет. Но вот чтобы сначала гремел гром, а потом била молния — это уже из области сказок.\"},{\"id\":565,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к тому, что лежало в мешке змеелова, кроме самих змей.\",\"Откладывают ли гадюки яйца или рождают уже готовых детёнышей?\"],\"short\":\"Змеелов сам подложил яйца: гадюки живородящие и яиц не откладывают, значит, эти яйца не из их гнезда.\",\"answer\":\"Гадюки относятся к живородящим змеям, поэтому процесс развития яиц происходит внутри самок, после чего детеныши появляются на свет уже готовыми к самостоятельной жизни. В отличие от многих других змей, яиц гадюка не откладывает.\"},{\"id\":566,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к тому, как Соколов устроился за рулём.\",\"Какого роста Соколов и каким было сиденье, если в эти дни машину водила жена?\"],\"short\":\"Соколов сам водил машину: сиденье уже стояло под его двухметровый рост, значит, жена за рулём не была.\",\"answer\":\"Хотя жена Соколова утверждала, что муж два дня не садился в машину и утром за рулем была она, ее муж, демонстрируя полицейским работу тормозов, удобно устроился за рулем. Если бы машину последнее время водила его жена, ему, человеку двухметрового роста, пришлось бы подгонять под свой рост сиденье.\"},{\"id\":567,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к ногам императора и к тому, во что он обут.\",\"Что носили вместо ботинок при Петре I и когда появились ботинки на шнуровке?\"],\"short\":\"Подделка: Пётр I носил ботфорты, а ботинки со шнуровкой появились позже; звезда ордена тоже нарисована неверно.\",\"answer\":\"Мошенника подкачало слабое знание истории.\\n\\nВо-первых, общеизвестным фактом является то, что Петр I предпочитал носить ботфорты. Мало этого, своим указом он обязал их носить и всех других придворных. А ботинки со шнуровкой появились значительно позже.\\n\\nВо-вторых, звезду ордена не крепят к ленте. Ее носят на левой стороне груди. На ленте носят знак ордена и он располагается возле бедра.\"},{\"id\":568,\"book\":\"aniskin\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к словам, которыми «Джек» описывает себя и газеты.\",\"Когда в обиход вошли слова «серийный убийца» и «маньяк»?\"],\"short\":\"Письмо подделка: Бобби отомстил за розыгрыш 1 апреля, а слова «серийный убийца» и «маньяк» появились через век.\",\"answer\":\"Во-первых, на нижнем листе — письме от Бобби Брауна — стоит дата — 1 апреля. Бобби просто-напросто отомстил Федору, выставившему его на посмешище.\\n\\nНо есть более веская причина, почему Анискин понял, что речь идет о розыгрыше. В письме используются термины «серийный убийца» и «маньяк». В реальности они стали использоваться только столетие спустя — в 70-е годы 20 века их ввел в обиход криминальный психолог Роберт Ресслер.\"},{\"id\":569,\"book\":\"aniskin\",\"lv\":3,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к тому, что рассказчик говорит о трюме и о том, кто там работал.\",\"Кто жил в самом низу трюма старых пароходов и на каком языке говорят «Бвана»?\"],\"short\":\"Самозванец: кочегаров на современных судах давно нет, а «Бвана» — африканское слово из суахили, не балийское.\",\"answer\":\"Во-первых, профессия кочегаров на кораблях исчезла вместе с пароходами, работающими на твердом топливе. На современных пароходах, работающих на жидком топливе, их заменили судовые механики.\\n\\nНу а во-вторых, обращение «Бвана, бвана» возможно у жителей Африки, говорящих на суахили, а Бали находится в Индонезии и местное население говорит на балийском языке.\"},{\"id\":570,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к тому, что Баляйкин рассказывает о своих последних выходных.\",\"Какие цветы он говорит, что рвал, и цветут ли они осенью?\"],\"short\":\"Баляйкин: рассказал, что «нарвал тюльпанов и нарциссов» на прошлых выходных, а осенью они не цветут — значит, врёт.\",\"answer\":\"Баляйкин неплохо продумал алиби — сосед видел его всего неделю назад (в то время как труп «образовался» совсем недавно). Однако он сказал, что приехал «нарвать тюльпанов и нарциссов». Неопытный дачник, он совсем забыл, что эти растения уже не цветут осенью. Именно на этой неточности и поймал его Анискин.\"},{\"id\":571,\"book\":\"aniskin\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к соседней стройке: что там делали ночью и что там гудело?\",\"Вчера над соседним двором гудел подъемный кран. Что он может поднять над внутренним двором?\"],\"short\":\"Крановщик со стройки по соседству: развернул стрелу крана над внутренним двором и поднял «Феррари» краном.\",\"answer\":\"Единственный, кто мог украсть «Феррари», — крановщик на стройке. Если стрелу подъемного крана развернуть, она как раз окажется прямо над внутренним двором, где стоял автомобиль.\"},{\"id\":572,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к тому, как Нечипоренко говорит о своих прежних делах и о том, почему он ушел из органов.\",\"Как сотрудники правоохранительных органов называют возбуждение уголовного дела? Сравни с тем, что сказал Нечипоренко.\"],\"short\":\"Слова «завели уголовное дело»: настоящий сотрудник сказал бы «возбудили», так говорят только самозванцы.\",\"answer\":\"Человек, проработавший долгое время в правоохранительных органах, никогда не будет говорить «завели дело». «Заводятся» тараканы и мыши, а уголовные дела ВОЗБУЖДАЮТСЯ!\"},{\"id\":573,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к тому, что дачник делал на своем участке, когда сыщики подошли к воротам.\",\"Что будет с растениями, если полить их ледяной водой в самое жаркое время дня?\"],\"short\":\"Он поливал грядки в полдень под палящим солнцем и ледяной водой: так не делает ни один огородник, вор не знает азов.\",\"answer\":\"Ни один хозяин не будет поливать грядки в жаркий день в полдень — солнце просто жжет растения. А кроме того, поливать растения ледяной водой — это значит намеренно убивать их. Вора подвело незнание элементарных азов огородничества.\"},{\"id\":574,\"book\":\"aniskin\",\"lv\":3,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к слуховому аппарату и очкам свидетеля, который уверял, что видел все из окна.\",\"Может ли человек в очках с толстыми линзами разглядеть ухмылку с расстояния пятидесяти метров?\"],\"short\":\"Митрофан Арнольдович: он лжет, что видел убийство — без слухового аппарата спящий не услышал бы крика, а в толстых очках на 50 метров ничего не разглядеть.\",\"answer\":\"Преступник — Митрофан Арнольдович. На ночь слуховой аппарат снимают, значит, спящего пенсионера не мог разбудить крик. Кроме того, труп обнаружен в 50 метрах от здания: вряд ли старик, который носит очки с толстыми линзами, мог на таком расстоянии увидеть все подробности убийства, сосчитать количество ножевых ударов и тем более рассмотреть ухмылку на лице Ивана Олеговича.\"},{\"id\":575,\"book\":\"aniskin\",\"lv\":3,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к надписи на открытке и к тому, как называлась армия в том году, на который она указывает.\",\"Как в 1938 году называлась наша армия? Сравни с тем, что написано на открытке, и с формой солдата на картинке.\"],\"short\":\"Подделка: в 1938 году армия называлась РККА, «Советской» стала в 1946 году, а погоны на солдате появились только в 1943-м.\",\"answer\":\"«20 лет Советской Армии» — значит, дело происходит в 1938 году. Но в то время армия называлась РККА (Рабоче-крестьянская Красная). Советской она стала лишь в 1946 году. То есть на подлинной открытке должно было быть написано: «20 лет РККА». Кроме того, солдат изображен в погонах. Погоны же, упраздненные после революции, в РККА появились лишь во время войны — в 1943 году.\"},{\"id\":576,\"book\":\"aniskin\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к тому, что молящиеся делают, входя в мечеть, и что видно на их ногах.\",\"Что все молящиеся делают с обувью, прежде чем встать на коврик? Кто этого не сделал?\"],\"short\":\"Того, кто сидит в обуви: молящиеся перед намазом разуваются при входе в мечеть, а грабитель в спешке этого не сделал.\",\"answer\":\"Того, кто сидит в обуви. Молящиеся перед молитвой снимают обувь, заходя в мечеть.\"},{\"id\":577,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к тому, что каждый из задержанных рассказывает о себе и о своих занятиях.\",\"Сравни то, что рассказывает задержанный про Рим и Цезаря, с тем, что известно из истории.\"],\"short\":\"Историка: назвал Цезаря императором, хотя Рим был республикой, а Колизей построен через сто с лишним лет после его гибели\",\"answer\":\"«Историк» допустил сразу два грубейших ляпа. Во-первых, Гай Юлий Цезарь не мог быть императором, ибо Рим тогда был республикой, а не империей. Во-вторых, Колизей возвели намного позже гибели Гая Юлия. Цезарь был убит в 44 году до нашей эры, а Колизей закончили строить лишь в 80 году нашей.\"},{\"id\":578,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, когда в России впервые появились такие игрушки.\",\"Крепостное право отменили в 1861 году. Могла ли матрешка существовать при барине, если её придумали позже?\"],\"short\":\"Матрешка — новодел конца XIX века: в годы крепостного права таких игрушек ещё не было\",\"answer\":\"Матрешки — это не старинные русские игрушки, а относительный новодел. Лишь в конце 1890-х годов матрешку впервые выдумал и вырезал талантливый токарь-умелец Василий Звездочкин, а расписал художник Сергей Малютин. В годы крепостного права никаких матрешек не существовало в принципе.\"},{\"id\":579,\"book\":\"aniskin\",\"lv\":3,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к тому, как Фролов рассказывает о детстве и переезде в город.\",\"Вспомни, какой город был столицей Украинской ССР в 1920-е годы, и сравни это с рассказом Фролова.\"],\"short\":\"Фролов назвал Киев столицей Украинской ССР в 1925 году, хотя тогда ею был Харьков: биография выдумана\",\"answer\":\"Задержанный очень подробно рассказывает этапы своей жизни, видно, что он выучил «автобиографию» назубок. Ошибся он, когда решил для красного словца приукрасить рассказ отсебятиной. С 1919 по 1934 год столицей УССР был Харьков, а не Киев. На незнании этого факта Солодов и подловил Фролова.\"},{\"id\":580,\"book\":\"aniskin\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к конверту: что на нем написано, кроме адреса и марки?\",\"Когда в СССР ввели почтовые индексы? Сравни эту дату с годом, указанным в письме.\"],\"short\":\"Конверт: на нем стоит почтовый индекс, а в 1956 году индексов в СССР ещё не было (ввели в 1971-м)\",\"answer\":\"Все дело в конверте, где находилось письмо. После начала Второй мировой войны по всему миру (и СССР не был исключением) в целях соблюдения секретности отменили почтовые индексы. Снова индекс стал применяться в Советском Союзе лишь в 1971 году. Поэтому на конверте, который якобы был передан в 1956 году, индекса быть не могло. А раз конверт фальшивый, скорее всего, подделка и письмо.\"},{\"id\":581,\"book\":\"aniskin\",\"lv\":3,\"pic\":false,\"ok\":2,\"hints\":[\"Посмотри, какая музыка звучала на танцах в доме отдыха и когда её написали.\",\"Сравни год написания «Школьного вальса» с годом, в который происходит история, и вспомни, когда в Подмосковье появились электрички.\"],\"short\":\"Письмо выдумано: в 1928 году танцевали под «Школьный вальс», написанный в 1950-м, и ездили на электричке, которой ещё не было\",\"answer\":\"Если уж автор письма дословно копировала все из дневника мамы, то там никак не мог фигурировать «Школьный вальс», написанный лишь в 1950 году. Кроме того, электрички были запущены в Подмосковье лишь в 1929 году. А первая электричка в СССР появилась в 1926 году под Баку.\"},{\"id\":582,\"book\":\"aniskin\",\"lv\":3,\"pic\":false,\"ok\":0,\"hints\":[\"Внимательно прочитай бытовые подробности, которые автор письма перечисляет, собираясь на Кавказ.\",\"Вспомни, как в 1841 году чистили зубы и когда в России появились зубные щётки.\"],\"short\":\"Зубная щётка в письме 1841 года: её тогда ещё не было в моде, зубы чистили порошком и пальцем\",\"answer\":\"Отец Игоря неплохо подделал стиль Лермонтова и умело оперирует фактами. Прокололся он на бытовых мелочах. Погибший в 1841 году Михаил Юрьевич никак не мог назвать зубную щетку предметом, необходимым офицерам. В России тогда зубы чистили зубным порошком при помощи пальца, щетки вошли в моду гораздо позже. Да и обсуждать вопросы гигиены с дамой в то время было не принято.\"},{\"id\":583,\"book\":\"werner\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Посмотри на автомобиль Линденов на картинке и подумай, с какой стороны из него выходят.\",\"Руль у машины Линденов справа. Что это значит для того, с какой стороны Бланка вышла на улицу?\"],\"short\":\"Машина с рулем справа: Бланка вышла на тротуар, а не на мостовую, где ее мог ограбить мотоциклист.\",\"answer\":\"Подойдя к вилле, инспектор заметил, что машина Линденов имеет руль с правой стороны и, следовательно, Бланка, остановившись перед магазином, вышла из машины на тротуар, а не на мостовую, где ее мог ограбить мотоциклист.\"},{\"id\":584,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к одежде полковника: что на его плаще и где на груди?\",\"Звезда Героя России крепится слева, а у полковника звезды справа. Что тут не так?\"],\"short\":\"Самозванец: награды на плаще не крепят, Звезда Героя носится слева, а второй раз звание Героя России не дают.\",\"answer\":\"Во-первых, на плаще не крепят никакие награды.\\n\\nВо-вторых, Звезда Героя России крепится с левой стороны груди, а не правой.\\n\\nВ-третьих, звание Героя России начали присваивать с 1992 года, т.е. через несколько лет после вывода советских войск из Афганистана.\\n\\nНу и в-четвертых, вторичное присвоение звания Героя России не производится.\"},{\"id\":585,\"book\":\"werner\",\"lv\":1,\"pic\":false,\"ok\":3,\"hints\":[\"Обрати внимание на то, как незнакомец вошел в квартиру и чем освещал себе дорогу.\",\"Что будет, если зажечь спичку в квартире, где только что открыли газ?\"],\"short\":\"Незнакомец не убийца: тот, кто открыл газ, не вернулся бы в квартиру с зажженной спичкой.\",\"answer\":\"Убийца, который открыл в квартире газ, не вернулся бы в нее с зажженной спичкой…\"},{\"id\":586,\"book\":\"aniskin\",\"lv\":3,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к настенному календарю в кабинете Митрофанова и к дате, которая на нем стоит.\",\"Какая дата стоит на календаре и что она говорит о том, был ли вчера в кабинете кто-то из своих?\"],\"short\":\"Оба лгут: календарь в кабинете переведен на 1 августа, значит, вчера там был кто-то свой, а не посторонний.\",\"answer\":\"На стене висит перекидной настенный календарь, курсор-бегунок которого установлен на дате 1 августа. Значит, вчера в кабинете кто-то был, перевернул страницу календаря и установил бегунок на дату 1 августа. Посторонний человек этого делать бы не стал…\"},{\"id\":587,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Обрати внимание на то, когда вдова приехала домой и что известно о времени, когда был завод будильника.\",\"Покойный завел будильник только после 20 часов. Кто из двух женщин в это время уже был в доме?\"],\"short\":\"Жену: будильник муж мог завести только после 20 часов, значит, он был жив при её приезде, а выстрел она не слышала.\",\"answer\":\"Это жена. Покойный мог завести будильник только после 20 часов. Значит, он был жив, когда приехала жена. Вместе с тем она утверждает, что ничего не слышала, в то время как звук выстрела не услышать практически невозможно.\"},{\"id\":588,\"book\":\"aniskin\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к майке задержанного и к тому, как на ней расположены пятна.\",\"Кровь из порезанной артерии брызжет, а из носа обычно стекает. Что видно на майке?\"],\"short\":\"Рецидивист врет: на майке брызги крови из порезанной артерии, а при носовом кровотечении так не бывает.\",\"answer\":\"По брызгам крови на майке преступника. Брызги крови образуются при повреждении артерии. При внутреннем носовом кровотечении возможны потеки крови, скатывающиеся капли и т.п., но забрызгать кровью свою майку невозможно.\"},{\"id\":589,\"book\":\"werner\",\"lv\":1,\"pic\":false,\"ok\":1,\"hints\":[\"Обрати внимание на мороженое, которое купил сын Гаусена, и на жаркую погоду в тот день.\",\"За сколько минут мороженое в жару тает? Сколько времени прошло с момента покупки?\"],\"short\":\"Гаусен лжет: мороженое, купленное полчаса назад в такую жару, растаяло бы полностью, а не просто подтаяло.\",\"answer\":\"В жаркий летний день за полчаса мороженое растаяло бы полностью или почти полностью.\"},{\"id\":590,\"book\":\"aniskin\",\"lv\":3,\"pic\":false,\"ok\":0,\"hints\":[\"Обрати внимание на то, как каждый из троих объясняет свою поездку в Калининград.\",\"Как назывался Калининград во время Великой Отечественной войны?\"],\"short\":\"Федора Михайловича: дед якобы ушел на фронт из Калининграда, а тогда город назывался Кенигсберг.\",\"answer\":\"Анискин задержал Федора Михайловича. Калининград стал называться так лишь после Великой Отечественной войны, когда он отошел к СССР. Ранее это был прусский город Кенигсберг. И призваться отсюда «на фронт» в Красную армию дед подозреваемого никак не мог.\"},{\"id\":591,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай о том, с какой стороны дороги мог оказаться человек, которого выбросили из машины.\",\"Вельтер ехал в Помдорф, в ту же сторону, что и Фитт. С какой обочины выпал бы пассажир?\"],\"short\":\"Вельтер выдумал историю: по его рассказу он должен был лежать на правой обочине, а не на левой.\",\"answer\":\"Если бы он говорил правду, то он должен был лежать на правой стороне обочины, а не на левой.\"},{\"id\":592,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Обрати внимание на то, как Гевин демонстрировал перчатку и часы на руке.\",\"Найденная перчатка с левой руки. Какая перчатка осталась у Гевина, если вторую он потерял?\"],\"short\":\"Гевин невиновен: у него осталась левая перчатка, значит, потерянная была правой, а найденная в гараже левая не его.\",\"answer\":\"Как известно, в гараже была найдена перчатка с левой руки. Перчатка Гевина тоже левая, так как ему, чтобы посмотреть на часы, которые носят на левой руке, пришлось ее сдвинуть.\"},{\"id\":593,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Внимательно перечитай список вещей, которые Ремер возил в каждой поездке.\",\"Чего в этом списке не хватает, хотя в дороге без этого обычно не обходятся?\"],\"short\":\"Героин в тюбике зубной пасты: зубной щётки у Ремера никогда не было, а тюбик он возил с собой постоянно.\",\"answer\":\"Ремер перевозил героин в тюбике из-под зубной пасты.\\n\\nИнспектор обратил внимание на то, что он возил с собой тюбик, в то время как у него никогда не было с собой зубной щётки.\"},{\"id\":594,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к тому, в каком состоянии был директор, когда его освободили.\",\"Мог ли человек с завязанным ртом заклеить конверт?\"],\"short\":\"Директор не мог заклеить конверт, ведь рот у него был завязан платком: значит, конверт заклеил кто-то другой.\",\"answer\":\"Директор не мог заклеить конверт, так как у него был завязан рот.\"},{\"id\":595,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Обрати внимание на то, кто звонил из кабинета и что было с отпечатками.\",\"Почему инспектор ничего не нашёл на телефоне и на сейфе, хотя к ним явно кто-то прикасался?\"],\"short\":\"Секретарь: он звонил Грену из кабинета и вытер все отпечатки, в том числе на телефонной трубке, которой пользовался.\",\"answer\":\"Секретарь. Нигде не было отпечатков пальцев, а ведь секретарь звонил господину Грену из кабинета. После этого он вытер всё в кабинете, включая телефонную трубку, не подумав, что это его выдаст.\"},{\"id\":596,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к шляпе Третнера и к тому, сколько в ней отверстий.\",\"Мог ли Ковары прострелить шляпу так, чтобы в ней осталось одно отверстие?\"],\"short\":\"Третнер: он стрелял через шляпу, в которой прятал пистолет, а второй пистолет потом вложил в руку покойнику.\",\"answer\":\"Ковары не мог прострелить шляпу Третнера так, чтобы на ней осталось только одно пулевое отверстие.\\n\\nПравдоподобнее то, что Третнер стрелял в Ковары через шляпу, в которой он укрывал своё оружие.\\n\\nПотом из другого пистолета он выстрелил в открытое окно, а затем вложил этот пистолет в руку покойнику.\"},{\"id\":597,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к запястьям блондинки и вспомни, куда дул ветер.\",\"Какие следы должны были остаться на руках, если её связывали верёвкой?\"],\"short\":\"Блондинка лжёт: на запястьях нет следов верёвок, а северный ветер не мог отнести лодку на север.\",\"answer\":\"Во-первых, на запястьях блондинки не было следов от верёвки. Во-вторых, поскольку дул северный ветер, парусная лодка не могла быть отнесена в направлении на север.\"},{\"id\":598,\"book\":\"werner\",\"lv\":3,\"pic\":false,\"ok\":1,\"hints\":[\"Вспомни, что никто из четверых не называется своей фамилией, а берёт фамилию дружка.\",\"Сержант ошибся насчёт Берта, а инспектор — насчёт Претцела: проследи, кто под какой фамилией живёт.\"],\"short\":\"Костан — Претцел, Претцел — Берт, Габер — Костан, Берт — Габер: из каждой пары догадок верна ровно одна.\",\"answer\":\"У Костана настоящая фамилия Претцел, у Претцела — Берт, у Габера — Костан, у Берта — Габер.\"},{\"id\":599,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Обрати внимание на то, чьи отпечатки в этом доме были бы естественны, а чьи — нет.\",\"Кто, кроме братьев, знал о монете, видел её и хотел купить?\"],\"short\":\"Янек: только у него был повод стереть отпечатки пальцев, а отпечатки братьев в доме были бы естественны.\",\"answer\":\"Монету мог похитить только Янек, так как у него одного было основание для того, чтобы позаботиться об уничтожении отпечатков пальцев. Отпечатки пальцев двух братьев вполне естественны, поскольку они живут вместе.\"},{\"id\":600,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Подумай, откуда полиция может узнать номера машин, которые стояли у музея той ночью.\",\"Что было вложено за дворники всех машин у музея и что с этими бумагами можно сделать?\"],\"short\":\"В районную дорожную полицию: проверить номера машин, которым в ту ночь выписали штраф за парковку у музея.\",\"answer\":\"Инспектор собирался позвонить в районную дорожную полицию и проверить номера машин, которым был выписан штраф в ту ночь за парковку возле музея. Скорее всего, среди них был и автомобиль вора.\"},{\"id\":601,\"book\":\"werner\",\"lv\":1,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к банану на столике и подумай, сколько времени он мог там пролежать.\",\"Сколько времени нужно банану, чтобы сгнить, если он лежит на открытом столике?\"],\"short\":\"Недавно кто-то был на вилле: банан на столе свежий, а за две недели он давно сгнил бы.\",\"answer\":\"За две недели банан должен был сгнить.\\n\\nТаким образом, кто-то был недавно на вилле.\"},{\"id\":602,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к тому, что сосед рассказал о сне своей жены.\",\"Как очень чутко спящая женщина отреагировала бы на два выстрела за стеной?\"],\"short\":\"Жена соседа, очень чутко спящая, не проснулась от двух выстрелов в соседней квартире: это странно.\",\"answer\":\"Инспектору показалось странным, что жена соседа с таким чутким сном не проснулась от выстрелов в соседней квартире.\"},{\"id\":603,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Подумай, что было бы, если бы свидетель курил в доме, где уже скопился газ.\",\"Что произошло бы в доме, полном газа, если бы кто-то закурил?\"],\"short\":\"Свидетель: в доме, полном газа, его окурок взорвал бы всё сразу, а этого не случилось, значит, газа тогда не было.\",\"answer\":\"Свидетель сказал, что он выбросил окурок сигареты, выходя из дома. Но если бы дом во время его визита был полон газа, то он непременно бы взорвался при зажигании сигареты.\"},{\"id\":604,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к тому, как старушка запиралась и как быстро можно выйти из квартиры.\",\"Сколько времени понадобилось бы убийце, чтобы отпереть все замки и засовы и сбежать по лестнице?\"],\"short\":\"Раковский: старушка сама впустила знакомого, а убийца не успел бы отпереть все замки и уйти по лестнице.\",\"answer\":\"Во-первых, почему убийца побежал по лестнице, хотя безопаснее было бы отступить через окно? Во-вторых, если господин Раковский выбежал сразу же после того, как услышал крик, то убийца не успел бы за это время открыть все засовы и замки и сбежать вниз по лестнице. Зато вполне вероятно, что старушка впустила к себе господина Раковского, так как хорошо его знала.\"},{\"id\":605,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к освещению в комнате и к тому, чем занимался Камас перед выстрелом.\",\"Что горело бы в комнате, если бы Камас сам чистил пистолет и случайно выстрелил?\"],\"short\":\"Не несчастный случай: при чистке оружия в комнате горел бы свет, а его не было, значит, Камаса убили гости.\",\"answer\":\"Если бы произошёл несчастный случай, то в комнате горел бы свет.\"},{\"id\":606,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к магнитофону: что с ним было, когда инспектор подошёл к столу?\",\"Кто мог войти в кабинет после выстрела, если госпожа Винтон к телу, по её словам, не подходила?\"],\"short\":\"Жена: магнитофон был выключен, а после выстрела в кабинет заходил только тот, кто его выключил, то есть она сама.\",\"answer\":\"Магнитофон был выключен, значит, после выстрела кто-то должен был заходить в комнату.\"},{\"id\":607,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к тампону: как давно, по словам чиновника, произошло нападение?\",\"Может ли хлороформ сохранять запах больше десяти часов, если он так быстро испаряется?\"],\"short\":\"Тампон пахнет хлороформом, хотя с нападения прошло больше десяти часов: за это время он бы испарился.\",\"answer\":\"Согласно заявлению чиновника, с момента нападения прошло более 10 часов. В течение такого длительного времени тампон не мог содержать следов хлороформа, так как это вещество очень быстро испаряется.\"},{\"id\":608,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Посмотри внимательно на то, как освещён письменный стол и кресло перед ним.\",\"Откуда должен был падать свет на исписанные страницы, чтобы человек в кресле мог работать ночью?\"],\"short\":\"Настольной лампы: при одном потолочном свете нельзя работать ночью, значит, рукописи Клюгса — инсценировка.\",\"answer\":\"Не хватало настольной лампы. В большой комнате с одной лампой на потолке, расположенной таким образом, что тень от человека в кресле падала бы на бумагу, лежащую перед ним, никто не смог бы работать всю ночь. Клюгс, готовя инсценировку, упустил эту деталь.\"},{\"id\":609,\"book\":\"werner\",\"lv\":1,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к тому, как автомобиль Волецкого освещал луг.\",\"Что произойдёт с фарами автомобиля, если аккумулятор полностью разряжен?\"],\"short\":\"Волецкий сам убийца: при разряженном аккумуляторе он не смог бы включить фары, значит, его рассказ лжив.\",\"answer\":\"С разряженным аккумулятором господин Волецкий не смог бы включить фары своего автомобиля. Следовательно, его показания были лживыми.\"},{\"id\":610,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Обрати внимание на то, когда именно сквозняк смёл бумаги со стола.\",\"Что было бы, если бы Стецковский вошёл в кабинет через дверь, как полицейские?\"],\"short\":\"Стецковский сам убийца: сквозняк сдул бумаги лишь в тот миг, когда вошёл инспектор, значит, он проник через окно.\",\"answer\":\"Если бы Стецковский вошел в кабинет через дверь, так же как и полицейские, сквозняк уже тогда бы сдул бумаги со стола. А поскольку они слетели лишь в тот момент, когда инспектор вошел, то он догадался, что Стецковский проник в кабинет через окно, застрелив Смита.\"},{\"id\":611,\"book\":\"werner\",\"lv\":3,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай о том, в каком состоянии был лоскуток и сколько времени прошло до осмотра тела.\",\"Сколько часов прошло до осмотра тела и что бывает с мокрой тканью в жаркий день?\"],\"short\":\"Лоскуток не мог остаться мокрым: в жаркий день за несколько часов он высох бы, значит, версия о мокром костюме ложна.\",\"answer\":\"Полиция исследовала труп Кличкова через несколько часов после его смерти.\\n\\nКаким же образом в жаркий день, на протяжении всех этих часов, кусок материала не смог высохнуть?\"},{\"id\":612,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Посмотри внимательно на руку погибшего и на то, что в ней лежит.\",\"Может ли человек держать молоток в руке и одновременно схватиться ладонью за рану?\"],\"short\":\"Помощник лжёт: окровавленная ладонь мастера показывает, что молоток вложили ему в руку уже после смерти.\",\"answer\":\"Ладонь была окровавлена, что указывало на то, что мастер схватился ею за рану, чего он не смог бы сделать, имея в руке молоток. Молоток был вложен ему в руку уже после смерти.\"},{\"id\":613,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к телефону на столе директора и к тому, что сделал сержант, когда подошёл к нему.\",\"Мог ли человек без сознания сам положить трубку телефона на место?\"],\"short\":\"Елинек притворялся: трубка лежала на рычаге, а потерявший сознание человек не смог бы положить её на место.\",\"answer\":\"Потеряв сознание, Елинек не смог бы положить трубку телефона на место.\"},{\"id\":614,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Посмотри внимательно на веревку и на руки Диккенса.\",\"Что бывает с ладонями, если быстро съезжать по шершавой веревке со второго этажа?\"],\"short\":\"Диккенс лжёт: съезжая по шершавой веревке со второго этажа, он стёр бы ладони в кровь, и следы остались бы на веревке.\",\"answer\":\"Съезжая по шершавой веревке с такой высоты, Диккенс должен был бы стереть в кровь себе ладони, а на веревке должны были бы остаться следы крови.\"},{\"id\":615,\"book\":\"werner\",\"lv\":3,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, что мог разглядеть студент с лодки на таком расстоянии.\",\"Мог ли он узнать женщину в очках и косынке по фотографии в костюме танцовщицы?\"],\"short\":\"Джим знал Нину раньше: по фотографии в костюме танцовщицы он не мог её опознать, видя издали в очках и косынке.\",\"answer\":\"Джим не мог опознать Нину по фотографии в костюме танцовщицы. Девушку, по его словам, он видел на расстоянии, а она была одета в темные очки, брюки и косынку на голове.\\n\\nЗначит, он знал ее ранее.\"},{\"id\":616,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к острию кинжала и к тому, что произошло с мрамором камина.\",\"Что должно было случиться с кончиком кинжала, если он откололся от мрамора?\"],\"short\":\"Хофер лжёт: кинжал якобы отколол кусок мрамора, но его острие осталось таким же острым, как игла.\",\"answer\":\"Хофер утверждал, что кинжал ударился острием в мрамор и отколол от него кусок. Если все было так на самом деле, то кончик кинжала должен был затупиться, а не остаться таким острым, как игла.\"},{\"id\":617,\"book\":\"werner\",\"lv\":3,\"pic\":false,\"ok\":1,\"hints\":[\"Посмотри на асфальт под машиной, который Новак обвёл жестами.\",\"Что останется сухим на мокром асфальте под машиной, которая простояла там весь дождь?\"],\"short\":\"Сухой след под машиной: её поставили до дождя и увезли лишь после него, значит, она простояла здесь всю ночь.\",\"answer\":\"Если автомобиль был припаркован перед тем, как начался дождь, а увезли его после того, как дождь закончился, то на этом месте асфальт должен был остаться сухим.\"},{\"id\":618,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к тому, в какой одежде Джузеппе был, когда открыл дверь.\",\"Можно ли снять брюки с пристёгнутыми подтяжками, не снимая жилета?\"],\"short\":\"Джузеппе лжёт: брюки с подтяжками нельзя снять, не сняв жилета, а он уверял, что только что раздевался.\",\"answer\":\"Если Джузеппе раздевался, то каким образом ему удалось снять брюки с пристегнутыми подтяжками, не снимая жилета?\"},{\"id\":619,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к тому, что говорили квартиранты о своих деньгах и о том, когда это было.\",\"Какой день недели был вчера, если сегодня понедельник?\"],\"short\":\"Даниель С.: он будто бы вчера снял деньги в банке, но вчера было воскресенье, и банки не работали.\",\"answer\":\"Действие происходит в понедельник, следовательно, Даниель не мог вчера снять деньги в банке, т.к. в воскресенье они не работают. Эта ложь и вызвала подозрение инспектора.\"},{\"id\":620,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к ковру, на котором стоял сейф, и к площади перед предприятием.\",\"Что оставили бы на бежевом ковре люди, прошедшие пешком через грязную перекопанную площадь в дождь?\"],\"short\":\"Нападение придумано кассиром: бандиты, пройдя пешком через перекопанную в дождь площадь, испачкали бы ковёр у сейфа, а он чист.\",\"answer\":\"Если бы преступники пересекли пешком во время дождя перекопанную площадь, то подходя к сейфу, они оставили бы грязные следы на чистом бежевом ковре.\"},{\"id\":621,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Подумай, что можно разглядеть из освещённой комнаты в темноте и тумане.\",\"Откуда владелец мог знать калибр револьвера, если инспектор его не показывал?\"],\"short\":\"Молодой владелец: в тумане и темноте через окно не видно цвета машины, а калибр револьвера он знал, хотя его не показывали.\",\"answer\":\"Во-первых, если на улице были темнота и туман, то через окно освещенной комнаты невозможно было разглядеть цвет автомобиля. Во-вторых, откуда он знал калибр револьвера, который обнаружил инспектор? Он ведь его не показывал.\"},{\"id\":622,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Посмотри, что висело над комодом и что в нём отражалось.\",\"Что должен был видеть Соломон в зеркале, стоя перед комодом?\"],\"short\":\"Соломон лжёт: стоя перед комодом, он увидел бы бандита в венецианском зеркале, а он говорит, что не видел.\",\"answer\":\"Если Соломон, как он рассказывал, стоял перед комодом, он увидел бы злоумышленника в висящем там венецианском зеркале.\"},{\"id\":623,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к тому, что Карл собирался делать перед сном, и к самой бритве.\",\"Мог ли человек, умерший мгновенно, сложить бритву, которую только что держал в руке?\"],\"short\":\"Карл не брился перед сном, а мгновенно умерший не смог бы сам сложить бритву: значит, её сложил кто-то другой.\",\"answer\":\"Кто же бреется перед сном? Можно было бы предположить, что Карл решил покончить жизнь самоубийством… Но в данном случае самоубийство исключено. Поскольку смерть наступила моментально, Карл не мог закрыть бритву.\"},{\"id\":624,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Вспомни, что девушка рассказала о своём спасении и в каком состоянии она была.\",\"Как она могла знать, что директор снял платок, если в тот момент была без сознания?\"],\"short\":\"Секретаршу: она знала, что директор снял платок, хотя лежала без сознания, — значит, инсценировала нападение сама.\",\"answer\":\"Откуда секретарша узнала, что её спас директор? Вполне очевидно, что она передала документы своим сообщникам, а когда услышала, что директор открывает дверь, положила себе на лицо платок с хлороформом.\"},{\"id\":625,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Подумай, откуда должны были взяться пороховые следы и где именно их нашли.\",\"Могла ли пуля, выпущенная из кармана пиджака, оставить порох на теле жертвы?\"],\"short\":\"Валкер: порох на теле Милс означает выстрел в упор, а следы в кармане — от второго, инсценирующего выстрела.\",\"answer\":\"Если бы все было так, как рассказывал директор, то следы пороха были бы только внутри кармана пиджака, а на теле их быть не могло. Валкер застрелил пани Милс, а потом для инсценировки сделал еще один выстрел из кармана пиджака.\"},{\"id\":626,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Вспомни, где стоял пассажир и что он говорил о том, слышал ли выстрел.\",\"Мог ли человек, стоявший рядом с дверью купе, ничего не услышать?\"],\"short\":\"Пассажира в коридоре: он солгал, что не слышал выстрела, хотя стоял рядом с дверью купе, — значит, стрелял он.\",\"answer\":\"Только сумасшедший мог стрелять с моста через окно в тёмное купе. Да и проводник, если бы он слышал звон разбившегося стекла о бетон моста, то услышал бы и звук выстрела с моста. А значит, кто-то стрелял внутри купе. Но в таком случае этот пассажир в коридоре не мог не слышать звука выстрела, так как он стоял рядом с дверью в это купе, а поезд замедлил ход и стук колёс был негромким. Раз он солгал, что не слышал выстрела, то причина одна — он и есть убийца.\"},{\"id\":627,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Посмотри, где именно стоит машина и как она оказалась именно в этом месте.\",\"Докуда доехала бы машина, пущенная без остановки, и кто в ней находился?\"],\"short\":\"Жену: машина пошла бы до конца двора, а стоит посреди него — значит, её остановила сидевшая за рулём жена.\",\"answer\":\"Если бы все было, как рассказывала женщина, то автомобиль должен был проехать весь двор до конца. А так как он стоял посредине двора, значит, его кто-то остановил.\"},{\"id\":628,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, что бухгалтер делал с лампочкой и в каком она была состоянии.\",\"Можно ли голой рукой вывернуть горячую лампочку и потом долго держать её в руке?\"],\"short\":\"Бухгалтер: горячую, долго горевшую лампочку голой рукой не вывернуть и не держать — значит, он лжёт.\",\"answer\":\"Очень трудно голой рукой вывернуть включенную лампочку, которая нагрелась от длительной работы, и уж тем более невозможно держать её в руке длительное время.\"},{\"id\":629,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Вспомни, что говорил инспектор, а что — Равер, когда услышал о смерти садовника.\",\"Что Равер сказал о садовнике такого, о чём инспектор ещё не говорил?\"],\"short\":\"Равера: он сразу спросил «Кто это сделал?», хотя инспектор не говорил об убийстве — значит, он знал, что садовника убили.\",\"answer\":\"Инспектор ничего не говорил об убийстве. Почему же Равер спросил: «Кто это сделал?». Эта фраза и выдала его.\"},{\"id\":630,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Перечитай рассказ задержанного о том, как он попал обратно в ресторан.\",\"Какое слово проговорился задержанный, рассказывая о возвращении в ресторан?\"],\"short\":\"Задержанного: он уверял, что никогда не был в ресторане «Под дубами», но сам сказал, что «вернулся» туда с полицейским.\",\"answer\":\"Человек в комбинезоне утверждал, что никогда не слышал о ресторане «Под дубами» и никогда в нём не был, а между тем в своём рассказе он выразился, что «вернулся» туда вместе с полицейским. Это небольшая оговорка убедила инспектора, что задержанный лгал.\"},{\"id\":631,\"book\":\"werner\",\"lv\":3,\"pic\":false,\"ok\":3,\"hints\":[\"Подумай, кому и как мог достаться каждый из жилетов.\",\"Что случилось бы с мужем, если бы ему достался дырявый жилет?\"],\"short\":\"Жену: она продырявила днище и один жилет, рассчитывая, что мужу достанется дырявый, а если нет — он спасёт её целым.\",\"answer\":\"Расчёт жены был такой: если мужу достанется дырявый жилет, то он утонет, как и было задумано, а если достанется жилет ей, то у мужа будет достаточно сил (ну и целый жилет ему поможет), чтобы её спасти. Вина мужа исключается. Если бы он сам подырявил лодку и жилет, то он не стал бы спасать жену, а дал бы ей спокойно утонуть в озере.\"},{\"id\":632,\"book\":\"werner\",\"lv\":3,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к рубашке покойного и к тому, что было на крыше после дождя.\",\"В каком состоянии была крыша после дождя и к какому времени она успела высохнуть?\"],\"short\":\"Гильс был мёртв уже около девяти: кошачьи следы на рубашке остались от мокрой крыши, которая к часу дня высохла.\",\"answer\":\"Следы испачканных лап кошки на рубашке указывают на то, что Гильс был убит почти сразу после того, как написал письмо — около 9 часов утра. Кошка, возвращавшаяся с прогулки по крыше, прыгнула из окна на грудь Гильса, когда он уже лежал мёртвым на полу. Это должно было произойти не слишком поздно после того, как прошёл дождь, иначе не было бы следов. В то время, когда якобы Гильс разговаривал с племянником, крыша была уже давно сухая.\"},{\"id\":633,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Сравни подпись на книге и подпись на чеке.\",\"Как дядя подписывался на книге, и чего не хватает в подписи на чеке?\"],\"short\":\"Роберт: подпись на чеке без буквы «Т», как у дяди на книге, — подделка; самоубийство исключает отсутствие пороха на рубашке.\",\"answer\":\"Если бы Моретти сам выстрелил себе в сердце, то на рубашке должны были остаться следы пороха. Да и обычно самоубийцы предпочитают стрелять в висок, а не в сердце. Во-вторых, исходя из дарственной надписи на книге, инспектор знал, что писатель подписывался «Карл Т. Моретти». А на чеке буква Т после имени отсутствует, что даёт повод подозревать племянника в фальсификации чека.\"},{\"id\":634,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Посмотри, как именно был взломан стенд и что при этом осталось целым.\",\"Зачем вору выворачивать болты рамы, если проще было разбить стекло кочергой?\"],\"short\":\"Партнёров: вор разбил бы стекло, а не выворачивал болты рамы; целое стекло значит, что стенд открыли свои, инсценировав нападение.\",\"answer\":\"Взломщик не стал бы выворачивать болты, а только бы разбил стекло на стенде той же кочергой, которой якобы был атакован господин Цолеман. Соучастники оставили стеклянную крышку целой, потому что боялись, что осколки стекла повредят другие марки. Взломщика вряд ли это стало бы беспокоить, только лишь в том случае если бы он хотел похитить все марки. Но ведь похищена была только одна, которая находилась внутри футляра. Следовательно, со стороны взломщика такая предусмотрительность была излишней.\"},{\"id\":635,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к тому, что Кола рассказывает о читальном зале и о тех, кто там был.\",\"Может ли громкая ссора пройти незамеченной там, где все сидят в тишине?\"],\"short\":\"Кола: громкая ссора в тихом читальном зале не прошла бы незамеченной — значит, писатель лжёт о библиотеке.\",\"answer\":\"Невозможно себе представить, чтобы громкая ссора в тишине читального зала библиотеки не привлекала к себе внимание посетителей. Следовательно, Кола лгал.\"},{\"id\":636,\"book\":\"seitim\",\"lv\":3,\"pic\":false,\"ok\":0,\"hints\":[\"Сравни, где было солнце утром, когда Сейтимбетов подходил к двери, и где оно было вечером.\",\"Могла ли тень входящего упасть на пол, если вечером солнце светило с другой стороны дома?\"],\"short\":\"Вдова лжёт: вечером солнце светило с другой стороны дома, и тени входящего на полу быть не могло.\",\"answer\":\"Если утром солнце светило следователю в спину, когда он подходил к входной двери, то вечером заходящее солнце находилось на другой стороне дома.\\n\\nСледовательно, когда открылась дверь, то тени на полу от входящего человека быть не могло.\"},{\"id\":637,\"book\":\"werner\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Посмотри, что видно на снимке за окном, и сравни с тем, что Боб говорит о своём утре.\",\"Какая погода на снимке и могла ли она быть такой в то утро, о котором говорит Боб?\"],\"short\":\"Снимок сделан не сегодня: на нём солнечная погода, а утро шестнадцатого было дождливым — Боб лжёт о съёмке.\",\"answer\":\"В тот день утром шел дождь, а снимок был сделан в солнечную погоду. Следовательно, он был сделан в другой день.\"},{\"id\":638,\"book\":\"seitim\",\"lv\":3,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к тому, что Ойсман говорил о шагах над головой и что лежало на полу кабинета.\",\"Слышны ли шаги по толстому ковру, которым был застлан весь кабинет?\"],\"short\":\"Ойсман: шаги на толстом ковре не слышны, значит, он лжёт — сам убил Исаева саблей из-за ордена Святого Павла.\",\"answer\":\"Закончив все необходимые следственные действия, следователи вернулись в отдел.\\n\\n— Как вы догадались, товарищ майор, что это была инсценировка? — спросил Гордеев.\\n\\n— Ойсман прокололся, говоря о том, что они услышали шаги в комнате над головой. Ведь пол в кабинете был застлан толстым ковром, который глушит любые шаги.\\n\\n— А куда же делся похищенный кинжал?\\n\\n— Да не было никакого кинжала Александра Великого! Эту красивую историю придумал Григорий Яковлевич, чтобы увести следствие в сторону. Истинный мотив убийства — орден Святого Павла.\\n\\n— Как? — лейтенант недоуменно взглянул на майора. — Ведь он принадлежит Ойсману.\\n\\n— Вот это он и пытался нам внушить. Ведь никто не знал, кроме него, про этот орден. А тут подвернулся такой удобный случай — замена системы наблюдения в доме. Ойсман, видимо, поднялся вслед за Исаевым в кабинет, когда тот пошел за орденом, и, дождавшись, когда тот достанет его из сейфа, заколол его саблей. Той самой, которую он взял в гостиной якобы для самообороны. Думаю, что эксперты найдут на ней следы крови Исаева.\\n\\n— Ну а затем он спокойно инсценировал проникновение в дом постороннего, — завершил рассуждения майора Гордеев. — И вся эта выдуманная история могла ему помочь в «легализации» ордена как своего собственного.\\n\\n— Молодец, лейтенант, — сказал Сейтимбетов. — Учишься размышлять логически…\"},{\"id\":639,\"book\":\"seitim\",\"lv\":3,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к тому, кто и в какое время был в кабинете и что в это время проезжало мимо офиса.\",\"Кто был в кабинете, когда мимо проехал поезд и заглушил звук выстрела?\"],\"short\":\"Иванов: он застрелил бухгалтера под грохот поезда в половине шестого и сам повесил табличку «Не беспокоить».\",\"answer\":\"Охранник должен был слышать звук выстрела. Ведь он же слышал, как в кабинете бухгалтера бьют часы.\\n\\nЗначит, звук выстрела был заглушен грохотом проезжавшего поезда. В этот момент в кабинете находился Иванов, который и убил бухгалтера, а затем повесил на дверь табличку. Бухгалтер не стал бы ее вешать, т.к. ждал посетителей. Поэтому третий посетитель и не заходил к нему в кабинет.\"},{\"id\":640,\"book\":\"seitim\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к числу, которое Лаврентьев написал на календаре перед смертью. Что могут означать его цифры?\",\"Цифры 12634 — это номера месяцев: 12 — декабрь, 6 — июнь, 3 — март, 4 — апрель. Что получится из первых букв?\"],\"short\":\"Дмитрий Матвеев: цифры 12634 на календаре — номера месяцев, их первые буквы складываются в имя «ДИМА».\",\"answer\":\"Следователь Сейтимбетов понял, что цифры, записанные на настольном календаре обозначают месяцы года: 12 (декабрь), 6 (июнь), 3 (март), 4 (апрель). А сложив вместе первые буквы этих месяцев, он прочитал имя — ДИМА. Таким образом, Лаврентьев указал перед смертью на своего убийцу — Дмитрия Матвеева.\"},{\"id\":641,\"book\":\"seitim\",\"lv\":3,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись ко времени: кто и когда выходил на лестничную площадку перед самым Новым годом?\",\"Новый год наступает не с двенадцатым ударом курантов, а раньше. Кто в этот момент был на площадке?\"],\"short\":\"Горгадзе: в последнюю минуту старого года на лестничной площадке был только он, Роза уже вернулась в квартиру.\",\"answer\":\"Существует распространенное заблуждение о том, что Новый год наступает с двенадцатым ударом курантов на Спасской башне Кремля. На самом деле двенадцать часов наступает с самым началом перезвона курантов. То есть, новый час, день и год начинаются за 20 секунд до первого удара колокола.\\n\\nПоэтому, Сейтимбетов, который был весьма эрудированным человеком и знал это обстоятельство, принял решение задержать Горгадзе, который единственный из всей компании находился на лестничной площадке в момент, когда был убит Сабиров.\"},{\"id\":642,\"book\":\"seitim\",\"lv\":3,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к телефону в коридоре: что с ним происходило, когда погасло электричество?\",\"Беспроводной телефон без электричества не работает. Мог ли жена звонить мужу из темноты?\"],\"short\":\"Жена прокурора: беспроводной телефон не работает без электричества, а она говорила, что звонила мужу в темноте.\",\"answer\":\"Все очень просто. Раз жена взяла трубку и ушла с ней разговаривать на балкон, значит в доме был установлен беспроводной телефон. А они, как известно, не работают без электричества. И поэтому жена не могла позвонить с этого телефона мужу в то время, когда в квартире не было электричества.\"},{\"id\":643,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к электронным часам у кровати Бржецкого. Что с ними происходит после отключения электричества?\",\"После часа без тока часы должны показывать неверное время. Сверь их с часами инспектора. Что ты видишь?\"],\"short\":\"Часы показывают точное время, хотя после часа без тока должны были отстать: кто-то их перевёл, значит, грабёж инсценирован.\",\"answer\":\"Электронные часы, подключенные к электросети дома, после часового перерыва в питании показывали бы неверное время. Следовательно, кто-то (и, наверняка, не мнимый похититель) установил на часах правильное время.\"},{\"id\":644,\"book\":\"seitim\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к тёмным очкам продавщицы и к тому, зачем она носит их в помещении.\",\"Гипнотизёр усыплял жертв за минуту-две. Что помешало бы ему сделать это, если на продавщице были тёмные очки?\"],\"short\":\"Продавщица: ограбление инсценировала она сама, ведь гипноз за минуту не сработал бы сквозь её тёмные очки.\",\"answer\":\"Ограбление инсценировала продавщица.\\n\\nК этому её подтолкнули рассказы о преступлениях, совершённых в городе с помощью криминального гипноза, и удачно подвернувшийся случай с выходом из строя системы наблюдения. Но она не учла того обстоятельства, что очень сложно загипнотизировать человека, если на него надеты тёмные защитные очки. В этом случае гипнотизёру требуется намного больше времени.\"},{\"id\":645,\"book\":\"seitim\",\"lv\":3,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к тому, как звучали выстрелы для полицейских, и что успел сделать охранник за это время.\",\"Посчитай, сколько времени понадобилось полицейским, чтобы развернуть машину и подъехать ко входу после первого выстрела.\"],\"short\":\"Охранник — сообщник грабителя: второй выстрел прозвучал не сразу, как он рассказывал, а с паузой, и разрушил его историю.\",\"answer\":\"Если бы всё происходило так, как рассказывал охранник, то два выстрела должны были прозвучать один за другим. Но полицейские из экипажа ППС услышали второй выстрел не сразу, а через определённый промежуток времени, что рушит всю историю, придуманную охранником.\"},{\"id\":646,\"book\":\"seitim\",\"lv\":3,\"pic\":true,\"ok\":3,\"hints\":[\"Посмотри, все ли тома стоят на полках над сейфом по порядку.\",\"Адвокат был аккуратным человеком, но в каждом многотомнике чего-то не хватало. Чего именно?\"],\"short\":\"Код 8 4 6 3 1 3 4 1: номера томов, которых не хватает в многотомниках на полках над сейфом.\",\"answer\":\"Код замка — 8 4 6 3 1 3 4 1.\\n\\nСейтимбетов обратил внимание на то, что все тома в каждом многотомнике, стоящем на книжных полках над сейфом, были перемешаны, а не расположены, как обычно, последовательно. А ведь адвокат был очень аккуратным человеком, как удалось выяснить. Присмотревшись, он обнаружил, что в каждом многотомнике отсутствует по одному тому. И это при том, что места для отсутствующих книг на полках практически нет. Таким образом он понял, что адвокат с помощью книг оставлял для себя подсказку, чтобы не забыть код от сейфа. И каждый день мог его менять, убирая с полок нужные тома, не боясь его забыть.\"},{\"id\":647,\"book\":\"seitim\",\"lv\":3,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись к слову на снимке: оно написано латиницей, а не кириллицей.\",\"Прочти слово из записки по-английски. Что это за предмет на хоккейной площадке?\"],\"short\":\"Записка «puck» — английское слово «шайба», а не «риск»: тайник с наркотиками был в хоккейных шайбах.\",\"answer\":\"— А ты знаешь, Сергей, — ответил ему Сейтимбетов, — ты был прав, когда сказал мне, что мы затеяли «рискованное» дело. Ты помнишь ту записку, которую обнаружили интерполовцы? Все решили, что это слово написано на кириллице и прочитали его как «риск». На самом деле записка была написана на английском и это было слово «puck», т.е. шайба. Сообщник Смола в записке указал то, где будет оборудован тайник.\\n\\n— Учите английский, Сережа, а то так и будете пилить как Шура, — улыбнулся майор.\"},{\"id\":648,\"book\":\"seitim\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к паролю из записки: на каком языке он набран?\",\"Набери пароль из записки, переключив клавиатуру на русскую раскладку.\"],\"short\":\"Директор Шкряев: пароль, набранный в английской раскладке, читается как «МЕНЯ ЗАСТРЕЛИЛ ШЕФ».\",\"answer\":\"Набирая на клавиатуре пароль, оставленный Ивановым, лейтенант обнаружил, что это на самом деле фраза «МЕНЯЗАСТРЕЛИЛШЕФ», набранная латиницей.\"},{\"id\":649,\"book\":\"seitim\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Подумай, что соседи рассказали о той ночи: было ли слышно собаку?\",\"Вспомни, кто когда-то подарил Березняку овчарку.\"],\"short\":\"Миров, бывший хозяин овчарки: ночью собака не залаяла, значит, гость был ей хорошо знаком.\",\"answer\":\"Убийство совершил Миров. Соседи рассказали, что накануне вечером было все тихо. Если бы кто-нибудь посторонний вечером проник в дом, то собака должна была залаять, а она молчала. Так она могла вести себя только в одном случае, если посетитель был ей хорошо знаком. А таким человеком, как выяснилось, был только Миров, ее бывший хозяин.\"},{\"id\":650,\"book\":\"seitim\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к натюрморту внимательнее: что лежит рядом с вазой на переднем плане?\",\"Тыква и початки кукурузы на переднем плане — растения, которых в Европе при Леонардо ещё не было.\"],\"short\":\"Картина не могла быть написана Леонардо: на ней кукуруза, тыква и подсолнухи, которых в Европе в его время ещё не было.\",\"answer\":\"Ничто из нарисованного на картине — ни подсолнухи, ни кукуруза, ни тыква, не были известны в Европе во времена молодого Леонардо. Эти растительные культуры были завезены в Европу после открытия американского континента Христофором Колумбом. Он сам привез кукурузу в 1496 году после своего второго путешествия в Америку. Доподлинно неизвестно в каком году завезли подсолнечник и тыкву, но это произошло не ранее 1500 года. Да и в других странах Европы все они стали возделываться десятилетиями позже. Не известно, видел ли когда-нибудь в своей жизни Леонардо да Винчи эти растения, но абсолютно точно, что художник, родившийся в 1452 году, не мог их видеть в своей молодости.\"},{\"id\":651,\"book\":\"seitim\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к окнам и стёклам офиса Билайна — какого они цвета?\",\"Что происходит с синим цветом, если смотреть на него через жёлтое стекло?\"],\"short\":\"Девушки солгали про голубую «Тойоту»: через жёлтое стекло голубое не видно, а им понравился Гордеев.\",\"answer\":\"В кабинете у девушек, как и в других кабинетах офиса, были желтые стекла. А желтое стекло выступает как желтый светофильтр, который поглощает синий цвет. Девушки не могли через желтое стекло ни в коем случае увидеть голубой цвет. Он должен был восприниматься как зеленый. Следовательно, им просто понравился лейтенант Гордеев и они таким образом решили продолжить с ним знакомство.\"},{\"id\":652,\"book\":\"seitim\",\"lv\":3,\"pic\":false,\"ok\":2,\"hints\":[\"Посмотри, откуда и как течёт кровь на левой руке и что сказала эксперт о правой.\",\"Какой рукой можно резать другую, если одна повреждена нервом, а после пореза вторая больше не поднимается?\"],\"short\":\"Липатова убили: правую руку повредил нерв, а левая после порезов не поднималась — кровь на ней течёт только вниз.\",\"answer\":\"На это указывает характер повреждений на теле погибшего. На правой руке поврежден крупный нерв. Следовательно, этой рукой после такого повреждения погибший действовать уже не мог. Значит сначала он должен был нанести порезы на левой, а затем ею нанести повреждения на правой руке. Но следы крови на левой руке идут только вниз. Это говорит о том, что левая рука после того, как ей были нанесены повреждения, больше не поднималась вверх.\\n\\nТаким образом характер повреждений позволил следователю сделать вывод о том, что погибший не мог самостоятельно нанести себе подобные повреждения. Значит ему кто-то «помог»…\"},{\"id\":653,\"book\":\"seitim\",\"lv\":3,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись, какие книги оставил Кравчун и что написано на их корешках.\",\"Сложи первые буквы названий этих книг подряд — какое слово получится?\"],\"short\":\"В автоклаве: первые буквы названий книг, оставленных Кравчуном, складываются в «АВТОКЛАВ».\",\"answer\":\"Сейтимбетов не зря решил посмотреть на книги, которые Кравчун отобрал. С их помощью тот указал своему сообщнику в каком из лабораторном оборудовании находится в этот раз тайник с похищенными алмазами. Если сложить первые две буквы названий всех книг, то получается «АВТОКЛАВ». Так и получилось на деле. Сотрудники полиции смогли проследить всю преступную цепочку и задержать всех участников преступной группы.\"},{\"id\":654,\"book\":\"seitim\",\"lv\":3,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к цвету чернил на листке.\",\"Фиолетовые чернила появились не при Пушкине, а между страницами 381 и 382 не лежит ни одного отдельного листа.\"],\"short\":\"Фиолетовые чернила появились только в конце XIX века, а между страницами 381 и 382 не может лежать отдельный лист.\",\"answer\":\"Все просто. Во-первых, между 381 и 382 страницами нельзя ничего положить, так как это страницы одного листа. А во-вторых, во времена Пушкина еще не было чернил фиолетового цвета. Они появились только к концу XIX века. А Пушкин писал т.н. «орешковыми» чернилами, которые имели темно-коричневый цвет.\"},{\"id\":655,\"book\":\"seitim\",\"lv\":3,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к тому, что делал каждый из мужчин за столом до темноты и сразу после нее.\",\"Сравни, сколько кофе было в чашке до того, как погас свет, и сколько — когда его включили.\"],\"short\":\"Собеседник женщины, пивший кофе: в темноте он спрятал ожерелье в чашку, и после света кофе в ней стоял полной.\",\"answer\":\"Преступник — собеседник женщины, который пил кофе. Перед тем как погас свет в зале, он сделал большой глоток кофе. Но когда он ставил чашку на стол после того, как свет снова включили, чашка была полна. Сейтимбетов понял, что преступник сорвал ожерелье и спрятал его в чашке с кофе.\"},{\"id\":656,\"book\":\"seitim\",\"lv\":3,\"pic\":false,\"ok\":1,\"hints\":[\"Подумай, где можно спрятать маленький предмет, если задержанного уже несколько раз обыскали.\",\"Среди чего легче всего спрятать монету? Посмотри, что лежало в кошельке потерпевшей.\"],\"short\":\"Заточенная пятикопеечная монета, спрятанная среди мелочи в кошельке потерпевшей, ведь задержанного обыскали и ничего не нашли.\",\"answer\":\"Следователь Сейтимбетов действительно не забывал о своей неудаче в начале карьеры и собирал информацию о преступнике. Он узнал, что кличку «Пятачок» тот получил за то, что в качестве орудия преступления всегда использовал остро заточенную пятикопеечную монету. Ну, а где легче всего спрятать монету? Среди других монет. Так как задержанного обыскали и ничего не обнаружили, а на месте преступления он ее не выбросил, то остается только одно место — кошелек жертвы.\\n\\nВ кошельке потерпевшей и была обнаружена среди других монет заточенная пятикопеечная монета — профессиональный инструмент карманника. Не правда ли, весьма тонкий психологический ход, позволяющий избавиться от орудия преступления и не быть изобличенным.\"},{\"id\":657,\"book\":\"seitim\",\"lv\":3,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к тому, что именно майор рассматривал лупой: не лицевую сторону картины.\",\"Подумай, как закрепить подлинную картину на другом холсте так, чтобы на подрамнике остались следы.\"],\"short\":\"Подлинник скрепили скобами с чистым холстом, на котором уже стояли печати, а сверху написали копию: следы скоб на подрамнике выдали обман.\",\"answer\":\"Мошенники использовали преступный трюк, изобретенный в середине 70-х годов прошлого века во Флоренции неким Умберто Ломбарди, бывшим директором художественной галереи, художником, а по совместительству и главарем преступной группировки. Достаточно было на чистый холст наложить подлинную картину и в присутствии нотариуса предложить автору картины засвидетельствовать ее подлинность. После этого полотна разделялись, и на чистый холст, уже имеющий на обороте нотариальную печать — свидетельство подлинности, наносилась искусная копия.\\n\\nСейтимбетов смог догадаться о том, что здесь использовался подобный трюк, внимательно осмотрев оборотную сторону картины на подрамнике. На ней отчетливо видны следы скоб, которыми подлинная картина крепилась к фальшивому полотну.\"},{\"id\":658,\"book\":\"werner\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Посмотри, в каком положении были окна у инкассаторов, и какая в тот день стояла погода.\",\"Бандит просунул руку в окно автомобиля, а на улице ведь лил дождь.\"],\"short\":\"Был дождь, значит окна были закрыты, и бандит не мог просунуть руку в окно и схватить сумку: инкассаторы лгут.\",\"answer\":\"Маловероятно, чтобы во время дождя инкассаторы ехали в автомобиле с открытыми окнами. А если они были закрыты, то все не могло происходить так, как они рассказывали инспектору.\"},{\"id\":659,\"book\":\"seitim\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к тому, какой рукой профессор держал книгу и где она лежала, когда его нашли.\",\"В какую сторону читают строки на фарси и под какой рукой лежала раскрытая книга?\"],\"short\":\"Сын лжёт: фарси читают справа налево, а книга лежала в правой руке отца, и водить по строкам правой он не мог.\",\"answer\":\"Во-первых, изобличает книга, которая выпала из руки профессора на пол. Читая книгу на фарси, профессор водил бы пальцем по строчкам не слева направо, как рассказывал его сын, а наоборот — справа налево.\\n\\nВо-вторых, положение книги говорит о том, что профессор держал ее при чтении в правой руке — как обычно и держат книги те, кто читает на фарси. Значит, он не мог водить по строчкам пальцем правой руки.\\n\\nНу и, в-третьих, профессор заметил, что на мизинце отсутствовал след от перстня, а ведь профессор не снимал его много лет. Если перстень сняли только что, то на мизинце остался бы след от него.\\n\\nВсе это и позволило следователю усомниться в правдивости рассказа сына профессора.\"},{\"id\":660,\"book\":\"seitim\",\"lv\":3,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к письменному столу и к книжному шкафу, а не к дверям и окнам.\",\"Посмотри на настольную лампу: как она стоит, и что с книгами на нижней полке среднего шкафа.\"],\"short\":\"Лампа на письменном столе стоит под другим углом, а четвёртая справа книга на нижней полке перевёрнута наоборот.\",\"answer\":\"Кто-то трогал настольную лампу на письменном столе, так как изменился угол ее наклона. И перевернута наоборот четвертая справа книга на нижней полке среднего шкафа.\"},{\"id\":661,\"book\":\"seitim\",\"lv\":3,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, чьи отпечатки должны были остаться на упаковке снотворного, кроме отпечатков погибшей.\",\"Кто, кроме погибшей, должен был касаться упаковки снотворного, когда его продавали?\"],\"short\":\"Муж: на флаконе и упаковке снотворного нет отпечатков аптекаря, продавшего его, значит, он стёр их и оставил отпечатки жены.\",\"answer\":\"На флаконе со снотворным и его упаковке были только отпечатки пальцев погибшей. А должны были быть еще, как минимум, отпечатки пальцев аптекаря, который продал этот препарат. Следовательно, это было не самоубийство, а убийство. Муж стер все отпечатки с упаковки и флакона, чтобы снять с себя подозрения и оставил на нем отпечатки жены, чтобы указать на версию о самоубийстве.\"},{\"id\":662,\"book\":\"seitim\",\"lv\":3,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к тому, что Воронова говорила о записке, и подходила ли она к столу.\",\"Откуда Воронова знает, что написано на листе, если к столу она не подходила?\"],\"short\":\"Жена: она знала текст записки, хотя к столу не подходила, а положение пистолета и гильзы выдаёт инсценировку.\",\"answer\":\"Во-первых (и это самое главное), женщина только вместе с полицейскими зашла в кабинет погибшего и не подходила к столу. Откуда тогда она знает о том, что было написано в предсмертной записке?\\n\\nВо-вторых, при самоубийстве редко бывает такое, чтобы оружие осталось в руке трупа. В руке пистолет может остаться, если выстрел производится в лежачем или слегка приподнятом положении. При этом рука продолжает сжимать пистолет, а не покоиться на нем, как на рисунке.\\n\\nВ-третьих, гильза из пистолета Макарова вылетает вверх, вправо и назад на 2–5 метров. И при данном расположении трупа она не могла упасть возле стула, а должна была находиться справа перед или сбоку от стола.\\n\\nВсе это и позволило сделать вывод, что Воронова инсценировала самоубийство мужа.\"},{\"id\":663,\"book\":\"seitim\",\"lv\":3,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к тому, что Старцев слышал на лестнице и где лежала пайцза.\",\"В наружном кармане куртки, кроме пайцзы, был только проездной билет. Что тогда могло звенеть?\"],\"short\":\"Старцев: он убил Ложкина, а рассказ о звенящей в кармане пайцзе выдумал, ведь в её кармане не было ничего металлического.\",\"answer\":\"Старцев утверждает, что слышал, как Ложкин звенел золотой пайцзой в кармане, когда спускался по лестнице на улицу. Но в кармане, где лежала пайцза, не было больше ничего металлического, что могло бы звенеть. Следовательно, его история — фальшивка.\"},{\"id\":664,\"book\":\"seitim\",\"lv\":3,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к тому, как эксперт описала смерть и где стоял бокал с вином.\",\"Могла ли женщина, которая бежала босиком с бала, остаться в белоснежных чулках?\"],\"short\":\"Муж Егор Прохоров: убил жену до бала, а на бал привёз любовницу в маске, чтобы разыграть «бегство Золушки».\",\"answer\":\"Во-первых, эксперт-криминалист заключила, что смерть была «практически мгновенной». Следовательно, бокал с вином погибшая должна была выронить, а не поставить на тумбочку рядом с кроватью.\\n\\nВо-вторых, на погибшей были «белоснежные чулки». Как же она в них бежала с бала? Они ведь должны были запачкаться.\\n\\nСейтимбетов догадался, что Прохоров убил свою жену перед балом, а на бал поехал со своей любовницей. Она была так похожа на его жену, а лицо ее скрывала маска. Чтобы ее не разоблачили, они и разыграли эту сцену с «бегством Золушки с бала».\"},{\"id\":665,\"book\":\"seitim\",\"lv\":3,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к обуви Наташи: на фотографии и в парке она выглядит по-разному.\",\"Какой каблук был у туфель, в которых Наташа ушла от друзей, и какой — у мокасин, в которых её нашли?\"],\"short\":\"Мужа Джабраилова: на фото Наташа уходила от друзей на каблуках, а в парке была в мокасинах — значит, заходила домой переобуться.\",\"answer\":\"Сейтимбетов заподозрил в убийстве мужа погибшей — Джабраилова. На фотографии, которую сделала Мария, видно, что его жена ушла от своих друзей в туфлях на высоком тонком каблуке, а ее нашли в мокасинах, у которых каблук небольшой. Так что, вопреки утверждению мужа, Наташа должна была вернуться домой от друзей, чтобы там поменять обувь.\"},{\"id\":666,\"book\":\"seitim\",\"lv\":3,\"pic\":true,\"ok\":2,\"hints\":[\"Присмотрись к окнам квартиры: куда они выходят и что видно из них.\",\"Куда выходят окна квартиры Непряева и где в вечернее время заходит солнце?\"],\"short\":\"Давлетов: окна квартиры выходят на восток, и вечернее солнце не могло светить Непряеву в лицо, как он рассказал.\",\"answer\":\"Окна квартиры Непряева выходят на восток. Это понятно по виду из окна. Согласно православным канонам алтарь церкви должен быть ориентирован на восток, а главный вход в храм — на запад. Могут быть отклонения, но алтарь никогда не располагается на западе. Сейтимбетов мог, конечно, и не знать таких тонкостей. Но он стоял утром возле окна и видел с какой стороны светило солнце. Следовательно, вечером солнце находилось с другой стороны дома и его лучи никак не могли падать на лицо Непряева, как рассказывал Давлетов.\"},{\"id\":667,\"book\":\"seitim\",\"lv\":3,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к тому, что Юрченко ел и пил в тот вечер, и почему он выжил.\",\"Чем нейтрализуют цианистый калий и что в больших количествах съел Юрченко?\"],\"short\":\"Юрченко: он сам подсыпал яд в кофейник, а сахар и колбаса с нитритом должны были нейтрализовать цианид.\",\"answer\":\"Отравителем оказался Юрченко. Чтобы отвести от себя подозрения, он тоже выпил кофе с ядом. Но, судя по всему, он имел прекрасные познания в области химии и знал о некоторых особенностях цианидов, например, о том, что их действие на организм нейтрализуется антидотами. Таким антидотом может выступать сахар, поэтому Юрченко весь вечер и употреблял такое количество продуктов, содержащих сахар. Ну а чтобы подстраховаться — съел ещё и большое количество колбасы, так как при производстве колбасы, особенно домашней, используют нитрит натрия, ещё одно вещество, инактивирующее цианиды. Таким образом, всё поведение Юрченко на этой вечеринке говорило только об одном, что он готовился к употреблению цианистого калия и его нейтрализации.\"},{\"id\":668,\"book\":\"seitim\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись, кто в фирме курит, а кто нет.\",\"Сопоставь: кто курит «Мальборо» в фирме и кто из двух подозреваемых не курит вообще.\"],\"short\":\"Сугробов: он не курит, а окурок «Мальборо» подбросил, чтобы подставить Петрушина.\",\"answer\":\"Следователь приказал арестовать Сугробова. Если бы преступником был Петрушин, он, тщательно уничтожив все свои следы в кабинете, ни за что не оставил бы свой окурок в пепельнице. Окурок был специально оставлен Сугробовым в пепельнице, чтобы подозрение пало на Петрушина.\"},{\"id\":669,\"book\":\"seitim\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к ковру в зале и к тому, как на нём отпечатываются мокрые следы.\",\"Представь: мокрые ботинки прошли три комнаты по толстому ковру. Что осталось бы на нём в каждой из них?\"],\"short\":\"Бородач не шёл через три комнаты: грязные следы есть только в зале, где он инсценировал вход через окно.\",\"answer\":\"Если Бородач действительно шёл с улицы через три комнаты, обутый в грязные ботинки, то толстый ковёр в этих комнатах должен был впитать влагу и грязь. Когда он дошёл бы до зала, обувь уже перестала бы оставлять отчётливые мокрые следы.\\n\\nА на месте преступления мы видим чёткие следы именно в зале, то есть в четвёртой комнате. Получается, Бородач никаких трёх комнат не проходил. Он всё время находился внутри и оставил следы только там, где инсценировал «вход убийцы через окно».\\n\\nИменно это и позволило Гордееву уличить его во лжи.\"},{\"id\":670,\"book\":\"seitim\",\"lv\":3,\"pic\":true,\"ok\":3,\"hints\":[\"Вспомни, какой стороной подкова с шипами прижата и как её поставили.\",\"Представь, как лошадь бьёт задними копытами. Где окажутся шипы, если удар идёт снизу вверх?\"],\"short\":\"Подкову прибили к доске и ударили ею, но не перевернули: отметины легли не так, как от копыта.\",\"answer\":\"Лошадь бьёт задними копытами снизу вверх. При таком ударе рваные раны от шипов должны были бы оказаться наверху, а след от округлой части подковы напоминал бы «лодочку». У Данилова же всё было наоборот.\\n\\nЗначит, кто-то попытался инсценировать несчастный случай: прибил подкову к доске и ударил ею по голове. Но преступник допустил промах — он не перевернул подкову. Именно эта ошибка и выдала убийство.\"},{\"id\":671,\"book\":\"seitim\",\"lv\":1,\"pic\":false,\"ok\":2,\"hints\":[\"Сравни, что он рассказывает про туман и что — про вора.\",\"Может ли человек, который дальше метра ничего не видит, разглядеть и вора, и сумочку?\"],\"short\":\"Задержанный сам вор: он уверяет, что в густом тумане ничего не видно, но при этом всё разглядел.\",\"answer\":\"Гордеев, рассказывая эту историю майору Сейтимбетову, усмехнулся:\\n\\n— Представляете, в тумане дальше метра ничего не видно, а он уверяет, что оказался в центре городка и ещё сумочку разглядел. Тут уж ясно — туман был только в его рассказе.\"},{\"id\":672,\"book\":\"seitim\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к тому, как Бухреев описывает игру: всё ли в его рассказе соответствует правилам регби?\",\"Вспомни, какие пасы разрешены в регби. Можно ли отдавать мяч вперёд?\"],\"short\":\"Бухреев лжёт: в его рассказе Мур отдал пас вперёд, а в регби так играть нельзя — матча он не смотрел.\",\"answer\":\"Если бы Бухреев был «страстным поклонником» регби, то он бы знал, что по правилам игры давать пас вперед в регби нельзя — только назад. В отличие от него, следователь Сейтимбетов прекрасно разбирался в регби.\"},{\"id\":673,\"book\":\"seitim\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к предметам, которые нашли у четверых. Какой из них постоянно нужен коллекционеру марок?\",\"Что филателист всегда держит под рукой, когда разглядывает марку? Было ли это на столе в кабинете?\"],\"short\":\"Друг хозяина-филателист: он ударил Коробейникова его лупой, которой на столе не оказалось, а нашли её у него.\",\"answer\":\"Сейтимбетов понял, что орудием убийства является лупа. У любого филателиста она всегда находится под рукой. А так как Коробейников был убит у себя в кабинете в то время, когда изучал марку, то лупа должна была находиться на столе, но ее там не было. Следовательно, подозрение падает на человека, у которого она была обнаружена.\"},{\"id\":674,\"book\":\"seitim\",\"lv\":2,\"pic\":true,\"ok\":2,\"hints\":[\"Посмотри внимательно на запястье «прадеда» на фотографии.\",\"Какие часы носили мужчины в 1890 году: карманные или наручные?\"],\"short\":\"Фото подделано: на руке «прадеда» наручные часы, которых в 1890 году не носили, а подпись написана без дореформенного «ъ».\",\"answer\":\"На руке «прадеда» на фотографии отчётливо видны наручные часы. В 1890 году мужчины носили исключительно карманные, а наручные вошли в моду только после Первой мировой.\\n\\nПодпись под фото — «С.-ПЕТЕРБУРГ, 1890». Но в дореформенной орфографии на конце слов, оканчивающихся на твёрдый согласный, обязательно ставился ъ. Правильно должно быть «С.-ПЕТЕРБУРГЪ».\\n\\nИ наконец, в 1890-м цветной фотографии в современном понимании ещё не существовало. Максимум — сепия.\\n\\nТаким образом, фотография была сделана специально, чтобы «легализовать» скрипку.\"},{\"id\":675,\"book\":\"seitim\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к тому, что рассказал второй задержанный о своём столике.\",\"Может ли столик на трёх ножках сильно шататься?\"],\"short\":\"Второй: его история про бумагу под ножкой стола — выдумка, ведь столики в «Эдельвейсе» стоят на трёх ножках и не шатаются.\",\"answer\":\"Гордеев задержал второго. Столы в «Эдельвейсе» стояли на трёх ножках, а такие столики не могут шататься. Значит, его история с «бумагой под ножку» была выдумкой, и именно он оказался вором.\"},{\"id\":676,\"book\":\"seitim\",\"lv\":3,\"pic\":true,\"ok\":0,\"hints\":[\"Подумай, каким кодом мог пользоваться бывший пилот, если он знал его лучше всего.\",\"Сидоров заменил точки и тире цифрами: какие из них обозначали точки, а какие тире?\"],\"short\":\"Котов: цифры на листке — азбука Морзе, где точки записаны нечётными цифрами, а тире — чётными; вышло «КОТОВ».\",\"answer\":\"Сейтимбетов рассудил просто: человек пользуется тем, что знает лучше всего. Сидоров был бывшим пилотом и отлично владел азбукой Морзе. Он заменил точки нечётными цифрами, а тире — чётными. Когда майор расшифровал запись, то получил фамилию убийцы: Котов.\"},{\"id\":677,\"book\":\"seitim\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Подумай, какие сведения о револьвере были известны только полиции и майору.\",\"Откуда Ахтамов знает, что калибр револьвера Басова был другим?\"],\"short\":\"Ахтамов: он знал калибр револьвера, которого никто не называл, а в тумане без фар не мог разглядеть цвет машины.\",\"answer\":\"Ахтамов не мог знать калибр оружия, из которого был убит Басов. Револьвер Сейтимбетов сразу убрал во внутренний карман — и детали о калибре никто не озвучивал.\\n\\nАхтамов уверял, что видел тёмно-синюю машину. Но в сумерках, да ещё в тумане и без фар, невозможно различить её цвет. Тем более, что он смотрел в тёмное окно из ярко освещённой комнаты.\"},{\"id\":678,\"book\":\"seitim\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись, что есть в квартире, а чего нет — особенно в ванной.\",\"Есть ли в ванной хоть что-нибудь из того, чем пользуется человек, который живёт там уже две недели?\"],\"short\":\"Квартиру подготовили к встрече: за «две недели» здесь нет ни зубной щётки, ни мыла, ни одной личной вещи.\",\"answer\":\"Женщина уверяла, что живёт здесь уже две недели, однако обстановка говорила об обратном. В квартире не было ни одной вещи, которая выдавала бы реальное проживание: на полках — пусто, в ванной ни зубной щётки, ни мыла, ни шампуня.\\n\\nВсё выглядело так, будто помещение подготовили специально к их приходу. Сейтимбетов сразу понял: эта квартира снята лишь для одной встречи — встречи с Куропаткиным. А вот кто и зачем всё это устроил, предстояло ещё выяснить.\"},{\"id\":679,\"book\":\"seitim\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к рукам погибшего — во что они одеты?\",\"Можно ли набрать номер на дисковом телефоне в таких перчатках?\"],\"short\":\"Звонок инсценирован: в лыжных перчатках нельзя набрать номер на диске, а трубку после звонка Карцев не мог аккуратно положить.\",\"answer\":\"Во-первых, Карцев был в лыжных перчатках — в таких невозможно набрать номер на дисковом телефоне.\\n\\nВо-вторых, после звонка он не мог аккуратно положить трубку на место. Значит, звонок и разговор — инсценировка, устроенная женой вместе с сообщником.\"},{\"id\":680,\"book\":\"seitim\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись, что именно лежит в корзине у крестьянок.\",\"Сравни даты: когда умер Дюрер и когда в Европе появился овощ из корзины?\"],\"short\":\"Гравюра не Дюрера: на ней картофель, а он появился в Европе уже после смерти Дюрера в 1528 году.\",\"answer\":\"На гравюре отчётливо изображены крестьянки с корзиной картофеля. Но Дюрер умер в 1528 году, а картофель появился в Европе только во второй половине XVI века и в Германии распространился ещё позже — фактически в XVII веке.\"},{\"id\":681,\"book\":\"seitim\",\"lv\":2,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к сейфу: что там лежит и что должно было бы оказаться в нём после выстрела?\",\"Куда, по логике, должна была улететь пуля, прошедшая через голову у открытого сейфа?\"],\"short\":\"Директор лжёт: пуля должна была застрять в сейфе, но там её нет — значит, стреляли в другом месте, не у сейфа.\",\"answer\":\"Директор утверждал, что стрелял в момент, когда «грабитель» стоял на четвереньках перед открытым сейфом. Пуля, по логике, должна была войти в затылок и остаться в сейфе.\\n\\nНо, осмотрев сейф, Сейтимбетов не нашёл в нём ни следа пули. Значит, стреляли вовсе не здесь — и вовсе не в момент «самообороны».\"},{\"id\":682,\"book\":\"seitim\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к тому, что Николай говорит о своём месте и о том, что видел.\",\"Может ли человек увидеть что-то в отражении, если стекло солнечным днём прозрачное?\"],\"short\":\"Николай лжёт: в солнечный день стекло прозрачное, поэтому в отражении он не мог увидеть, как Андрей прячет бутылку.\",\"answer\":\"Он утверждал, что сидел в кресле спиной к стойке и видел, как Андрей прячет бутылку — якобы в отражении в стекле. Но это невозможно: в солнечный день стекло работает как прозрачное, а не как зеркальное. В отражении он ничего разглядеть не мог.\"},{\"id\":683,\"book\":\"seitim\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к тому, что сосед рассказал о звуках в квартире.\",\"Мог ли глухой человек, которому ещё не сделали операцию, услышать будильник?\"],\"short\":\"Сосед Ибрагимов: он слышал звонок будильника, а глухой Смоляков-младший никогда бы его не завёл.\",\"answer\":\"Смоляков-младший был глухим. Ему предстояла операция по восстановлению слуха, но пока он физически не слышал звонков. Значит, он никогда бы не стал заводить будильник — в этом просто не было смысла.\\n\\nА вот сосед Ибрагимов, рассказывая следствию, что в девять утра услышал звонок будильника, сам себя выдал. Он не знал важной детали — глухоты погибшего. История с «будильником» оказалась лишь неудачной попыткой обмана.\"},{\"id\":684,\"book\":\"seitim\",\"lv\":1,\"pic\":false,\"ok\":0,\"hints\":[\"Представь, что серебро век пролежало в сыром тайнике: каким оно должно быть после этого?\",\"Может ли серебро, пролежавшее век в сыром тайнике, выглядеть так, будто его вчера отполировали?\"],\"short\":\"Подделка: серебро из сырого тайника давно бы потемнело, а этот канделябр сверкает, будто его вчера отполировали.\",\"answer\":\"Серебро, пролежавшее больше века в сыром тайнике, не может сверкать, как новое. Оно непременно окислилось бы, покрылось налётом, потемнело. А здесь «сокровище», якобы только что извлечённое из-под земли, сияло так, будто его вчера отполировали в мастерской.\"},{\"id\":685,\"book\":\"seitim\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к тому, что Штейн достал из багажа и что на экране выглядело обычным.\",\"Алмазы на рентгене плохо видны, особенно в жидкости. Что у Штейна было жидким?\"],\"short\":\"Алмазы были во флаконе спрея от горла: на рентгене их не видно, а майор понял, что жидкость в багаже — лишь спрей.\",\"answer\":\"— Видишь ли, Серёжа, — сказал Сейтимбетов, — с этим заводом я уже не раз сталкивался. Пришлось читать много спецлитературы. В одной из работ я узнал: алмазы на рентгене не видны, особенно если находятся в жидкости. А у Штейна был только один сосуд с жидкостью — его спрей. Так что, читайте, Серёжа, читайте…\"},{\"id\":686,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, что происходит с небом за час, если снимать его без перерыва.\",\"Земля вращается: за час звёзды смещаются на заметный угол. Что это значит для снимка?\"],\"short\":\"Чёткий снимок звёзд при часовой выдержке невозможен: вращение Земли смазало бы их, значит, Тим врёт про алиби.\",\"answer\":\"Тим Браун не мог сделать «чёткий снимок» Ковша Большой Медведицы при открытом в течение часа затворе. Из-за вращения Земли изображение звёзд было бы смазано.\"},{\"id\":687,\"book\":\"meridit\",\"lv\":3,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись, что в записке выглядит странно для маршрута по Европе.\",\"Названия городов в записке совпадают с названиями населённых пунктов в одном американском штате.\"],\"short\":\"Все города из записки — в штате Техас: Фредди летит туда, а не в Европу, и Дэйл полетит не туда.\",\"answer\":\"Тот факт, что Фредди указал пунктом назначения Палестину, а не Израиль, позволил Меридиту прийти к выводу о том, что Фредди запланировал трансконтинентальный полёт, а не трансатлантический. Новая широкополая шляпа точно пригодится ему в Техасе. Париж, Неаполь, Афины, Лондон, Палестина и Москва — это все города в американском штате Техас.\"},{\"id\":688,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, что сделал бы человек, который только что достал оружие, чтобы убить.\",\"Револьвер лежит на полу, а ящик стола закрыт. Кто его закрыл?\"],\"short\":\"Ри солгал: Стал не закрыл бы ящик, достав из него револьвер, а инспектор нашёл ящик закрытым — его закрыл Ри.\",\"answer\":\"Ри утверждал, что он ничего не трогал, а Стал «одним движением открыл верхний ящик стола, достал револьвер и выстрелил». Даже менее вспыльчивый человек никогда не стал бы закрывать ящик после того, как достал оттуда оружие с намерением убить кого-то. А инспектор обнаружил, что ящик стола закрыт.\"},{\"id\":689,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Посмотри внимательно на кофейник и на то, сколько воды в нём осталось.\",\"Сколько воды выкипит за час на огне? Сравни с тем, сколько её осталось в кофейнике.\"],\"short\":\"Кофе варили только что: за час вода выкипела бы ниже носика, значит, Фултон поставил кофейник перед побегом в лагерь.\",\"answer\":\"Если бы кофейник был поставлен на огонь прежде, чем два налётчика убили Свамма «час назад», как рассказывал Фултон, вода выкипела бы значительно ниже края носика кофейника.\\n\\nСледовательно, Фултон поставил кофейник на огонь непосредственно перед тем, как побежать в лагерь шерифа.\"},{\"id\":690,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Посмотри, кто из мужчин ревновал Марсию и что говорит о шляпе.\",\"Марсия выходила из дома без головного убора. Кто мог подбросить шляпу, чтобы подставить соперника?\"],\"short\":\"Билл Беттс подбросил шляпу Фоулеру: Марсия была без головного убора, а шляпы к вечернему платью не носят.\",\"answer\":\"Билла Беттса. Меридит догадался, что он подбросил шляпу в автомобиль своего конкурента и придумал эту историю.\\n\\nК сожалению для ревнивого Беттса, женщины не носят шляпы с вечерним платьем.\"},{\"id\":691,\"book\":\"seitim\",\"lv\":3,\"pic\":false,\"ok\":2,\"hints\":[\"Обрати внимание, из каких дров хозяин топит камин, и что он сам говорит о камнях.\",\"Сосна горит при 620 градусах, а алмазы — при 850 и выше. Что тогда станет с камнями в огне?\"],\"short\":\"Алмазы в тайнике полена: при сосновом огне (620 °C) они не сгорят, а Лебединский это знал и говорил иначе.\",\"answer\":\"Алмазы действительно горят и не оставляют после себя никаких следов. Температура, при которой алмаз сгорает на воздухе, составляет 850–1000 °C. Майор Сейтимбетов же обратил внимание на то, что Лебединский топил камин сосновыми дровами, а они горят при 620–630 градусах. То есть при такой температуре с ними ничего бы не случилось. И когда Лебединский сказал, что если бы он бросил в камин алмазы, то от них уже ничего не осталось, следователь понял, что алмазы там и находятся. Ведь хозяин дома очень хорошо разбирался в физических свойствах алмазов…\\n\\nСкорее всего, в одном из поленьев был оборудован тайничок, и когда полицейские обыскали камин, то Лебединский бросил это полено в камин и разжёг огонь. Он был уверен, что в камине больше никто искать не станет и алмазы спокойно будут покоиться под слоем золы.\"},{\"id\":692,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Обрати внимание, откуда Мимс знает, где лежит монета, и как лежит тело.\",\"Тело лежит лицом вниз. Может ли человек увидеть гвоздику в петлице, не переворачивая тело?\"],\"short\":\"Мимс сразу достал монету из гвоздики в петлице, хотя тело лежало лицом вниз и он не мог её видеть.\",\"answer\":\"Мимс доказал свою причастность к преступлению тем, что он достал монету из цветка гвоздики, который он не мог видеть, т. к. тело его дяди лежало лицом вниз на полу. Если бы он был не причастен к преступлению, то, когда Меридит сказал, что монета спрятана в гвоздике, он решил бы, что она находится в банке с сушёной гвоздикой, которая стояла на подносе со специями у него в руках.\"},{\"id\":693,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Обрати внимание на то, как именно Меридит открыл окно спальни.\",\"Французское окно на шарнирах: его поднимают или распахивают?\"],\"short\":\"Тэйлор солгал: французское окно на шарнирах не поднимают, а распахивают, значит, он не видел, как Годли его поднимал.\",\"answer\":\"Бен Тэйлор лгал, давая показания, что он видел, как Годли «поднял оконную раму» и выбросил свою жену.\\n\\nЭто было французское окно на шарнирах, которое Меридит открыл «распахивая».\"},{\"id\":694,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Посмотри, как менялся рисунок капель вдоль тропинки.\",\"Капли стали реже и длиннее в одной точке. Что могло заставить Эрнста резко побежать?\"],\"short\":\"Эрнст увидел убийство на полпути: дальше капли краски реже и длиннее, он побежал в мастерскую.\",\"answer\":\"Капли краски указали Меридиту на то, что Эрнст на полпути к мастерской увидел убийство. От этого места до мастерской, где запертый изнутри замок указывал, что он там спрятался, капли располагались на большем расстоянии друг от друга и были длиннее и уже, что показывало на то, что Эрнст внезапно быстро побежал.\"},{\"id\":695,\"book\":\"seitim\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись к столу в комнате фотографа: что там стоит и в каком виде?\",\"Сколько может пролежать лед в стакане с колой в теплой комнате, прежде чем растает?\"],\"short\":\"Фотограф Женя: в его номере стоит стакан колы с нерастаявшим льдом — значит, он там был недавно, а геометки подделаны.\",\"answer\":\"Кражу совершил фотограф. На столе в его номере стоял недопитый стакан с «Колой», в котором плавали кубики льда. Если бы он ушел с утра и только что вернулся, как утверждал, лед за несколько часов в теплой комнате давно бы растаял. А нетронутый лед доказывал, что он недавно был в номере — как раз в то время, когда была совершена кража. Его алиби с фотографиями было искусной подделкой — подменить метаданные в цифровом файле для человека с такой профессией не составляет большого труда. Его собственная небрежность и выдала его с головой.\"},{\"id\":696,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Подумай, каким должно быть окно комнаты, если на улице сильный ветер.\",\"Что станет со спичкой, если окно открыто, а ветер достигает сорока миль в час?\"],\"short\":\"Окно не могло быть открыто: при сорокамильном ветре спичка бы погасла, а закрытое стекло со вспышкой скрыло бы женщину.\",\"answer\":\"Окно на снимке было закрыто, иначе маленькая девочка не смогла бы держать зажженную спичку при ветре в «сорок миль в час». Поэтому тело женщины не могло быть видно на снимке. Фотоснимок был сделан с помощью вспышки поздно вечером. Оконное стекло, как зеркало, должно было отразить комнату, а все, что находилось за ним, было бы не видно.\"},{\"id\":697,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к тому, как муж описывает то, что случилось с женой.\",\"Как муж описывает смерть жены и что он видит перед собой, когда смотрит на пистолет?\"],\"short\":\"Муж Джон Пэйдж: он говорит, что жену «избили до смерти», хотя перед ним пистолет — он знал, что ее застрелили, и выдал себя.\",\"answer\":\"Если бы Джон Пэйдж был невиновен, он не знал бы, что его жену «избили до смерти». Видя оружие убийства, он должен был предположить, что ее застрелили.\"},{\"id\":699,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, кто был единственным свидетелем похищения и откуда он смотрел на двор.\",\"Как шар мог оказаться высоко на дубе в день, когда не было ветра?\"],\"short\":\"Сэм Паттс сам прицепил шар к дубу и втянул священника в выдуманную историю о похищении, которое будто бы видел.\",\"answer\":\"Меридит понял, что Сэм Паттс использовал невинного священника, чтобы подтвердить свой рассказ о похищении, которое якобы произошло у него на глазах. Паттс, вполне очевидно, сам прикрепил шар высоко на дубе в качестве доказательства. В безветренный день воздушный шар, наполненный воздухом из груди человека, никак не мог самостоятельно подняться высоко на дерево.\"},{\"id\":700,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к погоде, в которую разворачивалась эта история.\",\"Может ли знамя развеваться, если воздуха почти нет?\"],\"short\":\"В жаркий безветренный день знамя не могло развеваться, и Сирил не мог опознать американцев по нему.\",\"answer\":\"Так как это был «жаркий безветренный день», то полковое знамя не могло развеваться и, естественно, Сирил не мог его идентифицировать.\"},{\"id\":701,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Вспомни, что делал Вернер, когда на чердаке раздался звонок в дверь.\",\"Откуда Вернер мог знать, что звонят именно в заднюю дверь?\"],\"short\":\"Вернер бывал в доме: находясь на чердаке, он знал, что звонят в заднюю дверь, хотя утверждал, что никогда здесь не был.\",\"answer\":\"Хотя Вернер и пытался создать впечатление, что он никогда не был в этом доме, находясь на чердаке, он твердо знал, что звонят в заднюю дверь.\"},{\"id\":702,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, что могло случиться с водой в шланге, когда на нем стояла машина.\",\"Мог ли Мак-Генри, поливая сад почти полчаса, не заметить, что вода перестала течь?\"],\"short\":\"Олден не лгал: колеса фургона перекрыли шланг, и Мак-Генри, поливая сад, должен был заметить, что вода перестала течь.\",\"answer\":\"Потому что Олден сказал правду. Меридит пришел к выводу, что Мак-Генри, убивая свою жену, был удивлен прибытием доставщика заказов и поспешил на задний двор, чтобы придумать себе алиби с поливкой сада. Если бы он был там все время, он попытался бы разобраться в том, почему из шланга перестала течь вода. Ведь колеса грузовика перекрывали подачу воды в шланге в течение двух минут.\"},{\"id\":703,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Посмотри на одежду покойного и подумай, что он выбрал бы для вечернего свидания.\",\"Что надел бы эксперт по моде на свидание в 20:00 — и во что одет покойный?\"],\"short\":\"Клэнси убили: эксперт по моде не надел бы коричневый костюм и полосатую рубашку на вечернее свидание — так одел его убийца.\",\"answer\":\"Только человек, не разбирающийся в моде, одел бы коричневую обувь, коричневый костюм и полосатую рубашку для свидания в 20:00. После наступления темноты Клэнси, эксперт по моде, одел бы черную обувь, белую рубашку и темный костюм.\"},{\"id\":704,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Загляни в карманы: что в них лежит и мог ли Даффи туда дотянуться?\",\"Можно ли правой рукой, заключенной в гипс, залезть в свой правый карман?\"],\"short\":\"Убийца одел уже мертвого Даффи: его правая рука в гипсе не могла положить деньги в правый карман брюк.\",\"answer\":\"По содержимому правого кармана брюк Даффи Меридит понял, что Даффи сам не одевался. Правой рукой, заключенной в гипс «от кончиков пальцев до локтя», он не смог бы залезть в свой правый карман брюк, и тот был бы пуст, по крайней мере в нем не было бы денег.\"},{\"id\":705,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, что на самом деле видят собаки и какие цвета они различают.\",\"Могла ли собака отличить красное белье от других цветов?\"],\"short\":\"Собака не могла махать красным: собаки не различают красного цвета, а Сирил выдумал всю эту историю.\",\"answer\":\"Выдуманная Сирилом собака не могла знать, что дедушка махал красным флагом и что его белье было красного цвета. Собаки не различают красного цвета. Такая особенность собачьего зрения похожа на дальтонизм у людей.\"},{\"id\":706,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, что Ловелл мог увидеть из окна подвала, а что — только изнутри склада.\",\"Видны ли белые боковины шин, если их сложили в колонны высотой в три-четыре метра?\"],\"short\":\"Ловелл — убийца: он назвал марку шин «вайтволл», хотя из окна не видно белых боковин — значит, он был внутри склада.\",\"answer\":\"Ловелл сказал, что никогда не был прежде около склада. Но все же он знал, что шины, к которым тащили тело Капона, были марки «вайтволл». Но из окна он не мог видеть ничего, кроме протекторов шин, так как складские рабочие складывали их в «безупречно прямые колонны» высотой в 3–4 метра. И увидеть их белые боковины, по которым можно определить марку, было нельзя.\"},{\"id\":707,\"book\":\"seitim\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Посмотри на пол в детской: какие следы на нем остались и куда они ведут?\",\"Какие следы остались бы на присыпке у окна, если бы няня подбежала к нему?\"],\"short\":\"Няня лжёт: на присыпке остались только мужские следы, ведущие к окну, — значит, она не подбегала к нему, как говорила.\",\"answer\":\"Она утверждала, что бросилась к окну, когда похититель уже исчез. Но на полу, посыпанном белой присыпкой, остались только следы мужской обуви. Если бы Рената действительно подбежала к окну, её следы также были бы отчетливо видны.\"},{\"id\":708,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, каким воздухом дышал бы Джим через такую длинную трубку.\",\"Что вдохнул бы Джим через шестифутовую трубку: свежий воздух или то, что выдохнул сам?\"],\"short\":\"Через трубку Джим задохнулся бы собственным выдохом, а не утонул: значит, его убили.\",\"answer\":\"Дыша через трубку шести футов длиной и диаметром около двух сантиметров, Джим быстро потерял бы сознание. Он дышал бы тем же воздухом, которым выдыхал, — воздухом без кислорода. Этот простой медицинский факт доктор Хэллуэй, конечно, знал!\"},{\"id\":709,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к тому, из какого металла сделана статуэтка.\",\"Может ли бронза высекать искры, ударяясь о камни?\"],\"short\":\"Бронза не даёт искр при ударе о камни, значит, Эванс выдумал историю про искры, чтобы подставить Симмонса.\",\"answer\":\"Эванс утверждал, что «что-то», брошенное Симмонсом и оказавшееся бронзовой нимфой, при падении по скалистому склону выпускало искры, отмечая свой путь. Это невозможно: бронза — антифрикционный металл и не даёт искр при ударе.\"},{\"id\":710,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Обрати внимание, как Бартон говорит о докторе Уильямс.\",\"Какого пола доктор Уильямс и как Бартон её назвал?\"],\"short\":\"Бартон назвал доктора Уильямс «он», хотя она женщина: значит, он её знал и лжёт, что никогда о ней не слышал.\",\"answer\":\"Хотя Бартон утверждал, что никогда не слышал о докторе Эвелин Уильямс, он знал, что доктор был, во-первых, дантистом и, во-вторых, мужчиной.\"},{\"id\":711,\"book\":\"meridit\",\"lv\":3,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к тому, на чём, по словам Роуча, строила гнездо птица.\",\"Есть ли на пальме ветви, на которые может сесть и устроить гнездо птица?\"],\"short\":\"Роуч лжёт: на пальме не строят гнёзд, птицу с гнездом он видеть не мог, значит, выдумал свидетельство против де Мотта.\",\"answer\":\"Хотя Роуч и был опытным орнитологом, он плохо знал тропическую флору. Вполне очевидно, что он не мог наблюдать во Флориде птицу, строящую свое гнездо на пальме, как он утверждал. У пальм ствол не ветвится, а имеет длинные скользкие ветви, на которые птицы не могут взгромоздиться и строить гнездо, так как там мало места для него. Исключение составляют пальмовые стрижи и пальмовые грифы, но они живут в других частях света.\"},{\"id\":712,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, что происходит с человеком при резком ударе, если он не пристёгнут.\",\"Могла ли кровь пропитать всё сиденье, если водителя выбросило из машины?\"],\"short\":\"Кровь пропитала сиденье, а при аварии водителя выбросило бы наружу: значит, тело положили в машину уже мёртвым.\",\"answer\":\"Тот факт, что всё сиденье было пропитано кровью, указывает на то, что человек был убит, а его тело было помещено в автомобиль, который затем сбросили с горной дороги. Ведь при столкновении с преградой тело водителя было выброшено из автомобиля, и, естественно, крови на сиденье быть не должно.\"},{\"id\":713,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к окну Ника и тому, что из него видно, когда штора задёрнута.\",\"Мог ли Ник видеть двор через окно, закрытое шторой?\"],\"short\":\"Занавеска на окне Ника закрыта, поэтому драку он не видел: тело он нашёл по дороге домой и выдумал убийство ради денег.\",\"answer\":\"Инспектор догадался, что Ник обнаружил тело, идя домой, и придумал вымышленное убийство, чтобы заработать денег. Он не мог видеть из окна своей комнаты то, что описывал: ведь, если вы помните, окно было закрыто занавеской.\"},{\"id\":714,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к загару Вэнса на лице и на подбородке.\",\"Что осталось бы под густой бородой после семи месяцев на солнце?\"],\"short\":\"Вэнс лжёт о бороде: под семимесячной бородой кожа осталась бы светлой, а подбородок загорел, значит, бороды не было.\",\"answer\":\"Вэнс утверждает, что парикмахер только вчера сбрил у него семимесячную бороду. Но его щёки «загорелые», а подбородок «бронзовый». Если бы он действительно семь месяцев находился на солнце с бородой, кожа под ней осталась бы светлой.\"},{\"id\":715,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, что происходит с жидкостями при сильном морозе.\",\"Что замёрзнет и лопнет за пять дней мороза, если в бутылке простая вода с сахаром?\"],\"short\":\"Сахарная вода замёрзла бы и разорвала бутылки: эликсир был спиртным, и доктор поил индейцев опьяняющим зельем.\",\"answer\":\"После пяти дней на крепком морозе «сахарная вода» замерзла бы и разорвала бутылки. Следовательно, эликсир должен был содержать что-то с низкой точкой замерзания, например алкогольный напиток, который превращал индейцев в «сумасшедших пьяниц».\"},{\"id\":716,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Подумай, можно ли играть на виолончели в такой одежде, какая была на Фреде.\",\"Удобно ли сидеть с большим инструментом, если юбка узкая?\"],\"short\":\"Билл Сандерс: Фреда не собиралась играть, в узкой юбке с виолончелью не сыграешь, значит, он солгал о её планах.\",\"answer\":\"Фреда была одета в узкую юбку. Виолончелистка в такой юбке не смогла бы играть на инструменте, значит, на концерт она собиралась не играть. Билл Сандерс, уверявший, что она собиралась выступать и заедет за ним, солгал.\"},{\"id\":717,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Подумай, в каких условиях, по словам Берта, Морено рисовал свой портрет.\",\"Что происходит с чернилами, если несколько дней стоит сильный мороз?\"],\"short\":\"Чернила в морозной хижине замёрзли бы, и портрет нельзя было нарисовать: история Берта о последнем рисунке выдумана.\",\"answer\":\"Если погода в течение нескольких дней была морозной, то в покинутой хижине с разбитым окном чернила должны были замёрзнуть, и ими невозможно было бы рисовать.\"},{\"id\":718,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к тому, что парень предлагал шерифу и сколько времени он, по своим словам, ждал на жаре.\",\"Что стало бы с шоколадом за час на жаре в тридцать градусов?\"],\"short\":\"Шоколад не растаял: парень недавно был в машине, а на дороге его оставили сообщники, чтобы отвести погоню.\",\"answer\":\"Этот «попутчик» был одним из членов банды, оставленным на дороге специально, чтобы направить преследователей в другую сторону. Он уверял, что стоял на дороге больше часа. Если бы это было так, шоколад в такую жару растаял бы. Но шоколад был твёрдым: парень недавно был в машине.\"},{\"id\":719,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к тому, как выглядит кровь на лице и одежде Парида и какая была погода.\",\"Могла ли кровь стечь ровной линией по лицу во время бури с сильным ветром?\"],\"short\":\"Ветер размазал бы кровь по лицу и одежде, а она стекала ровной линией: Парида был убит не на скамье.\",\"answer\":\"Если бы Парида застрелился на скамье во время бури, кровь от раны не спускалась бы ровной линией по его лицу. Ветер размазал бы её по лицу и разбрызгал по одежде.\"},{\"id\":720,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к подаркам гостей и к тому, для какого вида спорта они нужны.\",\"Для чего нужны лыжные палки: для катания по снегу или по воде?\"],\"short\":\"Курт Гоуэн: подарок — лыжные палки, значит, он знал, что Кирк поедет на снежные лыжи, а не на водные.\",\"answer\":\"Курт Гоуэн. Его подарок, лыжные палки, показывал, что ему было известно: Кирк собрался кататься на лыжах по снегу. В то время как все остальные думали, что Кирк собрался кататься на водных лыжах где-то на юге.\"},{\"id\":721,\"book\":\"meridit\",\"lv\":3,\"pic\":false,\"ok\":1,\"hints\":[\"Подумай, что мешает услышать разговор в парикмахерской.\",\"Как можно понять чужой разговор, если ничего не слышишь?\"],\"short\":\"Одну из трёх новых клиенток, глухую: под фенами никто не слышит, а она могла читать по губам мистера Джона и Клары.\",\"answer\":\"Ни одна из этих трёх женщин, сидящих под фенами, вряд ли могла услышать, что мистер Джон сказал жене, так как фены слишком шумят. Поэтому Меридит решил, что это должна была быть одна из клиенток, глухая, которая могла читать по губам.\"},{\"id\":722,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к тому, что Ходер рассказывает о дне Молли перед гонкой.\",\"Может ли женщина, которая готовится к яхтенной гонке, в тот же день идти делать причёску?\"],\"short\":\"Эрик Ходер: он лжёт про парикмахера, ведь участница яхтенной гонки не стала бы делать причёску.\",\"answer\":\"Меридит понял, что лжет Ходер, говоря, что Молли собиралась пойти к парикмахеру. Ни одна женщина, которая собиралась принять участие в яхтенной гонке, не будет делать прическу.\"},{\"id\":723,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, как свидетель узнал то, что, по его словам, говорил Добейн.\",\"Может ли глухой человек отличить шёпот от громкой речи, глядя только на губы?\"],\"short\":\"Свидетель глухой: по губам нельзя понять, шепчет человек или говорит, а репутация Ника подмочена.\",\"answer\":\"Глухой человек не может по губам определить, шепчет кто-то или говорит, ведь в том и другом случае губы движутся одинаково, а силу звука человек определить не может. Этим и было вызвано недоверие инспектора Нику, и, добавив ко всему репутацию последнего, инспектор выставил его за дверь.\"},{\"id\":724,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Подумай, где должна была оказаться рука с револьвером после выстрела снизу вверх.\",\"Могла ли рука, которая стреляла снизу вверх, потом оказаться у затылка, если смерть была мгновенной?\"],\"short\":\"Это не самоубийство: при выстреле снизу вверх под сердце рука с револьвером не могла оказаться у затылка.\",\"answer\":\"Если бы Ван Свелт стрелял в себя снизу вверх, ниже сердца, то он должен был держать оружие возле своих коленей. Но так как смерть была «мгновенной», для человека с коротким телом было невозможно, чтобы рука с оружием после выстрела оказалась на столе возле головы.\"},{\"id\":725,\"book\":\"meridit\",\"lv\":1,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, в каких условиях стюард говорит, что заполнял декларации.\",\"Мог ли кто-то писать ровным почерком, когда самолёт так сильно трясёт?\"],\"short\":\"Стюард: во время сильной тряски он не смог бы заполнить декларации безупречным почерком, значит, лжёт.\",\"answer\":\"Стюарда. Он не мог во время сильной тряски заполнить декларации «безупречным» почерком.\"},{\"id\":726,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Посмотри внимательно на дату и на то, что написано на клинке.\",\"Могли ли однополчане через месяц после первого боя знать о втором сражении при Булл-Ране?\"],\"short\":\"На сабле написано «первое сражение»: через месяц после боя однополчане не могли знать о втором, случившемся через год.\",\"answer\":\"Т.к. второе сражение при Булл-Ране произошло через год после первого, однополчане «лейтенанта Макина» не могли знать через месяц после первого сражения о том, что будет второе сражение при Булл-Ране. Они написали бы на сабле «… в сражении при Булл-Ране», а не «… в первом сражении при Булл-Ране».\"},{\"id\":727,\"book\":\"meridit\",\"lv\":1,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к обуви, в которой был Роджер Пратт в момент нападения.\",\"Какую обувь завязывают на шнурки, а какую нет?\"],\"short\":\"Сиделка лжёт: Пратт не мог завязывать шнурки, ведь был в мокасинах. Значит, она замешана в убийстве.\",\"answer\":\"Утверждая, что погибший наклонился, чтобы завязать шнурки на туфлях, Берта Тоун лгала. Роджер Пратт был одет в мокасины — обувь, которую не завязывают на шнуровку. У неё не было причины лгать, если бы она не была замешана в преступлении.\"},{\"id\":728,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, что Мэгден сделал, когда вытащил предмет из углей, и что он знал об этих углях.\",\"Можно ли спокойно сунуть руку в угли, если они ещё горячие?\"],\"short\":\"Эд Мэгден: он знал, что угли остыли, и спокойно сунул в них руку. Так он подбросил серьгу, чтобы подставить Нору.\",\"answer\":\"Эду Мэгдену. Он ведь прибежал, как утверждает, только что, но знал, что угли уже остыли, и спокойно, без опаски, засунул в них руку. Меридит понял, что он подбросил серьгу, чтобы бросить подозрение на Нору.\"},{\"id\":729,\"book\":\"meridit\",\"lv\":3,\"pic\":false,\"ok\":0,\"hints\":[\"Посмотри, куда повёрнуто растение на каминной полке и куда оно обычно тянется к свету.\",\"Куда должны были повернуться листья за четыре дня, если их никто не трогал, и откуда в комнату падал солнечный свет?\"],\"short\":\"Кастерс соврал, что не входил: растение повёрнуто листьями к стене, хотя четыре дня его никто не трогал.\",\"answer\":\"Окно было заперто изнутри, а единственный ключ был у молодого человека. Следовательно, он был единственным, кто мог тайно открыть сейф с секретным кодом и при этом случайно развернуть растение листьями к стене. Ведь если бы куст никто не трогал четыре дня, то его листья должны были бы быть повёрнуты к освещённому солнцем окну.\"},{\"id\":730,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Вспомни, куда бросил взгляд Меридит и что сказал Тифф сразу после этого.\",\"Откуда Тифф мог знать, что алмаз нужно искать на улице, если никто ему не говорил о стреле?\"],\"short\":\"Тифф: он сразу предложил искать алмаз на улице, хотя о стреле ему никто не говорил, значит, он её и выпустил.\",\"answer\":\"Поскольку Меридит посмотрел на верх лестницы, то, если бы Тифф был не причастен к преступлению, он предложил бы искать алмаз наверху, а не на улице. Он ведь ничего не мог знать в этом случае о найденном луке.\"},{\"id\":731,\"book\":\"meridit\",\"lv\":1,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, откуда миссис Смит могла узнать, что именно снилось её мужу.\",\"Может ли кто-то узнать чужой сон, если человек умер во время этого сна?\"],\"short\":\"Миссис Смит лжёт: муж умер во сне, и она не могла знать, что ему снилось.\",\"answer\":\"Если офицер умер во сне, то жена никак не могла узнать, что ему снилось.\"},{\"id\":732,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Подумай, где фермер мог видеть машину Меридита и что он знал о ней.\",\"Мог ли фермер назвать точный размер покрышек, если машину Меридита он не видел?\"],\"short\":\"Фермер точно подобрал покрышки нужного размера, а видеть машину он мог, только будучи одним из грабителей.\",\"answer\":\"Если бы фермер не видел автомобиля Меридита, припаркованного ночью в миле от его дома, то он не смог бы точно заказать в сервисном центре автопокрышки нужного размера.\"},{\"id\":733,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Вспомни, как Стивен входил в комнату и что делал, пока в ней было темно.\",\"Мог ли Стивен в полной темноте узнать, что дядя лежит на полу, и не споткнуться о него?\"],\"short\":\"Стивен: в темноте он уверенно переступил через тело дяди, хотя не мог его видеть, значит, знал о нём заранее.\",\"answer\":\"Отходя от торшера, Стивен «переступил» через тело своего дяди. Значит, при движении к торшеру он должен был перешагивать через лежащее на полу тело. Но только человек, который заранее знал, что Филипп Бэйтс лежит на полу, мог не споткнуться об тело в темноте и перешагнуть через него.\"},{\"id\":734,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Подумай, что нужно, чтобы забрать письма из почтового ящика, и где в этой истории был нужный ключ.\",\"Может ли Мэри достать письма из запертого ящика, если ключа у неё нет?\"],\"short\":\"Мэри не виновата: ключ от ящика выслали по почте, и без него ящик не открыть.\",\"answer\":\"Хотя босс отправил ключ от почтового ящика по почте, Мэри не смогла его извлечь — ведь ящик был заперт.\"},{\"id\":735,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Посмотри, что Блайнд делал у окна, когда Квик вошёл в кабинет.\",\"Что сделал бы человек, который час сидит в кабинете, увидев, что через открытое окно натекает дождь?\"],\"short\":\"Блайнд лжёт: сидя час в кабинете, он давно закрыл бы окно, из которого натекла огромная лужа от дождя.\",\"answer\":\"Если бы он целый час сидел за столом, то давно бы закрыл окно, не дожидаясь, пока моросящий дождь нальёт лужу.\"},{\"id\":736,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Посмотри, сколько времени прошло между тем, как Мэнни оставил деньги в парке, и тем, как Кенни встретил его у дома.\",\"Мог ли Кенни, которого отпустили в десяти милях к югу, так быстро оказаться у дома дяди, если мотель, где его держали, на севере?\"],\"short\":\"Кенни: он слишком быстро оказался у дома дяди, а мотель, где его держали, в другой стороне. Похищение подстроено.\",\"answer\":\"Кенни не смог бы так быстро добраться до дома своего дяди, если бы похитители забрали деньги в десяти милях к югу от города, а затем, чтобы его выпустить, добирались бы до мотеля к северу от города. Кенни принимал участие в инсценировке похищения, чтобы получить дядины деньги.\"},{\"id\":737,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Посмотри, что нашли при обыске у каждого и чего среди этих вещей нет.\",\"У кого из двоих нет спичек, без которых в лесу не разжечь костёр на несколько дней?\"],\"short\":\"Джонс: в его вещах нет спичек, а без них на несколько дней в лес не отправляются — стоянка не его, он лжёт.\",\"answer\":\"Вряд ли кто-нибудь отправится в лес на несколько дней, не взяв с собой спичек.\"},{\"id\":738,\"book\":\"quick\",\"lv\":3,\"pic\":false,\"ok\":1,\"hints\":[\"Подумай, что Ральф и Бен говорили о выстрелах и о том, кто что знал об оружии.\",\"Сколько патронов в девятимиллиметровом автомате и мог ли Ральф, выждав шесть выстрелов, выходить на пристань?\"],\"short\":\"Бен Гувер: Ральф вышел после шести выстрелов, не зная, что 9-мм автомат даёт восемь. Владелец оружия знал бы это, значит, виноват Бен.\",\"answer\":\"Ральф заявил, что ждал шестой выстрел, но имеет довольно смутное представление о современном оружии, особенно о девятимиллиметровом. Чаще всего это автоматическое восьмизарядное оружие, так что Ральф поступил крайне глупо, выбежав на пристань сразу после шести выстрелов. Владелец оружия (т. е. убийца) знал бы об этом, так что Бен внушает больше подозрений.\"},{\"id\":739,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к листку и зубочистке на кухонном столе.\",\"Чем написана записка с требованием и как такой текст обычно проявляют?\"],\"short\":\"Записку написали лимонным соком: скрытый текст проявляется от нагрева, и спички нужны, чтобы прочесть послание.\",\"answer\":\"Самые простые и известные «невидимые» чернила — это лимонный сок. На столе лежит всё, что нужно для записки: бумага, сок, разбавленный водой, и зубочистка, которой она писалась. Подобная надпись проявляется при нагреве бумаги, лучше всего использовать утюг. Хотя, при некоторой осторожности, наверное, можно и спички.\"},{\"id\":740,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Вспомни, что Ларри рассказывал о револьвере, и подумай, как такой револьвер устроен.\",\"Есть ли предохранитель у револьвера, который держал в руках Ларри?\"],\"short\":\"Ларри: у револьверов нет предохранителя, поэтому его рассказ о забытом предохранителе — выдумка, и он знает, где деньги.\",\"answer\":\"Современные револьверы не имеют предохранителей, а это означает, что Ларри лжёт.\"},{\"id\":741,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, где стоял сторож и куда он смотрел, когда увидел машину.\",\"Откуда утром светит солнце и куда смотрел сторож, когда говорил о слепящем свете?\"],\"short\":\"Сторож лжёт: утреннее солнце на востоке, и оно не могло ослепить того, кто смотрел на запад.\",\"answer\":\"Конечно, если не учитывать, что сторож лжёт. Он утверждал, что солнце слепило ему глаза, но находился в западной части здания и смотрел на запад. Рано утром солнце низко над горизонтом на востоке, оно не могло слепить сторожу глаза!\"},{\"id\":742,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Сравни, что Тед и Джон сказали о ключах и о самом сейфе.\",\"Откуда Джон знает, что сейф открывается ключом, если в кабинет он никогда не заходил?\"],\"short\":\"Джон: он знает, что сейф открывается ключом, а не цифрами, значит, был в кабинете, хотя Тайт говорит иначе.\",\"answer\":\"Тед сказал, что не взламывал сейф, а Джон, похоже, знал, что сейф открыли ключом. Он сказал: «Я даже не знаю, с какого ключа надо снять копию, чтобы открыть сейф!» Если бы он не побывал в кабинете, то не знал бы, что сейф открывается ключом, а не комбинацией цифр. Джон явно хитрит!\"},{\"id\":743,\"book\":\"meridit\",\"lv\":3,\"pic\":false,\"ok\":2,\"hints\":[\"Прислушайся к тому, что якобы слышал свидетель в коридоре.\",\"Тикают ли электрические часы? Что именно слышал Бэн?\"],\"short\":\"Ошибка Ника: свидетель «слышал тиканье» электрического будильника, а такие часы не тикают — показания выдуманы.\",\"answer\":\"Ник слишком зациклился на будильнике, шнуром от которого задушили Баффало. Но, к сожалению для него, электрические часы не тикают.\"},{\"id\":744,\"book\":\"meridit\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Обрати внимание, на каком языке, по словам Ника, говорил умирающий старик.\",\"На каком языке говорят в Бразилии и на каком, по словам Ника, говорил старик?\"],\"short\":\"Ник выдумал историю и подкупил Педро: старик, «всю жизнь прожив в Бразилии», говорил бы по-португальски, а не по-испански.\",\"answer\":\"Ник «Нос» подкупил Педро, чтобы тот подтвердил его выдуманную историю. Умирающий старик, который «всю свою жизнь прожил в Бразилии», не стал бы говорить свои последние слова по-испански: в Бразилии говорят на португальском.\"},{\"id\":745,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Вспомни, что именно полицейский сказал Шону и что ответил сам Шон.\",\"Какой велосипед назвал Шон, хотя полицейский говорил только о краже велосипеда?\"],\"short\":\"Шон: полицейский сказал лишь «кто-то украл велосипед», а Шон сам назвал дорогой гоночный — значит, знал, какой украли.\",\"answer\":\"Шон знал, что украли гоночный велосипед, хотя никто ему об этом не говорил.\"},{\"id\":746,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Вспомни, какой свет был в гостиной, когда туда вошёл доктор Квик.\",\"Мог ли Чанг споткнуться о тело в темноте, если гостиную заливало солнце?\"],\"short\":\"Чанг лжёт: будто споткнулся о тело в темноте, но гостиная с утра залита солнцем, и видно всё.\",\"answer\":\"Чанг утверждал, что пробирался по дому в темноте, хотя солнце давно взошло и заливало комнату ярким светом.\"},{\"id\":747,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Обрати внимание на то, о чём Рэйнджер попросил в конце допроса.\",\"Куда Рэйнджер попросил отвезти его и мог ли он поехать туда, не побывав там раньше?\"],\"short\":\"Рэйнджер сам попросил отвезти его обратно в банк — значит, он там уже был, и маска не спасла.\",\"answer\":\"Рэйнджер сам попросил отвезти его обратно в банк. Обратно можно поехать только туда, где уже побывал.\"},{\"id\":748,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Вспомни, что дворецкий рассказал о двери, когда грабитель уходил.\",\"Как прохожий смог войти в дом, если грабитель запер дверь?\"],\"short\":\"Джонатан лжёт: грабитель запер дверь, и случайный прохожий не смог бы войти в дом и развязать дворецкого.\",\"answer\":\"Со слов дворецкого, грабитель запер дверь. Как же прохожий смог войти в дом, чтобы его освободить?\"},{\"id\":749,\"book\":\"quick\",\"lv\":3,\"pic\":false,\"ok\":3,\"hints\":[\"Обрати внимание, как каждый из троих стоял и куда смотрел.\",\"Кому было важнее всего держать всех в поле зрения и не подпускать никого за спину?\"],\"short\":\"Посетитель, который крутился у полок: грабитель не подпускает никого к себе за спину, когда делает вид, что всё в порядке.\",\"answer\":\"Появившись в магазине, доктор Квик понял, что грабитель не допустит, чтобы кто-нибудь находился у него за спиной, когда он будет делать вид, что всё в порядке.\"},{\"id\":750,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Вспомни, что слышали и видели все вокруг в ту ночь.\",\"Может ли человек спать, не слыша ни выстрелов, ни взрыва, ни сирен прямо у своего дома?\"],\"short\":\"Сосед лжёт: он будто спал и не слышал ни выстрелов, ни взрыва, ни сирен пяти машин прямо у его дома.\",\"answer\":\"Сосед утверждает, что спал, не обращая внимания на выстрелы, взрыв зажигательной бомбы и звуки сирен по меньшей мере пяти автомобилей, находившихся практически напротив его дома. Это прекрасный повод сомневаться в его словах.\"},{\"id\":751,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Посчитай, что было раньше: встряска или разбитые очки.\",\"Когда именно разбились очки: до встряски или после неё?\"],\"short\":\"Джастин лжёт: очки разбились уже после того, как грабитель тряхнул его, — вблизи он мог рассмотреть и описать грабителя.\",\"answer\":\"Джастин заявил, что грабитель подскочил к нему вплотную и как следует тряхнул. Но всё это произошло до того, как разбились очки Джастина! А значит, он мог как следует рассмотреть грабителя и описать его приметы.\"},{\"id\":752,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Вспомни, что именно Деннис говорил о Дэнни и о грабеже.\",\"Откуда Деннис знает про ограбление Дэнни, если, по его словам, ничего не знает?\"],\"short\":\"Деннис говорил, что ничего не знает об убийстве, но сам упомянул ограбление Дэнни — значит, он знает больше.\",\"answer\":\"Деннис говорил, что ничего не знает об убийстве, но сам упомянул ограбление Дэнни, хотя речь шла именно об убийстве. Значит, он знает больше, чем говорит.\"},{\"id\":753,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к тому, что Бобби говорит о своей руке и о том, в какой руке было оружие.\",\"Откуда Бобби мог знать, в какой руке был пистолет, если весь день сидел дома с телевизором?\"],\"short\":\"Бобби: он знал, что грабитель держал пистолет в правой руке, и выдал себя, назвав своё левшество как алиби.\",\"answer\":\"Ясно, что Бобби все хорошо продумал. Он заявил в полицию о пропаже собственного автомобиля, во время ограбления держал оружие в правой руке, а затем переложил в левую, думая, что его никто не видит. Потом он попытался использовать тот факт, что он левша, в качестве алиби, тем самым проявив осведомленность о том, что грабитель держал оружие в правой руке.\"},{\"id\":754,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, кто из продавцов знал о новой партии колец и в какое время ушёл домой.\",\"Кто уходил раньше и мог ли он знать о золоте, которое Леонард спрятал уже после его ухода?\"],\"short\":\"Марк: он ушёл раньше и не знал о новой партии золота, поэтому украл бриллианты и проглядел кольца.\",\"answer\":\"Если бы вором был Леонард, он забрал бы более ценные кольца. Марк проглядел их, потому что не знал, что магазин получил их.\"},{\"id\":755,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Посмотри, что стало со льдом в стаканах и сколько времени, по словам мужчины, прошло.\",\"За сколько времени растаял бы лёд в лимонаде, если стаканы стояли два часа?\"],\"short\":\"Мужчина, вызвавший полицию: лёд в лимонаде не растаял, значит, он лгал, что ушёл два часа назад.\",\"answer\":\"Доктор Квик заподозрил этого мужчину, потому что тот сказал, что он ушел два часа назад, а лед в лимонаде НЕ РАСТАЯЛ.\"},{\"id\":756,\"book\":\"quick\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись, кто из двоих парней спит спокойно и как он выглядит.\",\"Что беглец мог сделать со своей внешностью за день после побега?\"],\"short\":\"Парень без бороды: беглец за день после побега наверняка сбрил бороду, чтобы уничтожить главную примету.\",\"answer\":\"Побег был совершен накануне. Преступник наверняка побрился бы, чтобы уничтожить самую главную примету своей внешности.\"},{\"id\":757,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Вспомни, что Квик сказал о тех, кто спугнул грабителя, и как сам подозреваемый это назвал.\",\"Квик говорил о «двух ребятах». Какое слово подозреваемый произнёс сам?\"],\"short\":\"Подозреваемый: он назвал мальчиков братьями, хотя Квик говорил только о «двух ребятах», значит, он был там.\",\"answer\":\"Этот человек сказал, что мальчики были братьями, потому что видел их во время ограбления.\"},{\"id\":758,\"book\":\"quick\",\"lv\":3,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к тому, как именно записано имя в свидетельстве.\",\"Как на самом деле звали Марка Твена при рождении?\"],\"short\":\"Свидетельство было фальшивкой: «Марк Твен» — псевдоним Сэмюэла Клеменса, в метрике такого имени быть не могло.\",\"answer\":\"Доктор Квик знал, что если в коллекции и было свидетельство о рождении Марка Твена, то оно было ничего не стоящей фальшивкой: Марк Твен — это псевдоним Сэмюэла Клеменса.\"},{\"id\":759,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Подумай, как служанка ориентировалась в доме, когда, по её словам, ничего не видела.\",\"Сможет ли человек, который ничего не видит, так уверенно ходить по тёмному дому?\"],\"short\":\"Служанка: она ловко ориентировалась в тёмном доме, значит, могла набрать номер, и она сообщница вора.\",\"answer\":\"Доктор Квик считает, что служанка является сообщницей грабителя и что она говорит неправду. Человек, способный так хорошо ориентироваться в темном доме, без труда смог бы набрать на телефонном диске заветный номер — 911.\"},{\"id\":760,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Посмотри, что продавец говорит о руке грабителя и о том, сколько он унёс.\",\"Может ли человек с рукой в кармане нести два тяжёлых ящика и открывать дверь?\"],\"short\":\"Продавец: вор с рукой в кармане не мог унести два тяжёлых ящика — значит, всё подстроил сам продавец.\",\"answer\":\"Он имел в виду, что продавец попадет в тюрьму. Скорее всего, продавец лгал, когда утверждал, что не мог воспользоваться оружием и выстрелить в вора. Интересно, как бандит мог нести два тяжелых ящика и повернуть дверную ручку, не вынимая руку из кармана?\"},{\"id\":761,\"book\":\"borg\",\"lv\":3,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись к цвету лица каждого из четверых и к тому, кто был в кабинете дантиста.\",\"Может ли лицо быть бледным сразу после парилки?\"],\"short\":\"Бледнолицый горбоносый: единственный в сауне был в кроссовках, а после парилки лицо не бывает бледным.\",\"answer\":\"— Откуда вы могли знать, что доктор Менгель — дантист?\\n\\n— О, какой же я болван! — с досады бледнолицый даже стукнул себя по лбу. — Попасться на такой мелочи. Да, — добавил он со вздохом, — я отомстил садисту Менгелю.\\n\\n— Но за что? — одновременно спросили Борг и Глум.\\n\\n— Я почти час терпел издевательства Менгеля над одним зубом. Но когда он, покончив с ним и перейдя к другому, вырвал мне по ошибке не тот зуб, я уже не выдержал.\\n\\n— Кажется, я его понимаю, — сочувственно произнес Глум и повернулся к Боргу. — А как вы вычислили его в сауне?\\n\\n— Это было очень просто. После парилки лицо не может быть бледным. Вы ведь тоже заметили этот нюанс с цветом лица?\\n\\n— Да нет, — усмехнулся сержант, — бедняга единственный, кто сидел в кроссовках, все остальные были босыми.\"},{\"id\":762,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Посмотри, что именно украли и что оставили нетронутым на складе.\",\"Зачем вору брать двести долларов и бумаги, если рядом стоят телевизоры стоимостью в тысячи?\"],\"short\":\"Такер: он инсценировал кражу, чтобы спрятать документы; воры взяли бумаги и двести долларов, телевизоры оставили.\",\"answer\":\"Такер утверждал, что его офис ограбили, хотя никак не мог об этом знать. Он знал только, что сработала сигнализация. Очень подозрительно также, что воры польстились на двести долларов и какие-то документы, когда рядом стояли телевизоры стоимостью в несколько тысяч долларов. Такер захотел спрятать документы, и он инсценировал кражу.\"},{\"id\":763,\"book\":\"borg\",\"lv\":3,\"pic\":true,\"ok\":1,\"hints\":[\"Посмотри на фото: что соединено проводами и как стоит будильник?\",\"Соединён ли будильник с бомбой и что означает имя «Геба»?\"],\"short\":\"Провода бомбы не соединены с будильником, а «Геба» — богиня юности: заложник сам из ООУЗ, а не жертва.\",\"answer\":\"— Как это?! — опешил Глум и машинально плюхнулся в кресло. — Я ничего не понял.\\n\\n— Да все очень просто. Обратите внимание, провода от бомбы не соединены с часовым механизмом. Так что бомба не взорвется.\\n\\nГлум тут же склонился над фотографией и стал водить пальцем по проводам.\\n\\n— Точно! — подпрыгнул он от восхищения. — И как это вы сразу заметили?\\n\\n— Но это еще не все, — спокойно продолжал Борг. — Пока вы бегали за конвертом, я вспомнил, что Геба — это богиня вечной юности у древних греков. Ясно, что похоронное бюро с таким кощунственным названием не может процветать. Поэтому я понял, что заложник — один из террористов.\\n\\n— Здорово! — снова восхитился Глум, собираясь еще что-то спросить.\\n\\nНо тут опять зазвонил телефон.\\n\\n— Дайте я, — опережая инспектора, Глум бросился к аппарату.\\n\\n— Ну что, ученая клизма! — без церемоний прокричал он в трубку. — Мы тебя раскусили. Тебя и твоего дружка-заложника. Можете взрывать друг друга сколько угодно. Чтоб вас обоих разорвало! — не удержался напоследок Глум и с торжествующим видом бросил трубку на рычаг. — Кстати, инспектор, уже без пяти двенадцать. Не пора ли нам доставать шампанское?\\n\\n— Самое время, — заулыбался Борг, открывая холодильник. — Да, я забыл у вас спросить, за что арестовали этого самого Ры Сигея.\\n\\n— Он выпустил бегемота из клетки в нашем зоопарке…\"},{\"id\":764,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к молодому человеку у автомата: зачем ему столько монеток на один разговор?\",\"Куда могут деться монеты, которые вор опускает в аппарат, и кто их потом найдет?\"],\"short\":\"Вор прятал украденные монеты в телефонном аппарате: нарочно опускал их в автомат, избавляясь от улик.\",\"answer\":\"Молодой человек двадцать минут разговаривал по местному телефону. Когда доктор Квик и Джуниор вошли, они поняли, что он бросал в автомат дополнительные монетки, когда надо и не надо. Значит, он избавлялся от улик. Доктор Квик был уверен, что, когда представитель телефонной компании вскроет телефонный аппарат, он найдет там пропавшие монеты из коллекции.\"},{\"id\":765,\"book\":\"borg\",\"lv\":3,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к колоде: Борг заметил, что карт в ней меньше, чем обычно.\",\"Что меняется в карте, если ее обойти вокруг стола, перевернуть и потом перетасовать колоду?\"],\"short\":\"Шулер выкинул симметричные карты, остальные заранее сориентировал, и по развороту нужной карты он её определил.\",\"answer\":\"Ваш ловкий обидчик использовал лишь часть карт из обычной колоды.\\n\\n— Да, я тоже заметил, что стопка карт была тоньше обычной раза в два, но не понял почему, — вставил Босси, внимательно слушавший Борга.\\n\\n— Все очень просто. Он выкинул из колоды полностью симметричные карты и оставил лишь те, которые можно как-то ориентировать.\\n\\n— Что, что? — не понял Глум.\\n\\n— Отремонтировать?!\\n\\n— Да нет, — расстроился Борг, — ориентировать. Я имею в виду, что некоторые карты в колоде можно повернуть так, что большая часть пик, треф или червей на них будет смотреть в одну и ту же сторону.\\n\\nНапример, можно повернуть семерку пик так, что пять из семи пик, нарисованных на этой карте, будут смотреть, скажем, от нас, а остальные две — к нам.\\n\\nТак вот, мошенник заранее сориентировал эти карты так, что все они «смотрели» в одну сторону. Выбрав какую-то карту и обойдя вокруг стола, вы изменили ее ориентацию на противоположную. Тасовка уже ничего не меняла. Ему оставалось только определить карту, изменившую ориентацию.\\n\\n— Ловко придумано! — восхитился комиссар Босси.\\n\\n— А я ничего не понял! — раздраженно проворчал Глум.\\n\\n— Давайте я вам покажу на практике, — оживился инспектор, повернувшись к столику.\\n\\nНо ни столика, ни его долговязого владельца уже не было.\\n\\n— Да, он действительно ловкий парень, — засмеялся Борг.\\n\\n— Но ничего, сержант, у меня в управлении как раз есть колода. Пойдемте, я покажу вам, как это делается. В конце концов, сорок доблей — это не так уж и много.\\n\\nИ он весело подмигнул побагровевшему от досады Глуму.\"},{\"id\":766,\"book\":\"borg\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к бокалу с мартини и к кубику льда, которым охранник прикладывал глаз.\",\"Сколько времени нужно, чтобы растаял лед в мартини, и мог ли он лежать там целый час?\"],\"short\":\"Охранник врёт о времени: лёд в мартини за час растаял бы, значит, он сочинил легенду о нападении.\",\"answer\":\"— Это кто негодяй?! — завопил Шепелявичус.\\n\\n— Я пострадал при исполнении, и вы не имеете права меня оскорблять! На каком основании вы меня обвиняете?..\\n\\n— Вы очень плохо подготовились к преступлению и сочинили легенду, которая не выдерживает критики. За час лед в бокале с мартини должен был давно растаять.\"},{\"id\":767,\"book\":\"borg\",\"lv\":3,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к буквам сообщения: похоже ли оно на английский текст?\",\"Что выйдет, если набрать русское слово на английской раскладке клавиатуры?\"],\"short\":\"Шифр — русский текст, набранный на английской раскладке клавиатуры: Борг прочел буквы по тем же клавишам.\",\"answer\":\"За минуту до встречи он уже подходил к памятнику Казанове. Кроме стоящей к нему спиной пухлой женской фигуры в красном плаще, там никого не было.\\n\\n— Математильда? — почему-то шепотом робко произнес он в спину неизвестной.\\n\\n— Попался, голубчик! — зловеще проскрипела фигура и резко обернулась. Вместо обаятельной интеллектуалки с томиком Борхеса, прижатым к груди, прямо перед напуганным инспектором стояла… разгневанная Матильда с половником в руке.\\n\\n— А-а, это вы, инспектор, — разочарованно протянула она.\\n\\n— А где же мой маньяк?\\n\\n— М-маньяк не п-пришел, — чуть заикаясь, глупо брякнул Борг, опасливо косясь на половник.\\n\\n— Жаль, — расстроилась Матильда, убирая в сумочку орудие мести.\\n\\n— Он и не думал идти на встречу, потому что сразу догадался, что Математильда — это вы.\\n\\nПриободрившись, инспектор стал спасать горе-напарника.\\n\\n— А меня попросил завернуть сюда по дороге, чтобы сообщить вам об этом. Сам-то он очень занят на службе. А еще, говорит, — все более вдохновляясь, продолжал врать Борг, — передайте ей, что она просто умница. Надо же — написать послание английскими буквами, стоящими на тех же клавишах, что и русские!\\n\\n— Да. «Сегодня. 17-00. У памятника Казанове. Красный плащ», — процитировала довольная собой Матильда и машинально поправила прическу.\\n\\n— Лучше моей Матильды не сыскать — вот что он сказал мне напоследок.\\n\\nБорг был тоже доволен собой и вовсю улыбался.\\n\\n— Он так и сказал? — просияла Матильда.\\n\\n— Слово мужчины! — поклялся инспектор.\\n\\n— Ну ладно.\\n\\nОна вдруг заторопилась домой.\\n\\n— Пойду, приготовлю моему сержантику пироги с капустой. Он их так любит.\\n\\nИ Математильда, она же Матильда, бодро зацокала каблучками прочь от инспектора, съежившегося под насмешливым взглядом каменного Казановы.\"},{\"id\":768,\"book\":\"quick\",\"lv\":1,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к входной двери и к тому, чем она заперта.\",\"Можно ли открыть дверь электронной картой, если её заперли на засов?\"],\"short\":\"Макс лжёт: дверь заперта засовом, электронной картой её не открыть. Ограбления не было, он хотел получить страховку.\",\"answer\":\"Нельзя открыть дверь с помощью электронной карты, если она запирается на засов.\"},{\"id\":769,\"book\":\"borg\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к кровати и к тому, какой она выглядит для дома, где давно никто не жил.\",\"Может ли покрывало оставаться белым несколько месяцев и что сделал комар перед тем, как его прихлопнули?\"],\"short\":\"Угорь в домике: белое покрывало не осталось бы таким за несколько месяцев без людей, а комар только что напился крови.\",\"answer\":\"За несколько месяцев покрывало на кровати покрылось бы пылью и не могло остаться белоснежным. Кроме того, убитый вами комар только что напился крови, что также говорит о присутствии в доме человека.\"},{\"id\":770,\"book\":\"borg\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к словам «искусствоведа» о картине.\",\"Акварель никогда не пишут на холсте, а «искусствовед» назвал картину именно холстом.\"],\"short\":\"«Искусствовед» назвал акварель холстом: акварель пишут на бумаге, значит, он в сговоре с художником.\",\"answer\":\"— С чего вы взяли? — сразу насторожился сержант, зная, что Борг редко ошибается.\\n— Вроде бы все без обмана.\\n— На взгляд дилетанта. Но даже самый дремучий искусствовед знает, что акварельные рисунки делаются на специальной бумаге, и никогда не назовет акварель холстом.\\n— Да? А я и не знал ничего такого, — расстроился Глум.\\n— Ничего страшного, в полицейских академиях такого не проходят, — успокоил его инспектор и тут же предложил: — Ну что, посмотрим другие картины?\\n— Нет уж! — отрезал Глум, в последний раз оглянувшись на соблазнительную купальщицу.\\n— Хватит с меня искусства. Лучше уж я куплю Матильде горные лыжи.\\nИ он решительно зашагал к выходу из парка.\"},{\"id\":771,\"book\":\"borg\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к тому, что есть в каморке Штампа: стол, огарок, листы и ничего больше.\",\"Что будет с бумажным кулечком, если налить в него воду и поставить над огнем?\"],\"short\":\"Штамп вскипятил воду в бумажном кулечке над свечой: бумага не горит, пока в ней есть вода.\",\"answer\":\"Он запросто мог вскипятить воду и без чайника, в бумажном кулечке. Бумага при этом не загорается, но не потому, что «рукописи не горят», а в полном соответствии с законами физики. Можете сами это проверить, сержант.\"},{\"id\":772,\"book\":\"borg\",\"lv\":1,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к тому, как стоит цветок на подоконнике и куда он смотрит.\",\"Цветы тянутся к свету: в какую сторону должна смотреть роза на подоконнике?\"],\"short\":\"Роза на подоконнике повернута к двери, а не к солнцу: кто-то переставлял ее и рылся в записях.\",\"answer\":\"— Что еще за деталь? — Глум был явно обескуражен.\\n— Посмотрите на вашу розу. Она только недавно раскрылась, цветок повернут не к солнцу, как должно быть, а к двери. Это значит, что кто-то переставлял его для того, чтобы порыться в моих записях, а потом аккуратно поставил обратно, но в спешке повернул другой стороной.\\nНу а кто это мог сделать, я уже сказал.\"},{\"id\":773,\"book\":\"borg\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к тому, где именно лежала газета и как быстро Меер ее нашел.\",\"Меер приехал только что с вокзала, но без запинки пошел в спальню за газетой. Откуда он знал, где она?\"],\"short\":\"Меер за минуту нашел газету, которая лежала под телом жены, — значит, он знал, где ее искать, и был в квартире.\",\"answer\":\"Библия была под телом вашей жены, и вы это прекрасно знали, потому что иначе за минуту найти газету не смогли бы.\"},{\"id\":774,\"book\":\"borg\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к концовке истории Глума: откуда рассказчик узнал, что снилось Чанку?\",\"Чанк умер во сне. Кто мог рассказать, что ему тогда снилось?\"],\"short\":\"Чанк умер во сне, и никто не мог знать, что ему снилось: история Глума про сон выдумана.\",\"answer\":\"— Да, — выслушав эту мрачную историю, снова повторил инспектор, — старина Лайерс и впрямь был очень колоритной фигурой, вот только один недостаток...\\n— Да что вы заладили про этот недостаток? — не выдержал Глум. — Что вы имеете в виду?\\n— Ничего особенного. — Борг вовсю улыбался. — Просто сержант Лайерс очень любил приврать.\\n— С чего вы взяли? — не унимался Глум.\\n— Подумайте сами. Если Чанк действительно умер во сне, то откуда же было известно, что ему снилось.\\n— А ведь верно. — Глум восхищенно щелкнул пальцами. — Как я сам не догадался! Ну и дока же вы, инспектор! Хотя, постойте, постойте... — сержант подозрительно посмотрел на напарника. — А как же тогда быть с вашей историей?! Откуда вы могли узнать про тень и так далее? И, кстати, от кого вы все это услышали?\\n— Сержант Глум, — строго кашлянув, инспектор попытался скрыть смущение, — вы совсем забыли про нашу работу!\\nИ, прикрывшись газетой, инспектор Борг стал пристально вглядываться в старинное здание на другой стороне улицы.\"},{\"id\":775,\"book\":\"borg\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Внимательно перечитай надпись на золотом оружии прадеда жениха.\",\"В каком году началась первая мировая и успели ли её так назвать к 1916-му?\"],\"short\":\"Надпись на «золотом оружии» датирована 1916 годом, а тогда войну еще не называли первой мировой.\",\"answer\":\"— Даже не очень достойный молодой человек, — откликнулся инспектор, — должен знать, что в 1916 году война еще не могла называться первой мировой.\"},{\"id\":776,\"book\":\"borg\",\"lv\":3,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к тому, что на самом деле значат стихи Лукофация.\",\"Разбери первые слова стихов «Чимол, чимол»: сержант уже прочитал их как «МОЛЧИ».\"],\"short\":\"Лукофаций в сговоре с Профессором: его заумные стихи — шифровка «Молчи! Тогда тебя вызволят!»\",\"answer\":\"— Я вас не понимаю, — растерянно пробормотал сразу побледневший поэт и в сильном волнении плюхнулся на заботливо подставленный Глумом табурет.\\n\\n— Все очень просто, — улыбнулся Борг.\\n\\n— Вам, конечно, известен художественный салон «Подвал №(-1)», который организовал художник и меценат Са Шабел. Однажды я случайно заглянул туда и услышал выступление еще более безум… простите, еще более авангардного поэта. Кажется, его звали Герси де Фейн. Так вот, мне запомнилось, как этот самый де Фейн читал свой заумный «озарень»:\\n\\nОЗАГР ЛЕННО МЕД КОЯБЛО ДАЕТ ПА…\\n\\nПотом оказалось, что каждое слово в этой загадочной фразе получается из обычных слов путем многократного повторения. Например, ГРОЗАГРОЗА… ОЗАГР, ЛЕННОМЕДЛЕННОМЕД… МЕДЛЕННО и так далее. Поэтому абракадабра означала всего лишь: «Гроза. Медленно падает яблоко…»\\n\\nКогда я услышал ваше приветствие, то вспомнил этот прием и попытался применить его здесь. И у меня получилось…\\n\\n— Постойте, постойте! — оживился Глум, задремавший было в начале лекции о поэзии. — Дайте я сам попробую. ЧИМОЛЧИМОЛ…\\n\\n— Получается «МОЛЧИ»! Здорово! — поразился он.\\n\\n— А что там было дальше?\\n\\n— «Молчи! Тогда тебя вызволят!» — неожиданно признался Лукофаций и сокрушенно добавил: — Никогда бы не подумал, что в нашей полиции есть любители современной поэзии.\\n\\n— Ничего, теперь они будут и среди наших заключенных, — весело сказал сержант Глум, доставая наручники.\"},{\"id\":777,\"book\":\"borg\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Подумай, что сержант не сможет открыть, пока не найдет ключ, и где этот ключ может оказаться.\",\"Посмотри, что может висеть на дужке замка второго, почти пустого ящика.\"],\"short\":\"Вторая посылка пуста, зато с ключом на дужке замка: им сержант откроет первую посылку с подарком\",\"answer\":\"Сержант узнал только в день своего рождения.\\n\\nРовно за день до юбилея недовольный хогобогский почтальон вручил Глуму небольшой металлический ящик, закрытый на внушительный амбарный замок.\\n\\n— Инспектор так ничего и не понял! — в сердцах выругался Глум. — Ключа-то от этого замка у меня нет. Придется тащить этот маленький гроб обратно.\\n\\nОднако до этого не дошло. На следующий день еще более мрачный почтальон передал сержанту точно такой же ящик с замком. Впрочем, было и отличие. Судя по всему, ящик был пуст, однако на дужку замка был надет большой ключ с причудливой бородкой.\\n\\nДаже такой тугодум, как Глум, догадался, что это ключ и от первого замка. Сгорая от нетерпения, сержант с трудом вставил ключ в замок.\\n\\nНа дне первой посылки он нашел роскошно изданный том популярной серии «Библиотека сержанта».\\n\\nЗолотыми буквами на обложке было вытиснено название «3000 задач на смекалку для начинающих»…\"},{\"id\":778,\"book\":\"borg\",\"lv\":3,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к внешности доктора на рекламе и к тому, что Борг сказал о его прическе.\",\"Какая шевелюра у доктора на фото и что может прятаться под ней?\"],\"short\":\"Обмишулер сам лыс и носит парик: снимет его — и волосы клиента тоже будут «не хуже, чем у него»\",\"answer\":\"Он так и не понял, что на голове у Обмишулера парик, под которым скрывается лысина. Сняв парик, этот жулик действительно выполнит условие договора: волосы клиента, какими бы жидкими они ни были, все равно окажутся не хуже, чем у него.\"},{\"id\":779,\"book\":\"borg\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись, что маг делает с каждой запиской сразу после того, как «прочитал» ее пальцами.\",\"Зачем маг каждый раз разворачивает записку и смотрит в нее глазами?\"],\"short\":\"Маг жульничает: разворачивая записки, он тайно читает их, а блондинка-сообщница «признаётся» в нужной\",\"answer\":\"— Мне пока ничего не ясно, — проворчал Глум, инстинктивно дотронувшись до кармана с бумажником.\\n\\n— При чем тут то, что он читал записки и глазами? Ведь это было после чтения пальцами.\\n\\n— В том-то и дело, что нет. Ощупывая первую записку пальцами, он сделал вид, что прочитал ее, а на самом деле произнес заранее подготовленную фразу: «Я не верю в эту чепуху!»\\n\\nСоучастница мага, та самая блондинка, «призналась», что она написала эту фразу. Тогда маг, якобы желая лично убедиться в правильности «прочтения» пальцами, достал записку, якобы написанную блондинкой. А на самом деле это была ваша записка! Он про себя прочитал ее и запомнил. Затем, нащупав в мешке следующую записку, произнес вслух вашу фразу про блондинок и снова, как бы желая убедиться в правильности своего «прочтения», развернул и прочитал ее про себя. Ну и так далее. Последней он достал особо помеченную (например, согнутую пополам) записку блондинки.\\n\\n— Да, хитро придумано, — согласился Глум. — Но я поверю в эту версию, только если смогу убедиться, что красотка играет в одной команде с фиктивным магом.\\n\\n— А вы посмотрите туда, — с усмешкой посоветовал инспектор, указывая на полуприкрытый вход в шатер.\\n\\nВ глубине помещения Глум отчетливо увидел мага, обсуждающего что-то с блондинкой. Даже с такого расстояния сержанту было понятно: они хорошо знакомы.\\n\\n— Эх, — сокрушенно вздохнул Глум, доставая из бумажника проигранные деньги, — никогда больше не буду верить ни чудесам, ни женщинам.\"},{\"id\":780,\"book\":\"borg\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Перечитай письмо внимательнее: обрати внимание на числа и на знаки препинания.\",\"Одного знака препинания не хватает в одном месте письма — после какого слова?\"],\"short\":\"Солитерций не псих, а неграмотный: без двоеточия после «двадцать» письмо читается как про сороконожку\",\"answer\":\"Бедняга, по-видимому, просто не шибко грамотен. Если бы он поставил двоеточие после слова «двадцать», фраза была бы вполне нормальной.\"},{\"id\":781,\"book\":\"quick\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к тому, что миссис Рейтер достала из сумочки и как пришла собака.\",\"С чем собака пришла к жене и откуда миссис Рейтер достала поводок?\"],\"short\":\"Собака пришла без поводка, а поводок был в сумочке: муж с ней в парке не гулял, жена лжет ради страховки\",\"answer\":\"Если бы мистер Рейтер выгуливал собаку в парке, к ее ошейнику был бы пристегнут поводок. Совершенно ясно, что миссис Рейтер беспокоилась из-за увольнения мужа и возможного развода и решила получить его страховку.\"},{\"id\":782,\"book\":\"borg\",\"lv\":3,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к рисунку: как связаны слова верхней строки с нижней?\",\"Под каждым словом верхней строки стоит слово нижней из того же числа знаков: это две половинки одной фразы.\"],\"short\":\"«Побег в среду»: две строчки записки — половинки одной фразы, если прочесть их вместе.\",\"answer\":\"— Инспектор, — ухмыльнулся Глум, — не хотите ли вы сказать, что смогли утереть нос ребятам из шифровального отдела?\\n— Именно это я и хочу сказать.\\n\\n— Смотрите! — Борг положил записку на стол. — Специалисты из контрразведки полагают, что здесь две строчки зашифрованных букв. Я же сразу заметил, что под каждым «словом» первой строки стоит «слово» второй строки из того же числа знаков.\\n\\nТогда мне пришла в голову мысль, что на самом деле перед нами не разные зашифрованные слова, а половинки одного и того же.\\n\\nОсталось мысленно соединить обе строчки и получить ответ: «Побег в среду». Вот, полюбуйтесь!\\n\\nСержант и девушка склонились над столом. Инспектор, несомненно, был прав.\\n\\n— Вы — гений! — выдохнула Лиана, с обожанием глядя на инспектора и кокетливо поправляя прическу. — Я и не знала, что у нас в управлении работают такие мужчины!\\n— Я всегда говорил, — вздохнул Глум, отрываясь от записки, — что инспектору платят слишком мало. Впрочем, и мне тоже, — добавил он.\"},{\"id\":783,\"book\":\"borg\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись, какой рукой официант несёт поднос и какой расставляет приборы.\",\"Удар пришёлся в правый висок пострадавшего. Какой рукой нужно бить, чтобы попасть именно туда?\"],\"short\":\"Астэр левша: поднос он несёт правой, приборы ставит левой, а удар пришёлся в правый висок, его мог нанести только правша.\",\"answer\":\"— Я безумно рад это слышать, — взвизгнул Гурманоид, — но хотел бы знать, почему вы так решили и, главное, кто же все-таки обработал и меня, и мой сейф.\\n— Астэр нес поднос на правой руке, а приборы расставлял левой, и, следовательно, он левша, — терпеливо сказал Борг.\\n— А вы, Бэн, протянули для рукопожатия правую руку, отняв ее от шишки на голове. Но сильный удар сзади по правому виску мог нанести только правша. Сержант! Приведите-ка сюда этого… Бандероса!\"},{\"id\":784,\"book\":\"borg\",\"lv\":2,\"pic\":true,\"ok\":3,\"hints\":[\"Присмотрись к «подписи» свидетеля: это не имя и не закорючка.\",\"Попробуй прочесть номер буквами, а не цифрами, и не замечай тире.\"],\"short\":\"Телефонный номер на «подписи» свидетеля: если не замечать тире, он читается как слово «ЛОЖЬ».\",\"answer\":\"Внимательнее вглядитесь в телефонный номер, записанный Скабрези! Если не обращать внимания на тире, его можно прочитать как слово «ЛОЖЬ».\"},{\"id\":785,\"book\":\"borg\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Посмотри, куда был направлен взгляд Совракиса в ту минуту, когда в него попали.\",\"Айрис стоял прямо перед Совракисом. С какой стороны должен был лететь снаряд, чтобы попасть в правый висок?\"],\"short\":\"Совракис все время смотрел на Айриса, стоявшего прямо перед ним: яйцо в правый висок бросил кто-то другой.\",\"answer\":\"— Что такое?! — взревел Совракис. — Вы покрываете государственного преступника?!\\n— Вовсе нет, — кажется, Борг наслаждался возмущением виртуального демагога. — Просто он никак не мог попасть яйцом, простите, тухлым яйцом, — ехидно поправился он, — в ваш правый висок, если вы все время смотрели прямо на него. Так что бросал кто-то другой.\\n\\nЗаметив замешательство Совракиса, инспектор весело обернулся к Глуму:\\n— Пойдемте, сержант. Нам тут делать нечего. Политика, — он еще раз оглянулся на зловонное пятно на костюме Совракиса, — и впрямь очень грязное дело.\"},{\"id\":786,\"book\":\"borg\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Обрати внимание, кого, кроме самого мага, никто не видел в этой истории.\",\"Сравни таинственного посетителя в маске и пропавшего секретаря: что, если это один и тот же человек?\"],\"short\":\"Горбун в маске и был секретарём: он сам разыграл мага, а «исчезновение» с книгой — розыгрыш.\",\"answer\":\"— Откуда вы знаете? — в один голос воскликнули Глум и Глоболонго.\\n— Все очень просто. — Борг уже начал одеваться. — Ваш таинственный посетитель в маске, господин маг, и был вашим секретарем. Он просто решил разыграть вас, вот и устроил весь этот маскарад. Не сомневаюсь, что горбун уже исчез вместе с чудесной книгой, а секретарь вскоре появится и расскажет какую-нибудь мистическую байку.\\n— Точно! — ахнул потрясенный Глоболонго. — И как же я сразу не понял! И как смогли догадаться вы?!\\n— Элементарно, господин маг. Это старая психологическая задачка, описанная не только во многих учебниках, но и в одном из рассказов Честертона о патере Брауне. Читайте классику, и вы, сержант, тоже. И не расстраивайтесь — просто сегодня не ваш день. Не забывайте, что Стрелец в кульминации. По такому случаю приглашаю отведать отменного пива.\\nИ, может быть, вы понравитесь мне уже после первой кружки.\"},{\"id\":787,\"book\":\"borg\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Подумай, мог ли человек, выпивший мгновенно действующий яд, сделать то, что видно на столе.\",\"Будильник на утро и бокал, аккуратно стоящий в центре стола: можно ли так поступить, умирая мгновенно?\"],\"short\":\"Самоубийства не было: мгновенный яд не дал бы аккуратно поставить бокал и завести будильник; дядю убила племянница.\",\"answer\":\"— А с чего вы вообще взяли, что его убили? — изумился Глум, похоже, не допускавший такой версии.\\n— Все очень просто. Выпив яд, который действует мгновенно, старик не успел бы аккуратно поставить такой хрупкий бокал в центр стола. К тому же вспомните зазвонивший будильник. Можете ли вы представить себе человека, решившего покончить с собой и одновременно заводящего будильник на утро?\\n\\nЧерез час после начала перекрестного допроса племянница Фертли созналась в убийстве своего богатого дяди. Оказалось, что, недовольный ее легкомысленным поведением, он грозил лишить ее наследства и переделать завещание.\"},{\"id\":788,\"book\":\"borg\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к тому, в каких условиях, по словам Глума, писалась записка.\",\"Вспомни, при какой температуре замерзают чернила, и сравни с тем, где писали записку.\"],\"short\":\"Записка поддельная: чернила, которыми её написали на сильном морозе, должны были замерзнуть.\",\"answer\":\"Чернила в сильный мороз должны были замерзнуть.\"},{\"id\":789,\"book\":\"borg\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к тому, что написано на обложке дневника.\",\"Где водятся пингвины: на Северном полюсе или на другом конце Земли?\"],\"short\":\"Подделка: на обложке речь о Северном полюсе, а пингвины, которыми питался Шнобиле, живут в Антарктиде.\",\"answer\":\"— То есть как подделки? — побледнел Лопухнулис.\\n\\n— На обложке написано «Арктический дневник», значит, речь идет о покорении Северного полюса, — ласково сказал инспектор.\\n\\n— А пингвины живут в Антарктиде, на другом конце Земли.\"},{\"id\":790,\"book\":\"borg\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Посмотри, какие улики нашли в кабинете и кому они принадлежат.\",\"Почему Нейла, унизанная перстнями, не могла бы стрелять в перчатке, не оставив отпечатков?\"],\"short\":\"Лори стреляла и подбросила перчатку сестры: Нейла не смогла бы ни стереть отпечатки, ни стрелять в перчатке.\",\"answer\":\"— Лори? Почему вы так уверены в ее виновности? — удивился Глум.\\n\\n— Но ведь это же очевидно. На револьвере не осталось отпечатков пальцев, значит, это не самоубийство, а убийство. У Бэнга алиби, поэтому совершить преступление могли лишь сестры Кискас. Предположим, что это сделала Нейла. Тогда она либо стерла отпечатки пальцев на револьвере, но в этом случае непонятно, зачем ей перчатка, либо была в перчатках, что также исключается, поскольку ее пальцы унизаны перстнями.\\n\\nСледовательно, стреляла Лори, а затем подбросила перчатку сестры.\"},{\"id\":791,\"book\":\"borg\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Сравни два снимка: не изменилось ли что-то в одном из фанатов?\",\"Кто из фанатов на выходе стал выше, чем был на входе?\"],\"short\":\"Тот фанат, что на выходе из зала стал чуть выше, чем был на входе: он надел туфли на толстой подошве.\",\"answer\":\"— Зрение у меня прекрасное! — возмутился Глум. — Но я не вижу, на что здесь нужно смотреть!\\n\\n— На фотографии, сержант, на фотографии! Сравните их, и вы увидите, что один из фанатов при выходе из зала, где хранилась реликвия, стал чуть выше, чем был на входе. Он-то и украл бесценные туфли, а затем просто надел их на себя. Отправляйтесь за ним и дайте мне наконец спокойно пообедать…\"},{\"id\":792,\"book\":\"borg\",\"lv\":2,\"pic\":true,\"ok\":0,\"hints\":[\"Присмотрись к записке: как расставлены в ней пробелы?\",\"Сдвинь пробелы в «Вод…ая труба около Дома моды»: что получится?\"],\"short\":\"В записке сдвинуты пробелы: читается «Водосточная труба около Дома моды», значит, футляр спрятан в ней.\",\"answer\":\"Ведь если по-другому расставить пробелы в записке, получится «Вод…ая труба около Дома моды». А вся фраза будет читаться «Водосточная труба около Дома моды». Берите машину, сержант, поедем искать эту трубу.\"},{\"id\":793,\"book\":\"borg\",\"lv\":3,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к заслонке на задней крышке ящика.\",\"Что тает и исчезает без следов, если его держать в закрытом ящике и открыть заслонку?\"],\"short\":\"В ящике был сухой лед: Шпански сдавал его наглухо закрытым, а потом незаметно открывал заслонку, и лед испарялся.\",\"answer\":\"— Только сначала скажите мне, не был ли этот багажный аферист когда-нибудь связан с торговлей мороженым?\\n\\n— Как вы догадались?! — казалось, уши клерка вытянулись от удивления. — Действительно, на одной из предыдущих работ он торговал мороженым.\\n\\n— Я так и думал, — вздохнул Борг. — Хотя эта деталь совсем не обязательна. Правда, отгадка связана с мороженым, потому что я уверен, что в ящике был сухой лед. Ну да, твердый диоксид углерода, — продолжил он, видя застывшие лица обоих. — Каждый раз Шпански сдавал наглухо закрытый тяжелый ящик с сухим льдом. Затем, поскольку ящик был слишком тяжел для приемщика, сам относил его на полку и там незаметно открывал заслонку на отверстии в задней стенке. В итоге лед незаметно и бесшумно испарялся, не оставляя следов.\\n\\n— Гениально! — непонятно кого имея в виду, воскликнул представитель «Грота». — Теперь действительно все ясно, и вы получите ваши деньги. Но как же нам сейчас доказать вину Шпански и вернуть деньги?\\n\\n— Очень просто, — охотно начал объяснять инспектор, но его тут же перебил алчный Глум:\\n\\n— Это действительно очень просто, но это будет стоить еще двадцать тысяч доблей вашей компании. Ведь вы требовали лишь покончить с секретом мошенника, а не с ним самим.\\n\\nИ он широко улыбнулся обескураженному представителю компании.\"},{\"id\":794,\"book\":\"borg\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Посмотри, что было в японской комнате и чего в ней не было.\",\"Что обязательно остается после выстрела из пистолета, но не найдено в японской комнате?\"],\"short\":\"Стин Бормотелло: гильзы в японской комнате нет, значит, Фрину застрелили не там, а тело перенесли из спальни.\",\"answer\":\"— Вам, может быть, и понятно, — запротестовал Глум, — а мне нет!\\n\\n— Вы же сами видели, сержант, что комната пуста, — сказал инспектор.\\n\\n— В ней не было гильзы. Значит, стреляли не там и труп перенесли в японскую комнату из другого места, судя по одежде убитой — из спальни.\\n\\nОчевидно, для того, чтобы имитировать самоубийство.\\n\\nПосторонних в доме не было, и убийство мог совершить только хозяин особняка. Стин Бормотелло! Именем закона!…\"},{\"id\":795,\"book\":\"holmes\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к тому, в каком состоянии, по ее словам, была Сидни, когда звала на помощь.\",\"Насколько громко может крикнуть связанная женщина с кляпом во рту и услышит ли её патрульный через квартал?\"],\"short\":\"Сидни всё выдумала: связанная и с кляпом во рту она не смогла бы так громко закричать, чтобы её услышал патрульный через квартал.\",\"answer\":\"Поскольку г-жа Сидни была «беспомощна», т. к. была связана и ей «заткнули рот», то она не могла кричать настолько громко, чтобы ее услышал патрульный Кейси в квартале от ее дома.\"},{\"id\":796,\"book\":\"holmes\",\"lv\":3,\"pic\":false,\"ok\":0,\"hints\":[\"Посмотри, где именно лежат чемоданы относительно тела и в какую сторону шел поезд.\",\"Что означает, что чемоданы лежали дальше от тела по ходу поезда: кого выбросили раньше?\"],\"short\":\"Чемоданы лежали дальше тела по ходу поезда: их выбросили через несколько секунд после Уорнера, значит, его сбросили, а не он спрыгнул сам.\",\"answer\":\"Чемоданы были найдены вдали от тела на запад («в стороне заходящего солнца»), в том же направлении, куда ехал поезд из Чикаго в Лос-Анджелес.\\nСледовательно, Уорнер был выброшен из поезда первым, а его чемоданы через несколько секунд позже.\"},{\"id\":797,\"book\":\"holmes\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, что происходит с солнцем в Гренландии зимой и каким было время года в рассказе Сирила.\",\"Могло ли зимой за полярным кругом солнце светить достаточно ярко, чтобы зажечь бумагу линзой?\"],\"short\":\"Зимой за полярным кругом солнца не бывает, поэтому собрать его лучи линзой и разжечь огонь в Новый год было невозможно.\",\"answer\":\"В Новый год за Северным полярным кругом невозможно разжечь огонь от лучей солнца.\\nКаждый школьник знает, что там солнце исчезает с октября по март и наступает полярная ночь…\"},{\"id\":798,\"book\":\"borg\",\"lv\":3,\"pic\":false,\"ok\":1,\"hints\":[\"Обрати внимание, с какой стороны шеи царапина и как музыканты подстригают ногти на каждой руке.\",\"Чем отличаются ногти пианиста и гитариста и на какой руке их стригут короче всего?\"],\"short\":\"Крен Кусаки: царапина только слева, значит, у убийцы длинные ногти на правой руке, а гитаристы стригут левую коротко.\",\"answer\":\"— Совершенно ясно, что это — Крен Кусаки.\\n\\n— Почему вы сразу так решили? — изумился Глум.\\n\\n— Обратите внимание, сержант, что шея жертвы расцарапана только с левой стороны, то есть на правой руке преступника были длинные ногти.\\n\\nКак известно, гитаристы очень коротко стригут ногти на левой руке, чтобы зажимать лады, а пианисты — на обеих, чтобы чувствовать клавиши. Со стороны преступника было очень глупо не учесть эту маленькую деталь.\"},{\"id\":799,\"book\":\"holmes\",\"lv\":1,\"pic\":false,\"ok\":0,\"hints\":[\"Перечитай, что Хокинс говорил о ресторане и о том, как он туда снова попал.\",\"Сравни его слова «я никогда не был в ресторане» с тем, как он описал обратный путь туда вместе с полицейским.\"],\"short\":\"Хокинс сказал, что никогда не был в ресторане, но сам проговорился: «вернулся» в него вместе с полицейским.\",\"answer\":\"Хокинс утверждал, что никогда не слышал о ресторане и не был в нем. Если это правда, то он никогда не «вернулся» бы в него, как он сказал на допросе. Это была его фатальная оговорка!\"},{\"id\":800,\"book\":\"holmes\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к тому, откуда дул ветер в тот момент, когда чайка взлетала.\",\"Против какого ветра взлетает чайка и мог ли тот же ветер унести марку в океан?\"],\"short\":\"Ветер дул с океана, и марку не могло сдуть в воду, как говорит Мэрфи: чайка взлетала против ветра, значит, он соврал.\",\"answer\":\"Чайка взлетает против ветра, значит, полчаса назад ветер дул со стороны океана, а не наоборот. Значит, марку не могло унести в океан, как утверждал Мэрфи.\"},{\"id\":801,\"book\":\"holmes\",\"lv\":3,\"pic\":true,\"ok\":1,\"hints\":[\"Присмотрись к отпечаткам рук на мокрой земле и к тому, как близко к ним стоит бордюр.\",\"Какого роста должен быть человек, если он упал у самого бордюра, а руки оставили вмятины у края цветника?\"],\"short\":\"Хоппер: следы рук лежат у самого бордюра цветника, значит, упал человек очень маленького роста, а это жокей.\",\"answer\":\"Холмс сразу же обратил внимание на то, что отпечатки рук, четко заметные на еще не высохшей после грозы земле, расположены близко от края цветника. Следовательно, человек, который упал, споткнувшись о кирпичный бордюр, очень маленького роста. Им мог быть только жокей Хоппер.\"},{\"id\":802,\"book\":\"holmes\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к тому, с какого места Картер наблюдал за чердачным окном.\",\"Сможет ли человек внизу, у автомобиля, разглядеть табурет на полу чердака через окно на третьем этаже?\"],\"short\":\"Картер лжет: с земли через окно третьего этажа он не мог видеть табурет, а значит, не видел, как его отшвырнули.\",\"answer\":\"Арчи Картер утверждал, что видел, как Карл Месснер оттолкнул маленький табурет из-под себя. Однако, стоя на земле, Картер не мог видеть маленький табурет через чердачное окно тремя этажами выше!\"},{\"id\":803,\"book\":\"holmes\",\"lv\":3,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к подписям на чеках: бывают ли настоящие подписи одного человека полностью одинаковыми?\",\"Кто из участников экспедиции был знаком с Дольманом достаточно близко, чтобы знать подробности его жизни?\"],\"short\":\"Альваро Колес: подписи на чеках идентичны до малейших деталей, значит, их скопировали, а только близкий друг знал жизнь Дольмана.\",\"answer\":\"Слейд решил арестовать Альваро Колеса.\\nРассуждал он следующим образом: все подписи на чеках абсолютно идентичны, но действительные подписи любого человека всегда несколько разнятся одна от другой.\\nСледовательно, подписи под чеками были тщательно, до малейших деталей, скопированы с одного оригинала.\\nХарди был ростом ниже Дольмана, а Тревор был горбатым. И только капитан Колес, близкий приятель Дольмана, хорошо знавший подробности его жизни, мог выдать себя за погибшего. Тот факт, что он готовился к выезду в Южную Америку (там не всегда выдавали преступников европейским государствам), окончательно утвердил Слейда в его подозрениях.\"},{\"id\":804,\"book\":\"holmes\",\"lv\":1,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к записке: попробуй прочитать не всю фразу, а только первые буквы каждого слова.\",\"Сложи первые буквы слов записки подряд: что получится?\"],\"short\":\"Первые буквы слов записки складываются в «Меня убил Сэм, муж»: её заставили написать эти слова, а убил муж.\",\"answer\":\"Комиссар прочитал записку по первым буквам, и получилось: «Меня убил Сэм, муж».\"},{\"id\":805,\"book\":\"holmes\",\"lv\":1,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, как обычно ведет себя человек, который возвращается в собственный номер.\",\"Зачем тому, кто идет в свою комнату, стучаться в дверь?\"],\"short\":\"Незнакомец постучал, прежде чем войти: тот, кто идет в свой номер, не стучится, значит, он явился грабить.\",\"answer\":\"Если человек был уверен, что идет в свой номер, зачем он стучал в дверь?\"},{\"id\":806,\"book\":\"holmes\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, кто из четверых умеет водить машину и с кем из них никто не пойдет на дело.\",\"Кто не может водить машину, а кто ни за что не пойдет на дело вместе с Питом?\"],\"short\":\"Пита отпустил: он не в деле. Боба в первую камеру (водитель), Джека во вторую (стрелял высокий), Марка в третью.\",\"answer\":\"Он отпустил Пита, в первую камеру посадил Боба, во вторую — Джека, в третью — Марка.\"},{\"id\":807,\"book\":\"holmes\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Присмотрись к ковру в гостиной и к тому, что оставил после себя фермер в прихожей.\",\"Подумай, мог ли толстяк спрятаться за шторой у окна, где нашли пистолет и оборванные цветки герани, и остаться незамеченным.\"],\"short\":\"Ула наследил только в прихожей, ковер в гостиной чист: убийца прятался у окна за шторой, а толстяк там незаметным бы не остался.\",\"answer\":\"Улу наследил только в прихожей, а в гостиной, где обнаружили тело майора, ковер оставался белоснежным.\\n\\nУбийца же находился именно в гостиной — на это указывает найденный у окна пистолет и оборванные лепестки герани. К тому же, как неоднократно подчеркивается в рассказе, Ула был толстым человеком, а спрятаться толстяку за шторой и остаться при этом незамеченным невозможно.\"},{\"id\":808,\"book\":\"holmes\",\"lv\":3,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к разговору Микко с Юлиусом в пивной: кто что сказал и откуда он мог это знать.\",\"Юлиус назвал орудие, которого не было ни в протоколе, ни в газете. Откуда он его знал? Что Микко увидел в окне пустого дома?\"],\"short\":\"Юлиус назвал кочергу, которой не было ни в протоколе, ни в газете; Мария с любовником пряталась в пустом доме, где цвела герань.\",\"answer\":\"В разговоре с писателем Лехтоненом Юлиус Ахо сказал, что Эйно Синерво был убит кочергой, но ни в протоколе, ни в газетной статье кочерга не упоминалась. Именно она была найдена в ходе обыска в кузнице Юлиуса.\\n\\nМария Синерво пряталась со своим любовником в пустом доме аптекаря Койвисто. Лехтонен догадался об этом, когда увидел в окне заброшенного дома цветущую герань. За время отсутствия хозяина дома цветок должен был завянуть.\"},{\"id\":809,\"book\":\"holmes\",\"lv\":3,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись, как журналист описал ружьё, найденное в воде, и кто посоветовал ему нырять в этой бухте.\",\"За пятнадцать лет ружьё под водой должно было проржаветь. Почему же оно выглядело как новенькое?\"],\"short\":\"Карлос Ранжел: ружьё после пятнадцати лет в воде выглядело «как новенькое», значит, его бросили накануне.\",\"answer\":\"1. Найденное под водой ружьё было, по выражению журналиста, «как новенькое», хотя за пятнадцать лет наверняка должно было проржаветь.\\n\\n2. Это могло означать, что ружьё было брошено в воду накануне Карлосом Ранжелом, поскольку именно он посоветовал журналисту «нырять в бухте», да и в целом устроил его приезд на остров Кавиана.\\n\\n3. Карлос Ранжел рассчитывал, что журналист Жоакин Фернандо напишет статью, в которую поверит «каждый второй бразилец», его кузена Пауло арестуют по обвинению в убийстве, а он, Карлос, станет единственным владельцем всего состояния Пауло, в том числе нефтяного шельфа.\"},{\"id\":810,\"book\":\"borg\",\"lv\":3,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, как видят мир собаки, и что было в коробке с таблетками.\",\"Собаки плохо различают цвета, в отличие от людей. Что это значит для таблетки ярко-красного цвета среди других таблеток?\"],\"short\":\"Собака не различает цвета, поэтому не смогла бы найти среди разноцветных таблеток нужную красную; история выдумана.\",\"answer\":\"— Но почему? — одновременно спросили сержант и Босси.\\n\\n— Да потому, — улыбнулся инспектор, — что собака, даже самая умная, не умеет различать цвета и поэтому не может отличить красную таблетку среди кучи других таблеток разных цветов.\"},{\"id\":811,\"book\":\"holmes\",\"lv\":3,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к записи Джонса: кто с кем встречался и сколько раз.\",\"Кто встречался с мальтийцем, а потом сам обедал в «Фортуне» с Хейзом? Этот человек владеет саквояжем.\"],\"short\":\"Питерс из Мальты: по записи встреч, где ни одна пара не повторялась, вычисляются все шестеро.\",\"answer\":\"1. Хейз — охотник из Канады. 2. Клей — фотограф из Новой Зеландии. 3. Райдер — скрипач из Лондона. 4. Питерс — владелец саквояжа, из Мальты. 5. Аб Слени — менеджер из Австралии. 6. Смолл — клерк из Занзибара.\"},{\"id\":812,\"book\":\"holmes\",\"lv\":3,\"pic\":false,\"ok\":1,\"hints\":[\"Подумай, что должно было остаться на полу, если крюк забросили снаружи.\",\"Что Рютаро сказал о двери и откуда он мог это знать?\"],\"short\":\"Рютаро обмолвился, что дверь «неловко взломана», — знать это мог только вор; а стекло разбили изнутри.\",\"answer\":\"Если бы крюк забросили с соседнего здания, осколки разбитого стекла лежали бы на полу. Поскольку их не было, стекло разбили изнутри. В беседе Рютаро обмолвился, что дверь «так неловко взломана». Поскольку на этаже были только полицейские и директор, кроме них знать о том, что дверь взломана, мог только вор. Кроме того, Нобуко нашла «грязную» комнату, а разглядеть следы побелки на подошвах вора не составляло труда.\"},{\"id\":813,\"book\":\"holmes\",\"lv\":2,\"pic\":false,\"ok\":3,\"hints\":[\"Посмотри внимательно, что инспектор увидел, заглянув в гараж.\",\"Что должно было быть с гаражом, если Джонсон только что загнал в него машину?\"],\"short\":\"Гараж заперт на замок, хотя Джонсон сказал, что только что загнал в него машину: значит, он лжёт.\",\"answer\":\"Инспектор обратил внимание на то, что гараж был закрыт на замок. Если бы всё то, что рассказал Джонсон, было правдой, гараж должен был остаться открытым.\"},{\"id\":814,\"book\":\"holmes\",\"lv\":2,\"pic\":false,\"ok\":1,\"hints\":[\"Подумай, что видел детектив, когда тело ещё лежало лицом вниз.\",\"Откуда миссис Джонсон могла знать о ноже, если тело никто не переворачивал?\"],\"short\":\"Миссис Джонсон сказала, что мужа зарезали, хотя нож лежал под телом и его ещё никто не видел.\",\"answer\":\"Давая показания, миссис Джонсон сказала, что её муж был зарезан, но об этом никто не мог знать, пока не перевернули тело и не обнаружили нож и ножевые ранения на теле.\"},{\"id\":815,\"book\":\"holmes\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Присмотрись к тому, как Барлетт вошёл в дом и что стало с его очками.\",\"Что происходит с очками, если войти с мороза в тёплую комнату?\"],\"short\":\"Барлетт вошёл с мороза в тёплый дом: очки бы запотели, и без них он не разглядел бы грабителей.\",\"answer\":\"Если бы Барлетт зашёл в тёплый дом с мороза, то его очки тут же бы запотели, и он ничего не смог бы увидеть.\"},{\"id\":816,\"book\":\"holmes\",\"lv\":3,\"pic\":false,\"ok\":2,\"hints\":[\"Подумай, при каких условиях в пустыне поют пески и при каких возникает мираж.\",\"Песок поёт только при сильном ветре: что такой ветер сделал бы с миражом?\"],\"short\":\"Пески поют только при сильном ветре, а такой ветер разогнал бы испарения, и мираж был бы невозможен.\",\"answer\":\"Лорд Грэй сказал, что в момент появления миража слышалось пение песков. Но пески начинают «петь» только при достаточно сильном ветре, который в состоянии пересыпать целые струйки песка, именно их движение и создает звук, называемый «пение песков». Тогда мираж (отраженное изображение на густых испарениях влаги) не может появиться, т.к. ветер разгонит эти испарения.\"},{\"id\":817,\"book\":\"holmes\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, когда приехала милиция и что именно вызвало её приезд.\",\"Что включает сигнализацию магазина, и успели бы грабители возиться у закрытой двери до её срабатывания?\"],\"short\":\"Сигнализация срабатывает при открывании двери, а «свидетель» видел, как грабители возились у закрытой двери.\",\"answer\":\"Со слов «свидетеля» в тот момент, когда грабители пытались открыть дверь магазина, приехала милиция. Но милиция выехала тогда, когда в магазине сработала сигнализация, а она срабатывает при открывании дверей. А свидетель утверждает, что преступники возились возле закрытой двери. Следовательно, свидетель лжёт.\"},{\"id\":818,\"book\":\"holmes\",\"lv\":2,\"pic\":false,\"ok\":0,\"hints\":[\"Подумай, как и в каком порядке замерзает вода в луже.\",\"Что замерзает первым: края лужи или её середина?\"],\"short\":\"Лёд на луже нарастает от берега, а не с середины: значит, находка посреди льдины — выдумка горничной.\",\"answer\":\"Лужи начинают покрываться льдом с берега, а не с середины лужи, как это следует из рассказа горничной.\"},{\"id\":819,\"book\":\"holmes\",\"lv\":2,\"pic\":false,\"ok\":2,\"hints\":[\"Присмотрись к тому, какие очки носит профессор и для чего они ему нужны.\",\"Какие очки собирают солнечный свет, а какие его рассеивают?\"],\"short\":\"Очки профессора близорукие, их стёкла рассеивают свет, поэтому сжечь бумагу ими нельзя.\",\"answer\":\"Профессор носит очки постоянно, а при чтении они ему мешают. Значит, он близорук, а стёкла его очков — не собирающие, а рассеивающие. Сфокусировать солнечный свет и зажечь бумагу с их помощью невозможно.\"},{\"id\":820,\"book\":\"holmes\",\"lv\":3,\"pic\":false,\"ok\":3,\"hints\":[\"Присмотрись к тому, где в тот момент находилось солнце и где могла быть радуга.\",\"Радуга всегда лежит напротив солнца. Где относительно водителя «Москвича» должна быть радуга, если солнце светит ему в спину?\"],\"short\":\"Водитель «Москвича»: радуга видна только при солнце за спиной наблюдателя, а справа от него её быть не могло — он врёт.\",\"answer\":\"Радугу можно увидеть, если солнце располагается за спиной наблюдателя. Справа от водителя «Москвича» ее быть никак не могло.\"}]");
export default KEY;
